const resolveAppVersion = () => {
    const pkgVersion = resolvePackageVersion();

    try {
        const stamped = fsSync.readFileSync(path.join(process.cwd(), 'version.txt'), 'utf8').trim();
        // Prefer stamped build when present; strip stale major.minor if package/floor moved on.
        const match = stamped.match(/^v(\d+\.\d+\.\d+)(?:-(.+))?$/i);
        if (match) {
            const stampedPkg = match[1];
            const stampedSha = match[2] || '';
            if (stampedPkg === pkgVersion) return stamped;
            // Rebuild with current package version but keep the build SHA suffix when possible.
            if (stampedSha) return `v${pkgVersion}-${stampedSha}`;
        }
    } catch {
        // version.txt missing — rebuild below
    }

    const isTag = process.env.GITHUB_REF && String(process.env.GITHUB_REF).startsWith('refs/tags/');
    try {
        const gitHash = execSync('git rev-parse --short HEAD', { stdio: 'pipe' }).toString().trim();
        return isTag ? `v${pkgVersion}` : `v${pkgVersion}-${gitHash}`;
    } catch {
        return `v${pkgVersion}`;
    }
};

const appVersion = resolveAppVersion();

/** Plex session bandwidth is usually Kbps, but transcodes can report bps — normalize to Kbps. */
const normalizePlexBandwidthKbps = (raw) => {
    const n = Number(raw) || 0;
    if (!n) return 0;
    // >500 Mbps in Kbps is unrealistic for Plex; treat as bps misreport (e.g. 10_000_000 bps → 10 Mbps).
    if (n > 500_000) return Math.round(n / 1000);
    return Math.round(n);
};

const app = express();
app.use(compression({
    // Lower zlib window than the default (8) so concurrent gzip streams stay small.
    level: 4,
    memLevel: 5,
    threshold: 1024,
    filter: (req, res) => {
        // Speed tests must stay uncompressed — gzip of repetitive payloads skews Mbps badly.
        const url = String(req.originalUrl || req.url || '');
        if (shouldSkipGzipForUrl(url)) return false;
        // Embed proxy streams large JS/CSS/image payloads; compressing them duplicates buffers in RAM.
        if (isPortalEmbedProxyPath(url)) return false;
        const pathOnly = url.split('?')[0];
        if (isLeakedArrEmbedAssetPath(pathOnly)) return false;
        if (isLeakedSpotifyToPlexEmbedAssetPath(pathOnly)) return false;
        return compression.filter(req, res);
    },
}));
const PORT = parseInt(process.env.PORT || '2121', 10);
const BIND_HOST = process.env.BIND_HOST || '0.0.0.0';
const SETUP_TOKEN = process.env.SETUP_TOKEN || '';
const ALLOW_PRIVATE_INTEGRATION_URLS = String(process.env.ALLOW_PRIVATE_INTEGRATION_URLS || '').toLowerCase() === 'true';
const FORCE_SECURE_COOKIES = String(process.env.FORCE_SECURE_COOKIES || '').toLowerCase() === 'true';
const PUBLIC_BASE_URL = process.env.PUBLIC_BASE_URL || '';

/** Normalize a public portal URL (no trailing slash). Returns '' if invalid/empty. */
const normalizePublicBaseUrl = (raw = '') => {
    const value = String(raw || '').trim().replace(/\/+$/, '');
    if (!value) return '';
    try {
        return new URL(value).toString().replace(/\/+$/, '');
    } catch {
        return '';
    }
};

const getEnvPublicBaseUrl = () => normalizePublicBaseUrl(PUBLIC_BASE_URL);

/**
 * Prefer Portal UI "Public Base URL" (config.publicDomain), then PUBLIC_BASE_URL env.
 * Used for invite emails, newsletter links, OG tags, and CSRF allowed origins.
 */
const resolvePublicBaseUrlFromConfig = (config = {}) => (
    normalizePublicBaseUrl(config?.publicDomain) || getEnvPublicBaseUrl()
);

/** Hot-updated when settings save so CSRF / sync helpers see the UI value. */
let runtimePublicBaseUrl = getEnvPublicBaseUrl();

const refreshRuntimePublicBaseUrl = (config = {}) => {
    runtimePublicBaseUrl = resolvePublicBaseUrlFromConfig(config) || getEnvPublicBaseUrl();
    return runtimePublicBaseUrl;
};

const normalizeBasePath = (raw = '') => {
    const value = String(raw || '').trim();
    if (!value || value === '/') return '';
    const withLeading = value.startsWith('/') ? value : `/${value}`;
    return withLeading.replace(/\/+$/, '');
};

const deriveBasePath = () => {
    if (process.env.BASE_PATH != null && String(process.env.BASE_PATH).trim() !== '') {
        return normalizeBasePath(process.env.BASE_PATH);
    }
    if (PUBLIC_BASE_URL) {
        try {
            return normalizeBasePath(new URL(PUBLIC_BASE_URL).pathname);
        } catch (_) { /* fall through */ }
    }
    return '';
};

const BASE_PATH = deriveBasePath();

const withBasePath = (route = '/') => {
    const path = route.startsWith('/') ? route : `/${route}`;
    return BASE_PATH ? `${BASE_PATH}${path}` : path;
};

const plexImageUrl = (mediaPath) => withBasePath(`/api/plex/image?path=${encodeURIComponent(mediaPath)}`);
/** Poster-sized transcode so home cards are not stretched from tiny history thumbs. */
const PLEX_POSTER_WIDTH = 600;
const PLEX_POSTER_HEIGHT = 900;
const PLEX_IMAGE_MAX_WIDTH = 3840;
const PLEX_IMAGE_MAX_HEIGHT = 2160;
const plexPosterUrl = (mediaPath) => {
    if (!mediaPath) return null;
    return withBasePath(
        `/api/plex/image?path=${encodeURIComponent(mediaPath)}&width=${PLEX_POSTER_WIDTH}&height=${PLEX_POSTER_HEIGHT}`,
    );
};

const stripBasePathFromUrl = (url = '/') => {
    const [pathname, ...queryParts] = String(url).split('?');
    const query = queryParts.length ? `?${queryParts.join('?')}` : '';
    if (!BASE_PATH) return url;
    if (pathname === BASE_PATH || pathname === `${BASE_PATH}/`) {
        return `/${query}`;
    }
    if (pathname.startsWith(`${BASE_PATH}/`)) {
        const rest = pathname.slice(BASE_PATH.length) || '/';
        return `${rest}${query}`;
    }
    return url;
};

// Sentinel sent to the admin UI in place of stored secrets so raw credentials
// never leave the server. When the UI posts this value back unchanged on save,
// the existing stored secret is preserved instead of being overwritten.
const SECRET_MASK = '\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022';

const mediaAutomationWatchOptIn = () => String(process.env.MEDIA_AUTOMATION_ENABLE_WATCH || '').trim() === '1';

const mediaAutomationRuntimeConfig = (config = {}) => {
    const raw = config.mediaAutomation && typeof config.mediaAutomation === 'object'
        ? config.mediaAutomation
        : {};
    // Settings UI writes Safe fallback to fallback.outputMode — prefer that over a stale top-level value.
    const outputMode = String(raw.fallback?.outputMode || raw.outputMode || 'dry-run').toLowerCase();
    // Recursive watches on large Unraid/remote mounts can wedge the whole portal.
    // Require explicit env opt-in before the filesystem watcher may start.
    const libraryWatchEnabled = mediaAutomationWatchOptIn() && raw.libraryWatchEnabled === true;
    return normalizeMediaAutomationConfig({
        ...raw,
        enabled: !!config.mediaAutomationEnabled,
        dryRun: outputMode === 'dry-run',
        cpuConcurrency: raw.concurrency?.cpu ?? raw.cpuConcurrency,
        gpuConcurrency: raw.concurrency?.gpu ?? raw.gpuConcurrency,
        hardwareAcceleration: raw.fallback?.hardware || raw.hardwareAcceleration || 'auto',
        outputMode,
        libraryWatchEnabled,
    }, getDefaultMediaAutomationConfig());
};

const mediaAutomationConfigForApi = (config = {}) => {
    const runtime = mediaAutomationRuntimeConfig(config);
    const auth = config.mediaAutomation?.auth && typeof config.mediaAutomation.auth === 'object'
        ? config.mediaAutomation.auth
        : {};
    return {
        ...runtime,
        enabled: !!config.mediaAutomationEnabled,
        watchEnvEnabled: mediaAutomationWatchOptIn(),
        libraryWatchConfigured: config.mediaAutomation?.libraryWatchEnabled === true,
        notifyOnJobFailed: runtime.notifyOnJobFailed === true,
        notifyOnScanComplete: runtime.notifyOnScanComplete === true,
        notifyOnFailBurst: runtime.notifyOnFailBurst === true,
        minFreeDiskGb: runtime.minFreeDiskGb ?? 20,
        autoPauseQueueDepth: runtime.autoPauseQueueDepth || 0,
        pathDenyList: Array.isArray(runtime.pathDenyList) ? runtime.pathDenyList : [],
        quietHoursEnabled: runtime.quietHoursEnabled === true,
        quietHoursStart: runtime.quietHoursStart,
        quietHoursEnd: runtime.quietHoursEnd,
        quietHoursDays: Array.isArray(runtime.quietHoursDays) ? runtime.quietHoursDays : [],
        workerGroups: Array.isArray(runtime.workerGroups) ? runtime.workerGroups : [],
        deliveryTargets: Array.isArray(runtime.deliveryTargets) ? runtime.deliveryTargets : [],
        auth: {
            username: String(auth.username || ''),
            password: auth.password ? SECRET_MASK : '',
        },
        concurrency: {
            cpu: runtime.cpuConcurrency,
            gpu: runtime.gpuConcurrency,
        },
        fallback: {
            hardware: runtime.hardwareAcceleration,
            outputMode: runtime.outputMode,
        },
    };
};

const MEDIA_AUTOMATION_RULE_FIELDS = new Set([
    'path', 'container', 'videoCodec', 'audioCodec', 'width', 'bitrate', 'hdr',
]);
const MEDIA_AUTOMATION_RULE_OPERATORS = new Set([
    'equals', 'notEquals', 'contains', 'matches', 'greaterThan', 'lessThan',
]);

const normalizeMediaAutomationRuleGroup = (value) => {
    const source = value && typeof value === 'object' ? value : {};
    const operator = String(source.operator || 'AND').toUpperCase() === 'OR' ? 'OR' : 'AND';
    const conditions = (Array.isArray(source.conditions) ? source.conditions : [])
        .slice(0, 50)
        .map((condition) => {
            const field = String(condition?.field || '');
            const comparison = String(condition?.operator || 'equals');
            if (!MEDIA_AUTOMATION_RULE_FIELDS.has(field) || !MEDIA_AUTOMATION_RULE_OPERATORS.has(comparison)) {
                return null;
            }
            return {
                id: String(condition?.id || randomUUID()),
                field,
                operator: comparison,
                value: String(condition?.value ?? '').slice(0, 500),
            };
        })
        .filter(Boolean);
    return { operator, conditions };
};

const MEDIA_AUTOMATION_STEP_TYPES = new Set([
    'transcode',
    'remux',
    'subtitle-strip',
    'subtitle-extract',
    'subtitle-keep-lang',
    'keep-first-audio',
    'drop-commentary',
    'audio-normalize',
    'audio-stereo',
    'commercial-strip',
    'move',
    'custom-command',
]);

const normalizeMediaAutomationStep = (value = {}) => {
    const rawType = String(value.type || value.mode || 'transcode').toLowerCase();
    const type = MEDIA_AUTOMATION_STEP_TYPES.has(rawType) ? rawType : 'transcode';
    const videoCodec = ['h264', 'hevc', 'av1', 'copy'].includes(String(value.videoCodec || '').toLowerCase())
        ? String(value.videoCodec).toLowerCase()
        : 'hevc';
    const audioCodec = ['copy', 'aac', 'ac3', 'eac3', 'libopus', 'flac'].includes(String(value.audioCodec || '').toLowerCase())
        ? String(value.audioCodec).toLowerCase()
        : 'copy';
    const subtitleCodec = ['copy', 'drop', 'srt', 'webvtt'].includes(String(value.subtitleCodec || '').toLowerCase())
        ? String(value.subtitleCodec).toLowerCase()
        : 'copy';
    const args = Array.isArray(value.args)
        ? value.args.map((entry) => String(entry || '').slice(0, 500)).filter(Boolean).slice(0, 64)
        : [];
    const subtitleLanguages = String(value.subtitleLanguages || value.languages || '')
        .split(/[,\s]+/)
        .map((entry) => entry.trim().toLowerCase())
        .filter((entry) => /^[a-z]{2,3}$/.test(entry))
        .slice(0, 12)
        .join(',');
    let commercialPattern = String(value.commercialPattern || '').trim().slice(0, 200);
    if (commercialPattern) {
        try {
            RegExp(commercialPattern, 'i');
        } catch {
            commercialPattern = '';
        }
    }
    return {
        type,
        container: ['mkv', 'mp4'].includes(String(value.container || '').toLowerCase())
            ? String(value.container).toLowerCase()
            : 'mkv',
        videoCodec,
        audioCodec,
        subtitleCodec,
        audioBitrateKbps: Math.min(1536, Math.max(32, Number(value.audioBitrateKbps) || 192)),
        // 0 = quality mode (CRF/CQ). >0 = fixed video bitrate (kbps).
        videoBitrateKbps: (() => {
            const number = Number(value.videoBitrateKbps);
            if (!Number.isFinite(number) || number <= 0) return 0;
            return Math.min(100000, Math.max(100, Math.round(number)));
        })(),
        maxWidth: Math.max(0, Math.min(7680, Number(value.maxWidth) || 0)),
        preset: String(value.preset || 'medium').slice(0, 32),
        crf: Math.min(51, Math.max(0, Number.isFinite(Number(value.crf)) ? Math.round(Number(value.crf)) : 20)),
        destination: String(value.destination || value.destinationTemplate || '').trim().slice(0, 500),
        executable: String(value.executable || value.command || '').trim().slice(0, 260),
        args,
        skipMediaFinalize: !!value.skipMediaFinalize,
        subtitleLanguages,
        keepSubtitles: value.keepSubtitles !== false,
        commercialPattern,
        tenBit: value.tenBit === true || Number(value.bitDepth) === 10,
    };
};

const normalizeMediaAutomationPipelineInput = (value = {}, id) => {
    const name = String(value.name || '').trim().slice(0, 120);
    if (!name) throw Object.assign(new Error('Pipeline name is required'), { status: 400 });
    const pipelineId = String(id || value.id || randomUUID());
    const outputMode = ['dry-run', 'copy', 'replace'].includes(String(value.outputMode || '').toLowerCase())
        ? String(value.outputMode).toLowerCase()
        : 'dry-run';
    const hardware = ['auto', 'cpu', 'nvenc', 'qsv', 'intel-vaapi', 'vaapi'].includes(String(value.hardware || '').toLowerCase())
        ? String(value.hardware).toLowerCase()
        : 'auto';
    const steps = (Array.isArray(value.steps) ? value.steps : [])
        .slice(0, 10)
        .map(normalizeMediaAutomationStep);
    if (!steps.length) steps.push(normalizeMediaAutomationStep());
    const ruleGroup = normalizeMediaAutomationRuleGroup(value.rules);
    const firstStep = steps[0];
    const dolbyVisionHandling = ['skip', 'preserve', 'strip', 'inherit'].includes(String(value.dolbyVisionHandling || '').toLowerCase())
        ? String(value.dolbyVisionHandling).toLowerCase()
        : 'inherit';
    const hdr10Handling = ['preserve', 'strip', 'skip', 'inherit'].includes(String(value.hdr10Handling || '').toLowerCase())
        ? String(value.hdr10Handling).toLowerCase()
        : 'inherit';
    const minSavingsRaw = value.minSavingsPercent;
    let minSavingsPercent = null;
    if (minSavingsRaw != null && minSavingsRaw !== '') {
        if (String(minSavingsRaw).toLowerCase() === 'inherit') {
            minSavingsPercent = 'inherit';
        } else {
            const parsed = Number(minSavingsRaw);
            minSavingsPercent = Number.isFinite(parsed)
                ? Math.min(95, Math.max(0, Math.round(parsed)))
                : null;
        }
    }
    const action = {
        mode: firstStep.type,
        videoCodec: firstStep.videoCodec,
        audioCodec: firstStep.audioCodec,
        subtitleCodec: firstStep.subtitleCodec,
        audioBitrateKbps: firstStep.audioBitrateKbps,
        videoBitrateKbps: firstStep.videoBitrateKbps,
        maxWidth: firstStep.maxWidth,
        preset: firstStep.preset,
        crf: firstStep.crf,
        tenBit: firstStep.tenBit === true,
        outputExtension: `.${firstStep.container}`,
        outputMode,
        hardwareAcceleration: hardware,
    };
    const samplePathRaw = String(value.samplePath || value.testPath || '').trim();
    const samplePath = samplePathRaw
        && path.isAbsolute(samplePathRaw)
        && !samplePathRaw.includes('\0')
        && samplePathRaw.length <= 1000
        ? samplePathRaw
        : '';
    return {
        id: pipelineId,
        name,
        enabled: value.enabled !== false,
        priority: Math.max(-1000, Math.min(1000, Number(value.priority) || 0)),
        outputMode,
        hardware,
        samplePath,
        dolbyVisionHandling,
        hdr10Handling,
        minSavingsPercent,
        rules: ruleGroup,
        steps,
        compiledRules: [{
            id: `pipeline:${pipelineId}`,
            pipelineId,
            enabled: value.enabled !== false,
            priority: Math.max(-1000, Math.min(1000, Number(value.priority) || 0)),
            conditionGroup: ruleGroup,
            then: action,
        }],
    };
};

const normalizeMediaAutomationLibraryInput = (value = {}, id) => {
    const name = String(value.name || '').trim().slice(0, 120);
    const rootPath = String(value.rootPath || '').trim();
    if (!name) throw Object.assign(new Error('Library name is required'), { status: 400 });
    if (!rootPath || !path.isAbsolute(rootPath)) {
        throw Object.assign(new Error('Library root must be an absolute container path'), { status: 400 });
    }
    const outputPath = String(value.outputPath || '').trim();
    const quarantinePath = String(value.quarantinePath || '').trim();
    if (outputPath && !path.isAbsolute(outputPath)) {
        throw Object.assign(new Error('Library output path must be absolute'), { status: 400 });
    }
    if (quarantinePath && !path.isAbsolute(quarantinePath)) {
        throw Object.assign(new Error('Library quarantine path must be absolute'), { status: 400 });
    }
    return {
        id: String(id || value.id || randomUUID()),
        name,
        rootPath,
        outputPath,
        quarantinePath,
        enabled: value.enabled !== false,
        pipelineId: value.pipelineId ? String(value.pipelineId) : null,
        hardware: ['auto', 'cpu', 'nvenc', 'qsv', 'intel-vaapi', 'vaapi'].includes(String(value.hardware || '').toLowerCase())
            ? String(value.hardware).toLowerCase()
            : '',
        outputMode: ['dry-run', 'copy', 'replace'].includes(String(value.outputMode || '').toLowerCase())
            ? String(value.outputMode).toLowerCase()
            : '',
        priorityBoost: Math.max(0, Math.min(999, Number(value.priorityBoost) || 0)),
        tags: [...new Set(
            (Array.isArray(value.tags) ? value.tags : String(value.tags || '').split(/[,\s]+/))
                .map((entry) => String(entry || '').trim().toLowerCase())
                .filter((entry) => entry && entry.length <= 40)
                .slice(0, 24),
        )],
        deliveryTargetId: value.deliveryTargetId ? String(value.deliveryTargetId) : null,
    };
};

// --- Security: JWT secret must be explicitly set in the environment ---
const JWT_SECRET = process.env.JWT_SECRET;
if (!JWT_SECRET || JWT_SECRET.length < 32) {
    console.error('FATAL: JWT_SECRET environment variable must be set and at least 32 characters long.');
    console.error('Set it in a .env file or your process environment before starting the server.');
    process.exit(1);
}

let CLIENT_ID = process.env.CLIENT_ID || 'plex-expiry-manager-client-id'; // Now dynamically generated if missing

const portalFrameSrcDirective = (hostname = '') => {
    const sources = ["'self'", 'https://www.openstreetmap.org'];
    const base = registrableDomainFromHost(hostname);
    if (base && String(hostname || '').includes('.')) {
        sources.push(`https://*.${base}`);
    }
    return `frame-src ${sources.join(' ')}`;
};

const portalContentSecurityPolicy = (hostname = '', embedProxy = false) => {
    if (embedProxy) return "frame-ancestors 'self'; object-src 'none'";
    return [
        "default-src 'self'",
        "script-src 'self'",
        "style-src 'self' 'unsafe-inline' https://fonts.googleapis.com",
        "img-src 'self' data: blob: https:",
        "font-src 'self' data: https://fonts.gstatic.com",
        "connect-src 'self'",
        "media-src 'self' blob:",
        portalFrameSrcDirective(hostname),
        "manifest-src 'self'",
        "worker-src 'self' blob:",
        "frame-ancestors 'none'",
        "object-src 'none'",
        "base-uri 'self'",
        "form-action 'self'",
    ].join('; ');
};

// --- Security: HTTP Security Headers ---
app.use((req, res, next) => {
    res.setHeader('X-Content-Type-Options', 'nosniff');
    // Embed proxy responses are framed by the portal itself. DENY / frame-ancestors 'none'
    // makes Chrome show "portal.example refused to connect" in the iframe.
    const embedProxy = isPortalEmbedProxyPath(req.path);
    res.setHeader('X-Frame-Options', embedProxy ? 'SAMEORIGIN' : 'DENY');
    res.setHeader('X-XSS-Protection', '1; mode=block');
    res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
    res.setHeader('Permissions-Policy', 'camera=(), microphone=(), geolocation=()');
    res.setHeader(
        'Content-Security-Policy',
        portalContentSecurityPolicy(req.hostname, embedProxy),
    );
    if (requestIsHttps(req) || FORCE_SECURE_COOKIES) {
        res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
    }
    if (req.path.startsWith('/api/')) {
        res.setHeader('Cache-Control', 'no-store, private');
        res.setHeader('Pragma', 'no-cache');
    }
    next();
});

// --- Security: Rate Limiting for Auth Endpoints ---
// Prefer the TCP peer address so client-supplied X-Forwarded-For cannot bypass limits
// unless TRUST_PROXY is explicitly enabled for a real reverse-proxy deployment.
const TRUST_PROXY_FOR_RATE_LIMIT = ['1', 'true', 'yes'].includes(String(process.env.TRUST_PROXY || '').toLowerCase());
const getSocketPeerIp = (req) => (req.socket && req.socket.remoteAddress) || 'unknown';
const getClientIp = (req) => {
    if (TRUST_PROXY_FOR_RATE_LIMIT) {
        return req.ip || getSocketPeerIp(req) || 'unknown';
    }
    return getSocketPeerIp(req);
};
const createRateLimiter = (windowMs, maxRequests) => {
    const store = new Map();
    // Prune stale IP entries every window to prevent unbounded memory growth under high unique-IP load
    setInterval(() => {
        const now = Date.now();
        store.forEach((record, ip) => { if (now > record.resetAt) store.delete(ip); });
    }, windowMs).unref();
    return (req, res, next) => {
        const ip = getClientIp(req);
        const now = Date.now();
        const record = store.get(ip) || { count: 0, resetAt: now + windowMs };
        if (now > record.resetAt) {
            record.count = 0;
            record.resetAt = now + windowMs;
        }
        record.count++;
        store.set(ip, record);
        if (record.count > maxRequests) {
            return res.status(429).json({ error: 'Too many requests. Please try again later.' });
        }
        next();
    };
};
const authRateLimit = createRateLimiter(15 * 60 * 1000, 10); // Reduced from 20 — tighter brute-force window
const authCallbackRateLimit = createRateLimiter(15 * 60 * 1000, 40);
const jellyfinQuickConnectPollRateLimit = createRateLimiter(5 * 60 * 1000, 140);
const publicReadRateLimit = createRateLimiter(60 * 1000, 120);
const speedtestRateLimit = createRateLimiter(60 * 1000, 20);
const setupRateLimit = createRateLimiter(15 * 60 * 1000, 30);
const scannerTriggerRateLimit = createRateLimiter(15 * 60 * 1000, 60);
const mediaAutomationTriggerRateLimit = createRateLimiter(15 * 60 * 1000, 60);

/** Strip secrets that must never leave the server in user JSON responses. */
const sanitizeUserForApi = (user) => {
    if (!user || typeof user !== 'object') return user;
    const { plexAuthToken, ...safe } = user;
    return safe;
};
const sanitizeUsersForApi = (users) => (Array.isArray(users) ? users.map(sanitizeUserForApi) : users);

/** AES-GCM envelope for member Plex tokens stored in users.json (never return via API). */
const PLEX_TOKEN_ENC_PREFIX = 'enc:v1:';
const getPlexTokenEncryptionKey = () => createHash('sha256')
    .update(`plex-user-token:v1:${String(JWT_SECRET)}`)
    .digest();

const encryptPlexAuthToken = (plaintext) => {
    const raw = String(plaintext || '').trim();
    if (!raw) return '';
    if (raw.startsWith(PLEX_TOKEN_ENC_PREFIX)) return raw;
    const iv = randomBytes(12);
    const cipher = createCipheriv('aes-256-gcm', getPlexTokenEncryptionKey(), iv);
    const ciphertext = Buffer.concat([cipher.update(Buffer.from(raw, 'utf8')), cipher.final()]);
    const tag = cipher.getAuthTag();
    return [
        PLEX_TOKEN_ENC_PREFIX.slice(0, -1), // enc:v1
        iv.toString('base64url'),
        tag.toString('base64url'),
        ciphertext.toString('base64url'),
    ].join(':');
};

const decryptPlexAuthToken = (stored) => {
    const raw = String(stored || '').trim();
    if (!raw) return null;
    if (!raw.startsWith(PLEX_TOKEN_ENC_PREFIX)) return raw; // legacy plaintext
    const parts = raw.split(':');
    // enc:v1:<iv>:<tag>:<ciphertext>
    if (parts.length !== 5 || parts[0] !== 'enc' || parts[1] !== 'v1') return null;
    try {
        const iv = Buffer.from(parts[2], 'base64url');
        const tag = Buffer.from(parts[3], 'base64url');
        const ciphertext = Buffer.from(parts[4], 'base64url');
        const decipher = createDecipheriv('aes-256-gcm', getPlexTokenEncryptionKey(), iv);
        decipher.setAuthTag(tag);
        return Buffer.concat([decipher.update(ciphertext), decipher.final()]).toString('utf8');
    } catch {
        return null;
    }
};

/** One-shot upgrade of legacy plaintext plexAuthToken values in users.json. */
const migratePlexAuthTokensAtRest = async () => {
    const users = await loadFile(USERS_PATH, []);
    if (!Array.isArray(users) || !users.length) return 0;
    let changed = 0;
    for (const user of users) {
        const raw = String(user?.plexAuthToken || '').trim();
        if (!raw || raw.startsWith(PLEX_TOKEN_ENC_PREFIX)) continue;
        user.plexAuthToken = encryptPlexAuthToken(raw);
        changed += 1;
    }
    if (changed) await saveFile(USERS_PATH, users);
    return changed;
};

const isLoopbackAddress = (ip = '') => {
    const normalizedIp = String(ip || '').replace('::ffff:', '').toLowerCase();
    return normalizedIp === '127.0.0.1' || normalizedIp === '::1' || normalizedIp === 'localhost';
};

const hasValidSetupToken = (req) => {
    if (!SETUP_TOKEN) return false;
    const provided = req.headers['x-setup-token'] || req.body?.setupToken || req.query?.setupToken;
    return typeof provided === 'string' && provided === SETUP_TOKEN;
};

// Use the raw TCP peer address for setup authorization. req.ip honors the
// client-supplied X-Forwarded-For header (trust proxy is enabled), which an
// attacker could spoof to impersonate localhost during the unconfigured window.
const canRunInitialSetup = (req) => hasValidSetupToken(req) || isLoopbackAddress(getSocketPeerIp(req));

const normalizeHostnameForIpCheck = (hostname = '') => {
    let host = String(hostname || '').trim().toLowerCase();
    if (host.startsWith('[') && host.endsWith(']')) host = host.slice(1, -1);
    const zone = host.indexOf('%');
    if (zone !== -1) host = host.slice(0, zone);
    return host;
};

const isPrivateIp = (host) => {
    const h = normalizeHostnameForIpCheck(host);
    if (!h) return false;
    if (h === '0.0.0.0' || h === '::' || h === '::0') return true;
    if (h.startsWith('::ffff:')) return isPrivateIp(h.slice('::ffff:'.length));
    if (!net.isIP(h)) return false;
    if (net.isIPv4(h)) {
        if (h === '127.0.0.1' || h.startsWith('127.')) return true;
        if (h.startsWith('10.') || h.startsWith('192.168.') || h.startsWith('169.254.')) return true;
        if (/^172\.(1[6-9]|2\d|3[0-1])\./.test(h)) return true;
        return false;
    }
    // IPv6: loopback, ULA (fc00::/7), link-local (fe80::/10)
    if (h === '::1') return true;
    if (/^f[cd]/i.test(h)) return true;
    if (/^fe[89ab]/i.test(h)) return true;
    return false;
};

const isLoopbackHostName = (hostname = '') => {
    const host = normalizeHostnameForIpCheck(hostname);
    return host === 'localhost' || host === '127.0.0.1' || host === '::1' || host.startsWith('127.');
};

const isBlockedHostName = (hostname = '') => {
    const host = normalizeHostnameForIpCheck(hostname);
    if (!host) return true;
    if (host === 'localhost' || host.endsWith('.localhost')) return true;
    if (host.endsWith('.local') || host.endsWith('.internal') || host.endsWith('.lan')) return true;
    if (isPrivateIp(host)) return true;
    return false;
};

/** DNS rebinding guard: require resolved addresses stay non-private when policy forbids LAN. */
const assertResolvedAddressesAllowed = async (hostname, { allowPrivate = false } = {}) => {
    const host = normalizeHostnameForIpCheck(hostname);
    if (!host) throw new Error('Invalid host');
    if (net.isIP(host)) {
        if (!allowPrivate && isPrivateIp(host)) {
            throw new Error('Private or local network hosts are not allowed. Set ALLOW_PRIVATE_INTEGRATION_URLS=true in your environment to allow LAN/private URLs.');
        }
        return;
    }
    let addresses;
    try {
        addresses = await dns.lookup(host, { all: true, verbatim: true });
    } catch {
        throw new Error(`Unable to resolve host: ${host}`);
    }
    if (!Array.isArray(addresses) || !addresses.length) {
        throw new Error(`Unable to resolve host: ${host}`);
    }
    if (allowPrivate) return;
    for (const entry of addresses) {
        const address = entry?.address || entry;
        if (isPrivateIp(address) || isBlockedHostName(address)) {
            throw new Error('Host resolves to a private or local network address. Set ALLOW_PRIVATE_INTEGRATION_URLS=true to allow LAN/private URLs.');
        }
    }
};

const assertHttpUrlAllowed = async (rawUrl, { allowPrivate = false } = {}) => {
    const normalized = normalizeExternalBaseUrl(rawUrl, { allowPrivate, allowHttp: true });
    const parsed = new URL(normalized);
    await assertResolvedAddressesAllowed(parsed.hostname, { allowPrivate });
    return normalized;
};

/** Fetch Arr poster/screenshot remotes without SSRF into private networks. */
const resolveSafeArrRemoteImageUrl = async (remoteUrl, arrBase) => {
    if (!remoteUrl) return null;
    const raw = String(remoteUrl).trim();
    let absolute;
    if (/^https?:\/\//i.test(raw)) {
        absolute = raw;
    } else {
        const base = String(arrBase || '').replace(/\/+$/, '');
        if (!base) return null;
        absolute = `${base}${raw.startsWith('/') ? '' : '/'}${raw}`;
    }
    let parsed;
    try {
        parsed = new URL(absolute);
    } catch {
        return null;
    }
    if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') return null;
    parsed.hash = '';
    parsed.username = '';
    parsed.password = '';

    let arrHost = '';
    try {
        arrHost = normalizeHostnameForIpCheck(new URL(arrBase).hostname);
    } catch {
        arrHost = '';
    }
    const host = normalizeHostnameForIpCheck(parsed.hostname);
    if (arrHost && host === arrHost) return parsed.toString();

    // Third-party art CDNs must not resolve into RFC1918 / loopback.
    await assertResolvedAddressesAllowed(host, { allowPrivate: false });
    return parsed.toString();
};

const normalizeExternalBaseUrl = (rawUrl, { allowPrivate = false, allowHttp = true } = {}) => {
    if (!rawUrl) return '';
    let parsed;
    try {
        parsed = new URL(String(rawUrl).trim());
    } catch (e) {
        throw new Error('Invalid URL format');
    }
    const isHttps = parsed.protocol === 'https:';
    const isHttp = parsed.protocol === 'http:';
    if (!isHttps && !(allowHttp && isHttp)) {
        throw new Error('URL must use http or https');
    }
    if (!allowPrivate && isBlockedHostName(parsed.hostname)) {
        throw new Error('Private or local network hosts are not allowed. Set ALLOW_PRIVATE_INTEGRATION_URLS=true in your environment to allow LAN/private URLs.');
    }
    parsed.hash = '';
    parsed.search = '';
    return parsed.toString().replace(/\/+$/, '');
};

const sanitizeIntegrationUrl = (rawUrl) => {
    if (!rawUrl) return '';
    return normalizeExternalBaseUrl(rawUrl, { allowPrivate: ALLOW_PRIVATE_INTEGRATION_URLS, allowHttp: true });
};

/** Hostname + DNS-rebinding checks for URLs newly typed into Settings / setup tests. */
const sanitizeNewlySubmittedIntegrationUrl = async (rawUrl) => {
    const normalized = sanitizeIntegrationUrl(rawUrl);
    if (!normalized) return '';
    await assertResolvedAddressesAllowed(new URL(normalized).hostname, {
        allowPrivate: ALLOW_PRIVATE_INTEGRATION_URLS,
    });
    return normalized;
};

// For server-side calls to an already-configured integration (Tautulli, Sonarr,
// Radarr, request apps), the host is trusted admin input and is typically a LAN
// address. We still validate URL format/scheme but allow private/local hosts so
// homelab setups work regardless of the ALLOW_PRIVATE_INTEGRATION_URLS setting,
// which only governs validation of newly submitted URLs.
const resolveIntegrationUrlForFetch = (rawUrl) => {
    if (!rawUrl) return '';
    return normalizeExternalBaseUrl(rawUrl, { allowPrivate: true, allowHttp: true });
};

const resolveRequestAppFetchUrl = (config = {}) => {
    const override = String(process.env.REQUEST_APP_INTERNAL_URL || config.requestAppFetchUrl || '').trim();
    if (override) return resolveIntegrationUrlForFetch(override);
    return resolveIntegrationUrlForFetch(config.requestAppUrl || '');
};

const requestIsHttps = (req) => {
    if (FORCE_SECURE_COOKIES) return true;
    if (req && req.secure) return true;
    const forwarded = String(req?.headers?.['x-forwarded-proto'] || '')
        .split(',')[0]
        .trim()
        .toLowerCase();
    if (forwarded === 'https') return true;
    if (/^https:\/\//i.test(getEnvPublicBaseUrl() || runtimePublicBaseUrl || '')) return true;
    return false;
};

// Mark cookies Secure on HTTPS requests, HTTPS public URL, or FORCE_SECURE_COOKIES=true.
// Plain HTTP LAN setups remain usable when none of those apply.
const sessionCookieBase = (req) => ({
    httpOnly: true,
    secure: requestIsHttps(req),
    sameSite: 'lax',
    path: BASE_PATH || '/',
});

const clearSessionCookie = (req, res) => {
    res.clearCookie('session', sessionCookieBase(req));
};

const setSessionCookie = (req, res, token) => {
    res.cookie('session', token, {
        ...sessionCookieBase(req),
        maxAge: 7 * 24 * 60 * 60 * 1000,
    });
};

/** Bind Plex PIN login to the browser that started it (login CSRF / session substitution). */
const PLEX_OAUTH_COOKIE = 'plex_oauth_state';
const plexOauthStates = new Map(); // pinId -> { nonce, expiresAt }
const PLEX_OAUTH_TTL_MS = 15 * 60 * 1000;

const prunePlexOauthStates = () => {
    const now = Date.now();
    plexOauthStates.forEach((entry, pinId) => {
        if (!entry?.expiresAt || entry.expiresAt <= now) plexOauthStates.delete(pinId);
    });
};

const safeEqualString = (a, b) => {
    const left = Buffer.from(String(a || ''), 'utf8');
    const right = Buffer.from(String(b || ''), 'utf8');
    if (left.length !== right.length || left.length === 0) return false;
    return timingSafeEqual(left, right);
};

const issuePlexOauthState = (req, res, pinId) => {
    prunePlexOauthStates();
    const id = String(pinId || '').trim();
    if (!id) return null;
    const nonce = randomBytes(24).toString('base64url');
    plexOauthStates.set(id, { nonce, expiresAt: Date.now() + PLEX_OAUTH_TTL_MS });
    res.cookie(PLEX_OAUTH_COOKIE, `${id}.${nonce}`, {
        ...sessionCookieBase(req),
        maxAge: PLEX_OAUTH_TTL_MS,
    });
    return nonce;
};

/** Verify PIN OAuth binding via cookie (browser) or oauthState body/header (native app). */
const verifyPlexOauthState = (req, pinId) => {
    prunePlexOauthStates();
    const id = String(pinId || '').trim();
    const expected = id ? plexOauthStates.get(id) : null;
    if (!expected || !id || expected.expiresAt <= Date.now()) return false;
    const bodyState = String(
        req.body?.oauthState
        || req.query?.oauthState
        || req.get?.('x-plex-oauth-state')
        || '',
    ).trim();
    if (bodyState && safeEqualString(bodyState, expected.nonce)) return true;
    const raw = String(req.cookies?.[PLEX_OAUTH_COOKIE] || '').trim();
    const sep = raw.indexOf('.');
    if (sep <= 0) return false;
    const cookiePin = raw.slice(0, sep);
    const cookieNonce = raw.slice(sep + 1);
    return safeEqualString(cookiePin, id) && safeEqualString(cookieNonce, expected.nonce);
};

const clearPlexOauthState = (req, res, pinId) => {
    const id = String(pinId || '').trim();
    if (id) plexOauthStates.delete(id);
    res.clearCookie(PLEX_OAUTH_COOKIE, sessionCookieBase(req));
};

/** One-shot consume (browser redirect). Prefer verify + clear after success for PIN polling. */
const consumePlexOauthState = (req, res, pinId) => {
    const ok = verifyPlexOauthState(req, pinId);
    clearPlexOauthState(req, res, pinId);
    return ok;
};

const PLEX_HOME_SELECT_COOKIE = 'plex_home_select';
const plexHomeSelectPending = new Map(); // id -> { nonce, authToken, userData, ref, expiresAt }
const PLEX_HOME_SELECT_TTL_MS = 10 * 60 * 1000;

const prunePlexHomeSelectPending = () => {
    const now = Date.now();
    plexHomeSelectPending.forEach((entry, id) => {
        if (!entry?.expiresAt || entry.expiresAt <= now) plexHomeSelectPending.delete(id);
    });
};

const issuePlexHomeSelectPending = (req, res, { authToken, userData, ref }) => {
    prunePlexHomeSelectPending();
    const id = randomBytes(16).toString('hex');
    const nonce = randomBytes(24).toString('base64url');
    plexHomeSelectPending.set(id, {
        nonce,
        authToken,
        userData,
        ref: String(ref || '').trim(),
        expiresAt: Date.now() + PLEX_HOME_SELECT_TTL_MS,
    });
    const token = `${id}.${nonce}`;
    res.cookie(PLEX_HOME_SELECT_COOKIE, token, {
        ...sessionCookieBase(req),
        maxAge: PLEX_HOME_SELECT_TTL_MS,
    });
    persistPlexHomeOwner(req, res, { ownerId: userData?.id, authToken });
    return { id, nonce, token };
};

const readPlexHomeSelectPending = (req) => {
    prunePlexHomeSelectPending();
    const fromClient = String(
        req.body?.homeSelectToken
        || req.query?.homeSelectToken
        || req.get?.('x-plex-home-select')
        || '',
    ).trim();
    const raw = fromClient || String(req.cookies?.[PLEX_HOME_SELECT_COOKIE] || '').trim();
    const sep = raw.indexOf('.');
    if (sep <= 0) return null;
    const id = raw.slice(0, sep);
    const nonce = raw.slice(sep + 1);
    const entry = plexHomeSelectPending.get(id);
    if (!entry || entry.expiresAt <= Date.now()) return null;
    if (!safeEqualString(entry.nonce, nonce)) return null;
    return { id, ...entry };
};

const clearPlexHomeSelectPending = (req, res) => {
    const pending = readPlexHomeSelectPending(req);
    if (pending?.id) plexHomeSelectPending.delete(pending.id);
    res.clearCookie(PLEX_HOME_SELECT_COOKIE, sessionCookieBase(req));
};

const PLEX_HOME_REMEMBER_COOKIE = 'plex_home_remember';
const PLEX_HOME_REMEMBER_TTL_MS = 365 * 24 * 60 * 60 * 1000;

const encodePlexHomeRemember = ({ ownerId, userId, pin }) => {
    const payload = JSON.stringify({
        o: String(ownerId || '').trim(),
        u: String(userId || '').trim(),
        p: String(pin || '').trim(),
    });
    return encryptPlexAuthToken(payload);
};

const decodePlexHomeRemember = (raw) => {
    const decrypted = decryptPlexAuthToken(raw);
    if (!decrypted) return null;
    try {
        const parsed = JSON.parse(decrypted);
        const ownerId = String(parsed?.o || parsed?.ownerId || '').trim();
        const userId = String(parsed?.u || parsed?.userId || '').trim();
        if (!ownerId || !userId) return null;
        return {
            ownerId,
            userId,
            pin: String(parsed?.p || parsed?.pin || '').trim(),
        };
    } catch {
        return null;
    }
};

const readPlexHomeRemember = (req) => decodePlexHomeRemember(req.cookies?.[PLEX_HOME_REMEMBER_COOKIE]);

const setPlexHomeRemember = (req, res, { ownerId, userId, pin }) => {
    const encoded = encodePlexHomeRemember({ ownerId, userId, pin });
    if (!encoded) return;
    res.cookie(PLEX_HOME_REMEMBER_COOKIE, encoded, {
        ...sessionCookieBase(req),
        maxAge: PLEX_HOME_REMEMBER_TTL_MS,
    });
};

const clearPlexHomeRemember = (req, res) => {
    res.clearCookie(PLEX_HOME_REMEMBER_COOKIE, sessionCookieBase(req));
};

const PLEX_HOME_OWNER_COOKIE = 'plex_home_owner';

const encodePlexHomeOwner = ({ ownerId, authToken }) => {
    const payload = JSON.stringify({
        o: String(ownerId || '').trim(),
        t: String(authToken || '').trim(),
    });
    return encryptPlexAuthToken(payload);
};

const decodePlexHomeOwner = (raw) => {
    const decrypted = decryptPlexAuthToken(raw);
    if (!decrypted) return null;
    try {
        const parsed = JSON.parse(decrypted);
        const ownerId = String(parsed?.o || parsed?.ownerId || '').trim();
        const authToken = String(parsed?.t || parsed?.authToken || '').trim();
        if (!ownerId || !authToken) return null;
        return { ownerId, authToken };
    } catch {
        return null;
    }
};

const readPlexHomeOwner = (req) => decodePlexHomeOwner(req.cookies?.[PLEX_HOME_OWNER_COOKIE]);

const setPlexHomeOwner = (req, res, { ownerId, authToken }) => {
    const encoded = encodePlexHomeOwner({ ownerId, authToken });
    if (!encoded) return;
    res.cookie(PLEX_HOME_OWNER_COOKIE, encoded, {
        ...sessionCookieBase(req),
        maxAge: PLEX_HOME_REMEMBER_TTL_MS,
    });
};

const persistPlexHomeOwner = (req, res, { ownerId, authToken }) => {
    if (!ownerId || !authToken) return;
    setPlexHomeOwner(req, res, { ownerId, authToken });
    updateUsers((users) => {
        const owner = (Array.isArray(users) ? users : []).find((user) => (
            String(user?.plexId || '') === String(ownerId)
            || (user?.isAdmin && String(user?.id || '') === String(ownerId))
        ));
        if (!owner) return users;
        owner.plexAuthToken = encryptPlexAuthToken(authToken);
        return users;
    }).catch(() => {});
};

const PLEX_HOME_SKIP_REMEMBER_COOKIE = 'plex_home_skip_remember';
const PLEX_HOME_SKIP_REMEMBER_TTL_MS = 15 * 60 * 1000;

const issuePlexHomeSkipRemember = (req, res) => {
    res.cookie(PLEX_HOME_SKIP_REMEMBER_COOKIE, '1', {
        ...sessionCookieBase(req),
        maxAge: PLEX_HOME_SKIP_REMEMBER_TTL_MS,
    });
};

const consumePlexHomeSkipRemember = (req, res) => {
    const skip = String(req.cookies?.[PLEX_HOME_SKIP_REMEMBER_COOKIE] || '') === '1';
    if (skip) res.clearCookie(PLEX_HOME_SKIP_REMEMBER_COOKIE, sessionCookieBase(req));
    return skip;
};

const rejectPlexOauthState = (req, res, { redirectOnSuccess = false } = {}) => {
    const message = 'Login session expired or invalid. Please start Plex sign-in again.';
    log('Plex OAuth state mismatch — rejecting PIN callback (possible login CSRF)');
    clearSessionCookie(req, res);
    if (redirectOnSuccess) {
        return res.redirect(withBasePath('/?loginError=' + encodeURIComponent(message)));
    }
    return res.status(403).json({ error: message });
};

