// Capacitor / native Media Player app — allow cross-origin API with Bearer tokens.
const NATIVE_MEDIA_PLAYER_ORIGINS = new Set([
    'https://localhost',
    'http://localhost',
    'capacitor://localhost',
    'ionic://localhost',
    'http://localhost:5173',
    'http://127.0.0.1:5173',
]);
const isNativeMediaPlayerOrigin = (origin) => {
    const value = String(origin || '').trim();
    if (!value) return false;
    if (NATIVE_MEDIA_PLAYER_ORIGINS.has(value)) return true;
    // Optional extra origins from env (comma-separated).
    const extra = String(process.env.MEDIA_PLAYER_APP_ORIGINS || '')
        .split(',')
        .map((row) => row.trim())
        .filter(Boolean);
    return extra.includes(value);
};
app.use((req, res, next) => {
    const origin = String(req.get('origin') || '').trim();
    if (!origin || !isNativeMediaPlayerOrigin(origin)) return next();
    res.setHeader('Access-Control-Allow-Origin', origin);
    res.setHeader('Access-Control-Allow-Credentials', 'true');
    res.setHeader('Access-Control-Allow-Headers', 'Authorization, Content-Type, Accept, X-Requested-With');
    res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PUT, PATCH, DELETE, OPTIONS');
    res.setHeader('Vary', 'Origin');
    if (req.method === 'OPTIONS') return res.status(204).end();
    return next();
});

// CSRF defense for cookie-authenticated API mutations: require same-origin
// Origin/Referer or the portal's custom X-Requested-With header (sent by apiFetch).
// Bearer-only requests are not cookie CSRF (the token is not sent automatically).
const PORTAL_CSRF_HEADER = 'x-requested-with';
const PORTAL_CSRF_VALUE = 'ServerManagerPortal';
const collectAllowedOrigins = (req) => {
    const allowed = new Set();
    // Prefer Host; only trust X-Forwarded-Host when TRUST_PROXY is explicitly enabled.
    const rawHost = TRUST_PROXY_FOR_RATE_LIMIT
        ? (req.get('x-forwarded-host') || req.get('host') || '')
        : (req.get('host') || '');
    const host = String(rawHost).split(',')[0].trim();
    if (host) {
        allowed.add(`https://${host}`);
        allowed.add(`http://${host}`);
    }
    if (runtimePublicBaseUrl || PUBLIC_BASE_URL) {
        try {
            allowed.add(new URL(runtimePublicBaseUrl || PUBLIC_BASE_URL).origin);
        } catch { /* ignore */ }
    }
    return allowed;
};
const isSameOriginApiRequest = (req) => {
    const allowed = collectAllowedOrigins(req);
    if (!allowed.size) return false;
    const origin = String(req.get('origin') || '').trim();
    if (origin && allowed.has(origin)) return true;
    const referer = String(req.get('referer') || '').trim();
    if (referer) {
        try {
            if (allowed.has(new URL(referer).origin)) return true;
        } catch { /* ignore */ }
    }
    return false;
};
const portalCsrfMiddleware = (req, res, next) => {
    if (!['POST', 'PUT', 'PATCH', 'DELETE'].includes(req.method)) return next();
    if (!String(req.path || '').startsWith('/api/')) return next();
    // External integrations (no browser session / CSRF header).
    if (String(req.path || '').startsWith('/api/editions/webhook')) return next();
    if (String(req.path || '').startsWith('/api/poster-sets/webhook')) return next();
    if (String(req.path || '').startsWith('/api/overlays/collexions-collection-updated')) return next();
    const headerOk = String(req.get(PORTAL_CSRF_HEADER) || '') === PORTAL_CSRF_VALUE;
    if (headerOk || isSameOriginApiRequest(req) || isBearerOnlyRequest(req)) return next();
    return res.status(403).json({ error: 'CSRF validation failed.' });
};

