/** Always stamp wrap-up rank/XP from the live achievements snapshot so Home cannot drift. */
const overlayAchievementsXpOnWrapUp = async (payload, {
    accountID,
    config,
    req,
    usernameMap = {},
} = {}) => {
    if (!payload || !accountID || !config?.achievementsEnabled) return payload;
    if (config.achievementsLeaderboardEnabled === false) return payload;
    try {
        const achievementsState = await loadAchievementsState();
        const obfuscate = shouldObfuscateAnalyticsViewers(req?.user, config);
        const xpRank = buildAchievementsHomeRankContext(achievementsState, {
            accountId: accountID,
            obfuscate,
            usernameMap,
        });
        if (!xpRank || xpRank.myXp == null) return payload;
        const users = await loadFile(USERS_PATH, []);
        const neighbourhood = applyMemberNamePrivacyToRows(
            xpRank.leaderboardNeighbourhood,
            users,
            { obfuscate, viewerIsAdmin: !!req?.user?.isAdmin },
        );
        return {
            ...payload,
            myXp: xpRank.myXp,
            myLevel: xpRank.myLevel,
            myLevelProgress: levelProgress(xpRank.myXp),
            myPlaysOnLeaderboard: xpRank.myPlaysOnLeaderboard,
            leaderboardRank: xpRank.leaderboardRank ?? payload.leaderboardRank,
            totalActiveUsers: xpRank.totalActiveUsers || payload.totalActiveUsers,
            leaderboardNeighbourhood: neighbourhood?.length
                ? neighbourhood
                : payload.leaderboardNeighbourhood,
            leaderboardSource: 'achievements',
            leaderboardMetric: 'xp',
        };
    } catch {
        return payload;
    }
};

/**
 * Normalize library section identity from Plex/Tautulli history rows.
 * PMS history sometimes omits librarySectionID; Tautulli may use section_id / section_title.
 * Falls back to media-type buckets so Wrap-Up Top Library is never empty when plays exist.
 */
const resolveHistoryLibraryBucket = (item, sectionsMap = {}) => {
    const rawId = item?.librarySectionID ?? item?.librarySectionId ?? item?.section_id ?? item?.library_id ?? null;
    const id = rawId != null && !['', 'null', 'undefined'].includes(String(rawId).trim().toLowerCase())
        ? String(rawId).trim()
        : null;
    const titled = String(
        item?.librarySectionTitle
        || item?.section_title
        || item?.library_name
        || item?.section_name
        || '',
    ).trim();
    if (id) {
        const mapped = sectionsMap[id]
            || sectionsMap[Number(id)]
            || (Number.isFinite(Number(id)) ? sectionsMap[String(Number(id))] : null)
            || null;
        return {
            id,
            title: titled || mapped || `Library ${id}`,
        };
    }
    if (titled) return { id: `name:${titled.toLowerCase()}`, title: titled };
    const type = String(item?.type || '').toLowerCase();
    if (type === 'movie') return { id: 'type:movie', title: 'Movies' };
    if (type === 'episode' || type === 'show') return { id: 'type:show', title: 'TV Shows' };
    if (type === 'track' || type === 'album' || type === 'artist') return { id: 'type:music', title: 'Music' };
    return null;
};

const historyItemHasLibraryIdentity = (item) => {
    const rawId = item?.librarySectionID ?? item?.librarySectionId ?? item?.section_id ?? item?.library_id ?? null;
    if (rawId != null && !['', 'null', 'undefined'].includes(String(rawId).trim().toLowerCase())) return true;
    const titled = String(
        item?.librarySectionTitle
        || item?.section_title
        || item?.library_name
        || item?.section_name
        || '',
    ).trim();
    return !!titled;
};

const historyItemRatingKey = (item) => {
    if (item?.ratingKey != null && String(item.ratingKey).trim()) return String(item.ratingKey).trim();
    if (item?.key) {
        const tail = String(item.key).split('/').pop();
        if (tail && /^\d+$/.test(tail)) return tail;
    }
    return null;
};

/**
 * Plex `/status/sessions/history/all` often omits librarySectionID, which collapses several
 * real TV libraries into a single "TV Shows" type bucket. Fill section id/title from
 * `/library/metadata/{ratingKey}` (cached) before aggregating Top Library.
 */
const enrichHistoryItemsLibrarySections = async (
    uri,
    config,
    historyItems,
    sectionsMap = {},
    { maxLookups = 400, concurrency = 6, timeoutMs = 4000 } = {},
) => {
    if (!uri || !config?.plexToken || !Array.isArray(historyItems) || !historyItems.length) {
        return historyItems;
    }

    const toLookup = [];
    const seen = new Set();
    for (const item of historyItems) {
        if (historyItemHasLibraryIdentity(item)) continue;
        const rk = historyItemRatingKey(item);
        if (!rk || seen.has(rk)) continue;
        seen.add(rk);
        toLookup.push(rk);
        if (toLookup.length >= maxLookups) break;
    }
    if (!toLookup.length) return historyItems;

    const metaByRatingKey = new Map();
    let cursor = 0;
    const fetchOne = async (rk) => {
        const path = `/library/metadata/${rk}`;
        let data = plexMetadataCache.get(path);
        if (!data) {
            const metaRes = await fetch(
                `${uri}${path}?X-Plex-Token=${encodeURIComponent(config.plexToken)}`,
                { headers: plexClientHeaders(config.plexToken) },
            ).then((r) => r.json()).catch(() => null);
            data = metaRes?.MediaContainer?.Metadata?.[0] || null;
            if (data) plexMetadataCache.set(path, data);
        }
        if (data) metaByRatingKey.set(String(rk), data);
    };

    const worker = async () => {
        while (true) {
            const idx = cursor++;
            if (idx >= toLookup.length) return;
            await fetchOne(toLookup[idx]);
        }
    };

    const run = Promise.all(
        Array.from({ length: Math.min(concurrency, toLookup.length) }, () => worker()),
    );
    await Promise.race([
        run,
        new Promise((resolve) => setTimeout(resolve, timeoutMs)),
    ]);

    let filled = 0;
    for (const item of historyItems) {
        if (historyItemHasLibraryIdentity(item)) continue;
        const rk = historyItemRatingKey(item);
        const data = (rk && metaByRatingKey.get(String(rk)))
            || (item?.grandparentRatingKey != null
                ? (metaByRatingKey.get(String(item.grandparentRatingKey))
                    || plexMetadataCache.get(`/library/metadata/${item.grandparentRatingKey}`))
                : null);
        if (!data || typeof data !== 'object') continue;
        const sectionId = data.librarySectionID ?? data.librarySectionId;
        if (sectionId == null || sectionId === '') continue;
        item.librarySectionID = sectionId;
        const mapped = sectionsMap[String(sectionId)]
            || sectionsMap[Number(sectionId)]
            || (Number.isFinite(Number(sectionId)) ? sectionsMap[String(Number(sectionId))] : null)
            || null;
        item.librarySectionTitle = data.librarySectionTitle || mapped || null;
        filled += 1;
    }
    if (filled > 0) {
        log(`[Analytics] Filled library section on ${filled} history play(s) via metadata (${toLookup.length} lookup keys).`);
    }
    return historyItems;
};

const bumpHistoryLibraryCount = (libraryCounts, item, sectionsMap = {}) => {
    const bucket = resolveHistoryLibraryBucket(item, sectionsMap);
    if (!bucket) return;
    if (!libraryCounts[bucket.id]) {
        libraryCounts[bucket.id] = { id: bucket.id, title: bucket.title, plays: 0 };
    } else if (bucket.title) {
        const current = String(libraryCounts[bucket.id].title || '');
        const isWeakTitle = current.startsWith('Library ')
            || current === 'Movies'
            || current === 'TV Shows'
            || current === 'Music';
        if (isWeakTitle && bucket.title !== current) {
            libraryCounts[bucket.id].title = bucket.title;
        }
    }
    libraryCounts[bucket.id].plays++;
};

const buildLibrarySectionsMap = (sectionsRes) => {
    const sectionsMap = {};
    const dirs = sectionsRes?.MediaContainer?.Directory;
    if (!Array.isArray(dirs)) return sectionsMap;
    for (const section of dirs) {
        if (section?.key == null || !section?.title) continue;
        const key = String(section.key);
        sectionsMap[key] = section.title;
        const asNum = Number(section.key);
        if (Number.isFinite(asNum)) sectionsMap[asNum] = section.title;
    }
    return sectionsMap;
};
