const normalizeJellyfinAnalyticsProvider = (value, config = {}) => {
    const raw = String(value || '').toLowerCase();
    if (raw === 'jellystat' || raw === 'jellyglance') return raw;
    const hasJellystat = !!(config.jellystatUrl && config.jellystatApiKey);
    const hasJellyGlance = !!(config.jellyglanceUrl && config.jellyglanceApiKey);
    return hasJellystat && !hasJellyGlance ? 'jellystat' : 'jellyglance';
};

const createDefaultStatusConfig = (config = {}) => {
    const groups = [
        { id: 'core', name: 'Core Infrastructure', order: 0 },
        { id: 'media', name: 'Media Stack', order: 1 },
        { id: 'downloads', name: 'Download Clients', order: 2 },
        { id: 'external', name: 'External Services', order: 3 },
    ];
    const services = [];
    const addService = (id, name, url, groupId, description = '', { visibleToUsers = true } = {}) => {
        if (!url) return;
        services.push({ id, name, url, type: 'web', groupId, description, visibleToUsers: visibleToUsers !== false });
    };

    const publicDomain = resolvePublicBaseUrlFromConfig(config);
    if (publicDomain) addService('portal', 'StreamPilot', `${publicDomain}/api/health`, 'core', 'Portal API health', { visibleToUsers: true });

    const mediaServerType = String(config.mediaServerType || 'plex').toLowerCase();
    if (mediaServerType !== 'plex') {
        const mediaLabel = mediaServerType === 'emby' ? 'Emby' : 'Jellyfin';
        addService(mediaServerType, mediaLabel, config.jellyfinUrl, 'media', `${mediaLabel} media server`, { visibleToUsers: true });
        if (mediaServerType === 'jellyfin') {
            const analyticsProvider = normalizeJellyfinAnalyticsProvider(config.jellyfinAnalyticsProvider, config);
            addService(
                analyticsProvider,
                analyticsProvider === 'jellyglance' ? 'JellyGlance' : 'Jellystat',
                analyticsProvider === 'jellyglance' ? config.jellyglanceUrl : config.jellystatUrl,
                'media',
                'Jellyfin analytics',
                { visibleToUsers: true },
            );
        }
    } else {
        addService('plex', 'Plex', config.plexServerUrl || publicDomain, 'media', 'Plex Media Server', { visibleToUsers: true });
        addService('tautulli', 'Tautulli', config.tautulliUrl, 'media', 'Plex analytics', { visibleToUsers: true });
    }

    getArrInstances(config, { enabledOnly: true }).forEach((instance) => {
        if (!instance?.url) return;
        const label = instance.name || ({ radarr: 'Radarr', lidarr: 'Lidarr', bazarr: 'Bazarr', sonarr: 'Sonarr' }[instance.type] || 'Sonarr');
        const description = ({
            radarr: 'Movie automation',
            sonarr: 'TV automation',
            lidarr: 'Music automation',
            bazarr: 'Subtitle automation',
        }[instance.type] || 'Media automation');
        // Arr apps default admin-only on the public Status page.
        addService(`arr-${instance.id}`, label, instance.url, 'downloads', description, { visibleToUsers: false });
    });
    (Array.isArray(config.downloadClients) ? config.downloadClients : []).forEach((client) => {
        if (client?.enabled === false || !client?.url) return;
        services.push({
            id: `download-${client.id}`,
            name: client.name || downloadClientLabel(client.type),
            url: client.url,
            type: 'download-client',
            clientType: client.type,
            clientId: client.id,
            groupId: 'downloads',
            description: `${downloadClientLabel(client.type)} download client`,
            visibleToUsers: false,
        });
    });
    if (config.requestAppType && config.requestAppType !== 'none') {
        addService(config.requestAppType, config.requestAppType === 'jellyseerr' ? 'Jellyseerr' : 'Seerr', config.requestAppUrl, 'external', 'Requests portal', { visibleToUsers: true });
    }
    if (config.collexionsEnabled && String(config.collexionsInternalUrl || '').trim()) {
        addService('collexions', 'ColleXions', String(config.collexionsInternalUrl).trim().replace(/\/+$/, ''), 'external', 'Plex collections sidecar', { visibleToUsers: false });
    }
    if (config.spotifyToPlexEnabled && String(config.spotifyToPlexInternalUrl || '').trim()) {
        addService('spotify-sync', 'Spotify Sync', String(config.spotifyToPlexInternalUrl).trim().replace(/\/+$/, ''), 'external', 'spotify-to-plex Compose service', { visibleToUsers: false });
    }

    return { groups, services, announcement: null };
};

const syncIntegrationServicesInStatusConfig = (config = {}) => {
    const arrServices = getArrInstances(config, { enabledOnly: true })
        .filter((instance) => instance?.url)
        .map((instance) => ({
            id: `arr-${instance.id}`,
            name: instance.name || ({ radarr: 'Radarr', lidarr: 'Lidarr', bazarr: 'Bazarr', sonarr: 'Sonarr' }[instance.type] || 'Sonarr'),
            url: instance.url,
            type: 'web',
            groupId: 'downloads',
            description: ({
                radarr: 'Movie automation',
                sonarr: 'TV automation',
                lidarr: 'Music automation',
                bazarr: 'Subtitle automation',
            }[instance.type] || 'Media automation'),
            visibleToUsers: false,
        }));
    const downloadServices = (Array.isArray(config.downloadClients) ? config.downloadClients : [])
        .filter((client) => client?.enabled !== false && client?.url)
        .map((client) => ({
            id: `download-${client.id}`,
            name: client.name || downloadClientLabel(client.type),
            url: client.url,
            type: 'download-client',
            clientType: client.type,
            clientId: client.id,
            groupId: 'downloads',
            description: `${downloadClientLabel(client.type)} download client`,
            visibleToUsers: false,
        }));
    const managedTemplates = [...arrServices, ...downloadServices];
    const suppressed = new Set(
        (Array.isArray(statusConfig.suppressedManagedIds) ? statusConfig.suppressedManagedIds : []).map(String),
    );
    const existingServices = Array.isArray(statusConfig.services) ? statusConfig.services : [];
    const existingById = new Map(existingServices.map((service) => [String(service.id), service]));

    // Keep custom / manually added monitors (not arr-* / download-* managed rows).
    const unmanaged = existingServices.filter((service) => {
        const id = String(service.id || '');
        return !id.startsWith('arr-') && !id.startsWith('download-');
    });

    const mergedManaged = [];
    for (const template of managedTemplates) {
        const id = String(template.id);
        // Honor admin deletions — do not resurrect suppressed managed monitors.
        if (suppressed.has(id)) continue;

        const existing = existingById.get(id);
        if (existing) {
            mergedManaged.push({
                ...existing,
                // Only refresh connection metadata from Integrations; keep name/group/visibility.
                url: template.url,
                type: template.type,
                ...(template.clientType != null ? { clientType: template.clientType } : {}),
                ...(template.clientId != null ? { clientId: template.clientId } : {}),
                // Managed rows without an explicit flag default to admin-only.
                visibleToUsers: existing.visibleToUsers === undefined ? false : existing.visibleToUsers !== false,
            });
        } else {
            mergedManaged.push(template);
        }
    }

    statusConfig.services = [...unmanaged, ...mergedManaged];
    statusConfig.suppressedManagedIds = [...suppressed];
};

/** Public/member Status page: omit admin-only services. Missing flag stays visible for back-compat. */
