// --- Helper Functions ---
const log = (message) => console.log(`[${new Date().toISOString()}] ${message}`);

const getDaysUntilExpiry = (expiryDate) => {
    if (expiryDate == null || expiryDate === '') return null;
    const datePart = String(expiryDate).split('T')[0];
    const [year, month, day] = datePart.split('-').map(Number);
    if (!Number.isFinite(year) || !Number.isFinite(month) || !Number.isFinite(day) || !year || !month || !day) {
        return null;
    }
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    const expiry = new Date(year, month - 1, day);
    if (Number.isNaN(expiry.getTime())) return null;
    expiry.setHours(0, 0, 0, 0);

    const diffTime = expiry.getTime() - today.getTime();
    return Math.round(diffTime / (1000 * 60 * 60 * 24));
};

/** True when the member's calendar expiry date is in the past (unlimited = not expired). */
const isAccessExpired = (user) => {
    const days = getDaysUntilExpiry(user?.expiryDate);
    return days !== null && days < 0;
};

/**
 * APIs expired members may still call (support / chat / profile / prefs / logout).
 * Everything else under requireMember returns 403 ACCESS_EXPIRED.
 */
const isExpiredPortalAllowedApiPath = (rawPath = '') => {
    const path = String(rawPath || '').split('?')[0].toLowerCase();
    const prefixes = [
        '/api/support',
        '/api/chat',
        '/api/profile',
        '/api/users/preferences',
        '/api/notifications',
        '/api/auth/logout',
        '/api/me/onboarding',
        '/api/me/referral-stats',
    ];
    return prefixes.some((prefix) => path === prefix || path.startsWith(`${prefix}/`));
};

/** Clear stale isTrial when access is unlimited or extended beyond short-term trial. */
const reconcileTrialAccessFlag = (user) => {
    if (!user?.isTrial) return false;
    const days = getDaysUntilExpiry(user.expiryDate);
    if (days === null || days > 3) {
        user.isTrial = false;
        return true;
    }
    return false;
};

const addMonths = (date, months) => {
    const d = new Date(date);
    d.setMonth(d.getMonth() + months);
    return d;
};

const addYears = (date, years) => {
    const d = new Date(date);
    d.setFullYear(d.getFullYear() + years);
    return d;
};

const addDays = (date, days) => {
    const d = new Date(date);
    d.setDate(d.getDate() + days);
    return d;
};

const normalized = (value) => value ? value.toString().trim().toLowerCase() : '';

// --- Bounded API cache (TTL + LRU) ---
const apiCache = createTtlLruCache({
    name: 'api',
    maxEntries: 300,
    defaultTtlMs: 60_000,
});

/** Shared media-server sessions cache for Now Playing / watching count (SWR). */
const mediaSessionsSwr = createSwrCache({ name: 'media-sessions', maxEntries: 8 });
const MEDIA_SESSIONS_FRESH_MS = 8_000;
const MEDIA_SESSIONS_STALE_MS = 45_000;
const PLEX_SESSIONS_SWR_KEY = 'plex_status_sessions';
const jellyfinSessionsSwrKey = (type = 'jellyfin') => `${type}_sessions`;

const fetchPlexStatusSessions = async (uri, config) => (
    fetch(`${uri}/status/sessions?X-Plex-Token=${config.plexToken}`, {
        headers: plexClientHeaders(config.plexToken),
    })
        .then((r) => r.json())
        .catch(() => null)
);

const plexSessionsAreEmpty = (sessionsData) => {
    const meta = sessionsData?.MediaContainer?.Metadata;
    if (meta == null) return true;
    if (Array.isArray(meta)) return meta.length === 0;
    return !meta.ratingKey && !meta.key;
};

const getPlexStatusSessionsSwr = async (uri, config, { force = false } = {}) => {
    if (force) {
        const value = await mediaSessionsSwr.revalidate(
            PLEX_SESSIONS_SWR_KEY,
            () => fetchPlexStatusSessions(uri, config),
        );
        return { sessionsData: value, stale: false, ageMs: 0 };
    }

    const peeked = mediaSessionsSwr.peek(PLEX_SESSIONS_SWR_KEY);
    // Empty session lists go stale quickly so Android / Web starts aren't masked.
    const empty = peeked ? plexSessionsAreEmpty(peeked.value) : false;
    const freshMs = empty ? 2_000 : MEDIA_SESSIONS_FRESH_MS;
    const staleMs = empty ? 8_000 : MEDIA_SESSIONS_STALE_MS;

    const { value, stale, ageMs } = await mediaSessionsSwr.get(
        PLEX_SESSIONS_SWR_KEY,
        () => fetchPlexStatusSessions(uri, config),
        { freshMs, staleMs },
    );
    return { sessionsData: value, stale, ageMs };
};

const getJellyfinSessionsSwr = async (config) => {
    const mediaServerType = config.mediaServerType || 'jellyfin';
    const baseUrl = resolveIntegrationUrlForFetch(config.jellyfinUrl);
    const { value, stale, ageMs } = await mediaSessionsSwr.get(
        jellyfinSessionsSwrKey(mediaServerType),
        async () => (
            fetchWithTimeout(`${baseUrl}/Sessions`, { headers: jellyfinHeaders(config.jellyfinApiKey) }, 15000)
                .then((r) => (r.ok ? r.json() : []))
                .catch(() => [])
        ),
        { freshMs: MEDIA_SESSIONS_FRESH_MS, staleMs: MEDIA_SESSIONS_STALE_MS },
    );
    return { sessions: value, stale, ageMs };
};

/**
 * Wraps an expensive async fetcher function with a TTL cache.
 * @param {string} key Unique cache key
 * @param {number} ttlMs Time to live in milliseconds
 * @param {Function} fetcher Async function returning data to cache
 */
const withCache = async (key, ttlMs, fetcher) => {
    const hit = apiCache.get(key);
    if (hit !== undefined) return hit;

    const data = await fetcher();
    if (data !== null && data !== undefined) {
        apiCache.set(key, data, ttlMs);
    }
    return data;
};

const isDeletedUser = (deletedUsers, user) => {
    const ids = [
        normalized(user.id),
        normalized(user.plexId),
        normalized(user.jellyfinId)
    ].filter(Boolean);
    const email = normalized(user.email);
    const username = normalized(user.username);

    return deletedUsers.some(deletedUser => {
        const deletedIds = [
            normalized(deletedUser.id),
            normalized(deletedUser.plexId),
            normalized(deletedUser.jellyfinId)
        ].filter(Boolean);

        return (
            ids.some(id => deletedIds.includes(id)) ||
            (email && email === normalized(deletedUser.email)) ||
            (username && username === normalized(deletedUser.username))
        );
    });
};

const rememberDeletedUser = async (user, deletedBy) => {
    const deletedUsers = await loadFile(DELETED_USERS_PATH, []);
    if (!isDeletedUser(deletedUsers, user)) {
        deletedUsers.push({
            blockId: randomUUID(),
            id: user.id,
            plexId: user.plexId || user.id,
            jellyfinId: user.jellyfinId || null,
            username: user.username,
            email: user.email,
            deletedAt: new Date().toISOString(),
            deletedBy: deletedBy?.username || deletedBy?.email || 'admin'
        });
        await saveFile(DELETED_USERS_PATH, deletedUsers);
    }
};

const getDeletedUserKey = (deletedUser) => deletedUser.blockId || deletedUser.id || deletedUser.plexId || deletedUser.email || deletedUser.username;

const appendAuditLog = async (event, actor, target = null, details = {}) => {
    try {
        const auditLog = await loadFile(AUDIT_LOG_PATH, []);
        auditLog.unshift({
            id: randomUUID(),
            timestamp: new Date().toISOString(),
            event,
            actor: actor ? {
                id: actor.id || actor.plexId || null,
                plexId: actor.plexId || actor.id || null,
                username: actor.username || null,
                email: actor.email || null,
                isAdmin: !!actor.isAdmin
            } : null,
            target: target ? {
                id: target.id || target.plexId || null,
                plexId: target.plexId || target.id || null,
                username: target.username || null,
                email: target.email || null
            } : null,
            details
        });
        await saveFile(AUDIT_LOG_PATH, auditLog.slice(0, 5000));
    } catch (error) {
        log(`Failed to write audit log: ${error.message}`);
    }
};

