app.post('/api/settings/email-templates/preview', requireAdmin, async (req, res) => {
    try {
        const event = String(req.body?.event || '').trim();
        if (!EMAIL_TEMPLATE_EVENTS.includes(event)) {
            return res.status(400).json({ error: 'Invalid email template event.' });
        }
        const config = await loadFile(CONFIG_PATH, {});
        const draftFields = req.body?.templates && typeof req.body.templates === 'object'
            ? req.body.templates
            : {};

        if (event === 'newsletter') {
            const { html, attachments } = await generateNewsletterHtml(config, {
                embedImages: true,
                draftTemplates: { newsletter: draftFields },
            });
            const previewHtml = renderNewsletterHtmlForBrowser(html, attachments, req.user?.username || 'Preview User');
            const { rendered } = renderEmailEventTemplates(
                { ...config, emailTemplates: normalizeEmailTemplates({ ...(config.emailTemplates || {}), newsletter: draftFields }) },
                'newsletter',
                { serverName: 'Preview Server', username: req.user?.username || 'Preview User', portalUrl: resolvePublicBaseUrlFromConfig(config) || config.publicDomain || '#' },
            );
            return res.json({ subject: rendered.subject, html: previewHtml, event });
        }

        const adminProfile = await getAdminProfile(config).catch(() => null);
        const serverName = adminProfile?.serverName || 'Preview Server';
        const previewConfig = {
            ...config,
            contactEmail: config.contactEmail || req.user?.email || '',
            contactWhatsApp: config.contactWhatsApp || '',
            contactUrl: config.contactUrl || resolvePublicBaseUrlFromConfig(config) || config.publicDomain || '#',
        };
        const mail = buildAutomatedEmailPreview(previewConfig, event, draftFields);
        if (mail?.unsupported) {
            return res.status(400).json({ error: 'Preview is not available for this event.' });
        }
        return res.json({
            subject: mail.subject,
            html: mail.html,
            event,
            serverName,
        });
    } catch (error) {
        log(`Email template preview error: ${error.message}`);
        return res.status(500).json({ error: `Failed to render preview: ${error.message}` });
    }
});

app.post('/api/settings/email-templates/test', requireAdmin, async (req, res) => {
    try {
        const event = String(req.body?.event || '').trim();
        if (!EMAIL_TEMPLATE_EVENTS.includes(event)) {
            return res.status(400).json({ error: 'Invalid email template event.' });
        }
        const config = await loadFile(CONFIG_PATH, {});
        if (!config.smtpHost || !config.smtpUser) {
            return res.status(400).json({ error: 'SMTP settings are not configured.' });
        }
        const adminEmail = req.user?.email;
        if (!adminEmail) {
            return res.status(400).json({ error: 'Admin email not found in session.' });
        }
        const draftFields = req.body?.templates && typeof req.body.templates === 'object'
            ? req.body.templates
            : {};

        if (event === 'newsletter') {
            const { html, attachments } = await generateNewsletterHtml(config, {
                draftTemplates: { newsletter: draftFields },
            });
            const providerLabel = getNewsletterProviderLabel(config);
            const { rendered } = renderEmailEventTemplates(
                { ...config, emailTemplates: normalizeEmailTemplates({ ...(config.emailTemplates || {}), newsletter: draftFields }) },
                'newsletter',
                { serverName: providerLabel, username: req.user?.username || 'Admin', portalUrl: resolvePublicBaseUrlFromConfig(config) || config.publicDomain || '#' },
            );
            const transporter = nodemailer.createTransport({
                host: config.smtpHost,
                port: config.smtpPort,
                secure: config.smtpSecure,
                auth: { user: config.smtpUser, pass: config.smtpPass },
            });
            const personalizedHtml = personalizeNewsletterHtml(html, {
                username: req.user?.username || 'Admin',
                plexAccountId: req.user?.plexAccountId,
            });
            await transporter.sendMail({
                from: config.smtpFrom || config.smtpUser,
                to: adminEmail,
                subject: `${rendered.subject || `${providerLabel} Newsletter`} (Test)`,
                html: personalizedHtml,
                attachments,
            });
            return res.json({ message: `Test newsletter sent to ${adminEmail}` });
        }

        const adminProfile = await getAdminProfile(config).catch(() => null);
        const previewConfig = {
            ...config,
            contactEmail: config.contactEmail || adminEmail,
            contactWhatsApp: config.contactWhatsApp || '',
            contactUrl: config.contactUrl || resolvePublicBaseUrlFromConfig(config) || config.publicDomain || '#',
        };
        const mail = buildAutomatedEmailPreview(previewConfig, event, draftFields);
        if (mail?.unsupported) {
            return res.status(400).json({ error: 'Test send is not available for this event.' });
        }
        await sendEmail(config, adminEmail, `${mail.subject} (Test)`, mail.html);
        return res.json({ message: `Test email sent to ${adminEmail}` });
    } catch (error) {
        log(`Email template test error: ${error.message}`);
        return res.status(500).json({ error: `Failed to send test email: ${error.message}` });
    }
});

// Plex's auth page compares this to the forwardUrl host. A missing Origin
// makes app.plex.tv show "We were unable to complete this request."
const plexPinOrigin = (req) => {
    const requested = String(req.get('origin') || '').trim();
    if (requested && collectAllowedOrigins(req).has(requested)) return requested;
    const pub = runtimePublicBaseUrl || getEnvPublicBaseUrl() || '';
    if (pub) {
        try { return new URL(pub).origin; } catch { /* ignore */ }
    }
    const host = String(req.get('host') || '').split(',')[0].trim();
    if (!host) return '';
    return `${requestIsHttps(req) ? 'https' : 'http'}://${host}`;
};

// Auth endpoints
app.post('/api/auth/plex/login', authRateLimit, async (req, res) => {
    try {
        // strong=true → long code for app.plex.tv/auth (web redirect flow).
        // linkCode/strong=false → short 4-char code for https://plex.tv/link (TV / native).
        const wantLinkCode = req.body?.linkCode === true || req.body?.strong === false;
        const pinEndpoint = wantLinkCode
            ? 'https://plex.tv/api/v2/pins'
            : 'https://plex.tv/api/v2/pins?strong=true';
        const origin = plexPinOrigin(req);
        const response = await fetch(pinEndpoint, {
            method: 'POST',
            headers: plexClientHeaders('', {
                'X-Plex-Product': 'StreamPilot',
                ...(origin ? { Origin: origin } : {}),
            }),
        });
        if (!response.ok) throw new Error('Failed to generate Plex PIN');
        const data = await response.json();
        log(`Plex login PIN issued origin=${origin || 'none'} pinId=${data?.id || 'none'}`);
        const oauthState = data?.id ? issuePlexOauthState(req, res, data.id) : null;
        if (req.body?.skipHomeRemember === true) issuePlexHomeSkipRemember(req, res);
        // oauthState is for Capacitor / cross-origin clients that cannot rely on the OAuth cookie.
        res.json({
            ...data,
            clientIdentifier: CLIENT_ID,
            oauthState,
            linkCode: wantLinkCode,
        });
    } catch (err) {
        log('Error in plex login: ' + err.message);
        res.status(500).json({ error: 'Failed to initiate login' });
    }
});

const jellyfinQuickConnectSessions = new Map();

const pruneJellyfinQuickConnectSessions = () => {
    const now = Date.now();
    jellyfinQuickConnectSessions.forEach((session, id) => {
        if (!session?.expiresAt || session.expiresAt <= now) {
            jellyfinQuickConnectSessions.delete(id);
        }
    });
};

const completeJellyfinPortalLogin = async (req, res, config, authData, source = 'password') => {
    const jellyfinUser = authData?.User || authData?.user || {};
    const accessToken = authData?.AccessToken || authData?.accessToken || '';
    const userId = jellyfinUser.Id || jellyfinUser.Id || jellyfinUser.id || '';
    const username = jellyfinUser.Name || jellyfinUser.name || 'Jellyfin User';
    const isAdmin = jellyfinUser?.Policy?.IsAdministrator === true || jellyfinUser?.policy?.isAdministrator === true;
    const sessionUser = {
        id: userId ? `jellyfin:${userId}` : `jellyfin:${username}`,
        jellyfinId: userId,
        authProvider: 'jellyfin',
        username,
        email: '',
        thumb: userId ? withBasePath(`/api/jellyfin/user-image?userId=${encodeURIComponent(userId)}`) : null,
        jellyfinIsAdmin: isAdmin,
        isAdmin,
    };
    const ref = String(req.body?.ref || req.query?.ref || '').trim();

    const deletedUsers = await loadFile(DELETED_USERS_PATH, []);
    if (!isAdmin && isDeletedUser(deletedUsers, sessionUser)) {
        await appendAuditLog('login_blocked_deleted_user', sessionUser, sessionUser);
        clearSessionCookie(req, res);
        return res.status(403).json({ error: 'Your portal session has expired. Please contact the admin for access.' });
    }

    let users = await loadFile(USERS_PATH, []);
    let knownUser = findLocalUserForSession(users, sessionUser);
    if (!isAdmin && !knownUser) {
        const canSelfRegister = !!config.referralEnabled && !!ref;
        if (canSelfRegister) {
            await claimReferralForSession(sessionUser, config, ref);
            users = await loadFile(USERS_PATH, []);
            knownUser = findLocalUserForSession(users, sessionUser);
        }
        if (!knownUser) {
            await appendAuditLog('login_blocked_non_member', sessionUser, sessionUser, {
                reason: ref ? 'referral_not_granted' : 'not_a_member',
            });
            clearSessionCookie(req, res);
            log(`Jellyfin ${source} login blocked for ${sessionUser.username}: not a portal member`);
            const message = ref
                ? 'This referral link could not be used. Please contact the admin for access.'
                : 'Your account is not registered for this portal.';
            return res.status(403).json({ error: message });
        }
    }

    if (!isAdmin) {
        await updateUsers((currentUsers) => {
            if (!touchUserLastLogin(currentUsers, sessionUser)) {
                return { data: currentUsers, result: currentUsers };
            }
            return currentUsers;
        });
    }

    const token = jwt.sign(sessionUser, JWT_SECRET, { expiresIn: '7d' });
    setSessionCookie(req, res, token);
    await appendAuditLog('user_login', sessionUser, sessionUser);
    log(`Jellyfin ${source} login success for ${sessionUser.username} (admin=${isAdmin}, secureCookie=${FORCE_SECURE_COOKIES}, token=${accessToken ? 'received' : 'missing'})`);
    return res.json({ success: true, sessionToken: token, user: { username: sessionUser.username, jellyfinId: sessionUser.jellyfinId, isAdmin } });
};

app.post('/api/auth/jellyfin/login', authRateLimit, async (req, res) => {
    const { username, password } = req.body || {};
    if (!username || !password) {
        return res.status(400).json({ error: 'Username and password are required' });
    }

    try {
        const config = await loadFile(CONFIG_PATH, {});
        const mediaServerLabel = String(config.mediaServerType || '').toLowerCase() === 'emby' ? 'Emby' : 'Jellyfin';
        if (!isJellyfinConfigured(config)) {
            return res.status(400).json({ error: `${mediaServerLabel} authentication is not configured` });
        }

        const baseUrl = resolveIntegrationUrlForFetch(config.jellyfinUrl);
        const response = await fetch(`${baseUrl}/Users/AuthenticateByName`, {
            method: 'POST',
            headers: jellyfinHeaders('', { 'Content-Type': 'application/json' }),
            body: JSON.stringify({ Username: username, Pw: password }),
        });

        if (!response.ok) {
            const detail = await response.text().catch(() => '');
            log(`${mediaServerLabel} login failed for ${username}: ${response.status} ${detail.slice(0, 120)}`);
            return res.status(401).json({ error: `Invalid ${mediaServerLabel} username or password` });
        }

        return completeJellyfinPortalLogin(req, res, config, await response.json(), 'password');
    } catch (err) {
        log('Error in media server login: ' + err.message);
        res.status(500).json({ error: 'Failed to authenticate with media server' });
    }
});

app.post('/api/auth/jellyfin/quick-connect/initiate', authRateLimit, async (req, res) => {
    try {
        pruneJellyfinQuickConnectSessions();
        const config = await loadFile(CONFIG_PATH, {});
        if (!isJellyfinConfigured(config)) {
            return res.status(400).json({ error: 'Jellyfin authentication is not configured' });
        }

        const baseUrl = resolveIntegrationUrlForFetch(config.jellyfinUrl);
        const enabledRes = await fetch(`${baseUrl}/QuickConnect/Enabled`, {
            headers: jellyfinHeaders(''),
        });
        if (enabledRes.ok) {
            const enabledText = await enabledRes.text();
            if (String(enabledText).trim().toLowerCase() === 'false') {
                return res.status(400).json({ error: 'Quick Connect is disabled on your Jellyfin server.' });
            }
        }

        const initiateRes = await fetch(`${baseUrl}/QuickConnect/Initiate`, {
            method: 'POST',
            headers: jellyfinHeaders(''),
        });
        if (!initiateRes.ok) {
            const detail = await initiateRes.text().catch(() => '');
            log(`Jellyfin Quick Connect initiate failed: ${initiateRes.status} ${detail.slice(0, 160)}`);
            return res.status(502).json({ error: 'Failed to start Jellyfin Quick Connect.' });
        }

        const state = await initiateRes.json();
        const secret = state.Secret || state.secret;
        const code = state.Code || state.code;
        if (!secret || !code) {
            return res.status(502).json({ error: 'Jellyfin did not return a Quick Connect code.' });
        }

        const sessionId = randomUUID();
        jellyfinQuickConnectSessions.set(sessionId, {
            secret,
            baseUrl,
            expiresAt: Date.now() + 5 * 60 * 1000,
        });
        res.json({ sessionId, code, jellyfinUrl: config.jellyfinUrl });
    } catch (err) {
        log('Error starting jellyfin quick connect: ' + err.message);
        res.status(500).json({ error: 'Failed to start Jellyfin Quick Connect' });
    }
});

app.post('/api/auth/jellyfin/quick-connect/poll', jellyfinQuickConnectPollRateLimit, async (req, res) => {
    const { sessionId } = req.body || {};
    if (!sessionId) return res.status(400).json({ error: 'sessionId is required' });

    try {
        pruneJellyfinQuickConnectSessions();
        const quickSession = jellyfinQuickConnectSessions.get(sessionId);
        if (!quickSession) {
            return res.status(404).json({ error: 'Quick Connect session expired. Please try again.' });
        }

        const config = await loadFile(CONFIG_PATH, {});
        if (!isJellyfinConfigured(config)) {
            return res.status(400).json({ error: 'Jellyfin authentication is not configured' });
        }

        const stateRes = await fetch(`${quickSession.baseUrl}/QuickConnect/Connect?secret=${encodeURIComponent(quickSession.secret)}`, {
            headers: jellyfinHeaders(''),
        });
        if (!stateRes.ok) {
            const detail = await stateRes.text().catch(() => '');
            log(`Jellyfin Quick Connect poll failed: ${stateRes.status} ${detail.slice(0, 160)}`);
            return res.status(502).json({ error: 'Failed to check Jellyfin Quick Connect status.' });
        }
        const state = await stateRes.json();
        const authenticated = state.Authenticated === true || state.authenticated === true;
        if (!authenticated) {
            return res.json({ authenticated: false });
        }

        const authRes = await fetch(`${quickSession.baseUrl}/Users/AuthenticateWithQuickConnect`, {
            method: 'POST',
            headers: jellyfinHeaders('', { 'Content-Type': 'application/json' }),
            body: JSON.stringify({ Secret: quickSession.secret }),
        });
        if (!authRes.ok) {
            const detail = await authRes.text().catch(() => '');
            log(`Jellyfin Quick Connect token exchange failed: ${authRes.status} ${detail.slice(0, 160)}`);
            return res.status(502).json({ error: 'Jellyfin approved the code, but token exchange failed.' });
        }

        jellyfinQuickConnectSessions.delete(sessionId);
        return completeJellyfinPortalLogin(req, res, config, await authRes.json(), 'quick-connect');
    } catch (err) {
        log('Error polling jellyfin quick connect: ' + err.message);
        res.status(500).json({ error: 'Failed to finish Jellyfin Quick Connect' });
    }
});

const fetchPlexPinAuthToken = async (pinId, { attempts = 10, delayMs = 800 } = {}) => {
    let lastData = null;
    for (let attempt = 1; attempt <= attempts; attempt++) {
        const pinRes = await fetch(`https://plex.tv/api/v2/pins/${pinId}`, {
            headers: plexClientHeaders(),
        });
        lastData = await pinRes.json();
        if (lastData?.authToken) {
            if (attempt > 1) log(`Plex pin ${pinId} authenticated after ${attempt} attempts`);
            return lastData;
        }
        if (attempt < attempts) {
            await new Promise((resolve) => setTimeout(resolve, delayMs));
        }
    }
    log(`Plex pin ${pinId} missing authToken after ${attempts} attempts`);
    return lastData || {};
};

/**
 * Atomically claim a referral for a brand-new session user (Plex or Jellyfin/Emby).
 * Returns { kind: 'skip'|'blocked'|'granted', ... }.
 */
const claimReferralForSession = async (sessionUser, config, ref) => {
    const referralCode = String(ref || '').trim();
    if (!config?.referralEnabled || !referralCode) return { kind: 'skip' };

    const trialDays = config.referralTrialDays || 3;
    const rewardDays = config.referralRewardDays || 7;
    const onboardingDoc = normalizeOnboardingDocument(
        await loadFile(ONBOARDING_PATH, emptyOnboardingDocument())
    );
    const isJellyfinSession = sessionUser?.authProvider === 'jellyfin' || !!sessionUser?.jellyfinId;

    const claimOutcome = await withFileLock(USERS_PATH, async () => {
        const users = await readFileUnlocked(USERS_PATH, []);
        if (findLocalUserForSession(users, sessionUser)) return { kind: 'skip' };

        return withFileLock(REFERRAL_REWARDS_PATH, async () => {
            let rewardsDoc = normalizeReferralRewardsDocument(
                await readFileUnlocked(REFERRAL_REWARDS_PATH, emptyReferralRewardsDocument())
            );
            const referrer = users.find((u) => u.id === referralCode || u.plexId === referralCode || u.jellyfinId === referralCode) || null;

            const recordRewardUnlocked = async (entry) => {
                rewardsDoc = prependReferralReward(rewardsDoc, entry);
                await writeFileUnlocked(REFERRAL_REWARDS_PATH, rewardsDoc);
                return rewardsDoc;
            };

            if (sameAccount(sessionUser, { id: referralCode, plexId: referralCode, jellyfinId: referralCode })
                || (referrer && sameAccount(sessionUser, referrer))) {
                await recordRewardUnlocked(createReferralRewardEntry({
                    status: 'blocked',
                    blockReason: 'self_referral',
                    referrer: referrer || { id: referralCode },
                    referred: sessionUser,
                    referralCode,
                    trialDays,
                    rewardDays,
                    rewardApplied: false,
                }));
                return { kind: 'blocked', reason: 'self_referral', referrer: referrer || { id: referralCode }, trialDays, rewardDays };
            }
            if (!referrer) {
                await recordRewardUnlocked(createReferralRewardEntry({
                    status: 'blocked',
                    blockReason: 'referrer_not_found',
                    referrer: { id: referralCode },
                    referred: sessionUser,
                    referralCode,
                    trialDays,
                    rewardDays,
                    rewardApplied: false,
                }));
                return { kind: 'blocked', reason: 'referrer_not_found', referrer: { id: referralCode }, trialDays, rewardDays };
            }
            if (referrer.plexAccessStatus !== 'active') {
                await recordRewardUnlocked(createReferralRewardEntry({
                    status: 'blocked',
                    blockReason: 'referrer_inactive',
                    referrer,
                    referred: sessionUser,
                    referralCode,
                    trialDays,
                    rewardDays,
                    rewardApplied: false,
                }));
                return { kind: 'blocked', reason: 'referrer_inactive', referrer, trialDays, rewardDays };
            }
            if (findGrantedRewardForReferred(rewardsDoc, sessionUser)) {
                await recordRewardUnlocked(createReferralRewardEntry({
                    status: 'blocked',
                    blockReason: 'duplicate',
                    referrer,
                    referred: sessionUser,
                    referralCode,
                    trialDays,
                    rewardDays,
                    rewardApplied: false,
                }));
                return { kind: 'blocked', reason: 'duplicate', referrer, trialDays, rewardDays };
            }

            const previousExpiryDate = referrer.expiryDate || null;
            const canApplyReward = !!previousExpiryDate;
            const newExpiryDate = canApplyReward
                ? addDays(new Date(previousExpiryDate), rewardDays).toISOString()
                : null;
            const newUserObj = {
                id: sessionUser.id,
                username: sessionUser.username,
                email: sessionUser.email || '',
                joiningDate: new Date().toISOString(),
                expiryDate: addDays(new Date(), trialDays).toISOString(),
                // Jellyfin/Emby users already authenticated on the media server.
                plexAccessStatus: isJellyfinSession ? 'active' : 'pending',
                isTrial: true,
                referredBy: referrer.id || referrer.plexId || referrer.jellyfinId || referralCode,
                referredAt: new Date().toISOString(),
            };
            if (sessionUser.plexId) newUserObj.plexId = sessionUser.plexId;
            if (sessionUser.jellyfinId) {
                newUserObj.jellyfinId = sessionUser.jellyfinId;
                newUserObj.authProvider = 'jellyfin';
            }
            if (sessionUser.thumb) newUserObj.thumb = sessionUser.thumb;
            Object.assign(newUserObj, markUserOnboardingPending(newUserObj, onboardingDoc));
            users.push(newUserObj);
            if (canApplyReward) {
                referrer.expiryDate = newExpiryDate;
            }
            await writeFileUnlocked(USERS_PATH, users);
            await recordRewardUnlocked(createReferralRewardEntry({
                status: 'granted',
                referrer,
                referred: newUserObj,
                referralCode,
                trialDays,
                rewardDays,
                rewardApplied: canApplyReward,
                previousExpiryDate,
                newExpiryDate,
            }));
            return {
                kind: 'granted',
                referrer,
                newUserObj,
                canApplyReward,
                previousExpiryDate,
                newExpiryDate,
                trialDays,
                rewardDays,
                inviteToPlex: !isJellyfinSession,
            };
        });
    });

    if (claimOutcome?.kind === 'blocked') {
        await appendAuditLog('referral_blocked', sessionUser, claimOutcome.referrer, {
            reason: claimOutcome.reason,
            trialDays: claimOutcome.trialDays,
            rewardDays: claimOutcome.rewardDays,
        });
    } else if (claimOutcome?.kind === 'granted') {
        const {
            referrer, newUserObj, canApplyReward, previousExpiryDate, newExpiryDate, inviteToPlex,
        } = claimOutcome;
        await appendAuditLog('referral_claimed', sessionUser, referrer, {
            trialDays: claimOutcome.trialDays,
            rewardDays: claimOutcome.rewardDays,
            rewardApplied: canApplyReward,
            previousExpiryDate,
            newExpiryDate,
        });
        try {
            const expiryLabel = newExpiryDate
                ? new Date(newExpiryDate).toLocaleDateString()
                : 'unlimited';
            await createInAppNotification({
                userId: referrer.id,
                type: 'referral_success',
                title: 'Your referral was successful!',
                body: canApplyReward
                    ? `${sessionUser.username} joined and ${claimOutcome.rewardDays} day${claimOutcome.rewardDays === 1 ? '' : 's'} were added to your access. New expiration: ${expiryLabel}.`
                    : `${sessionUser.username} joined via your referral link. Your account is unlimited, so no bonus days were applied.`,
                href: '/',
                meta: {
                    referredUserId: newUserObj.id,
                    referredUsername: sessionUser.username,
                    rewardDays: canApplyReward ? claimOutcome.rewardDays : 0,
                    forceUnique: true,
                },
            });
        } catch (notifyErr) {
            log(`Failed to notify referrer ${referrer.username}: ${notifyErr.message}`);
        }
        if (inviteToPlex && config.serverIdentifier && config.plexToken) {
            inviteUserToPlex(newUserObj, config).catch((e) => log('Failed to invite referral: ' + e.message));
        }
    }

    return claimOutcome || { kind: 'skip' };
};

const plexLoginFail = (req, res, message, { redirectOnSuccess = false, status = 403 } = {}) => {
    clearSessionCookie(req, res);
    if (redirectOnSuccess) {
        return res.redirect(withBasePath('/?loginError=' + encodeURIComponent(message)));
    }
    return res.status(status).json({ error: message });
};

const completePlexPortalLogin = async (req, res, {
    userData,
    authToken,
    ref,
    redirectOnSuccess = false,
    autoProvisionHomeUser = false,
} = {}) => {
    const config = await loadFile(CONFIG_PATH, {});
    await syncAdminPlexIdFromConfigToken(config);
    const adminId = await getAdminId(config);
    const isAdmin = !!(adminId && String(userData.id) === String(adminId));

    const sessionUser = {
        id: userData.uuid || String(userData.id),
        plexId: userData.id,
        email: userData.email || '',
        username: userData.username || userData.title || userData.friendlyName || 'Plex User',
        thumb: userData.thumb || null,
        isAdmin,
        ...(autoProvisionHomeUser && !isAdmin ? { plexHomeUser: true } : {}),
    };

    if (autoProvisionHomeUser && !isAdmin) {
        await ensurePortalUserForPlexHomeProfile(sessionUser);
    }

    const deletedUsers = await loadFile(DELETED_USERS_PATH, []);
    if (!isAdmin && isDeletedUser(deletedUsers, sessionUser)) {
        await appendAuditLog('login_blocked_deleted_user', sessionUser, sessionUser);
        return plexLoginFail(req, res, 'Your portal session has expired. Please contact the admin for access.', { redirectOnSuccess });
    }

    if (!isAdmin) {
        const users = await loadFile(USERS_PATH, []);
        const knownUser = findLocalUserForSession(users, sessionUser);
        const canSelfRegister = !!config.allowTemporaryAccess || (!!config.referralEnabled && !!ref);
        if (!knownUser && !canSelfRegister) {
            await appendAuditLog('login_blocked_non_member', sessionUser, sessionUser);
            log(`Plex login blocked for ${sessionUser.username}: not a portal member (admin=${isAdmin}, adminPlexId=${config.adminPlexId || 'unset'})`);
            return plexLoginFail(req, res, 'Your account is not registered for this portal.', { redirectOnSuccess });
        }
    }

    if (!isAdmin && config.referralEnabled && ref) {
        await claimReferralForSession(sessionUser, config, ref);
    }

    if (!isAdmin) {
        const usersAfterReferral = await loadFile(USERS_PATH, []);
        const knownAfterReferral = findLocalUserForSession(usersAfterReferral, sessionUser);
        if (!knownAfterReferral && !config.allowTemporaryAccess) {
            await appendAuditLog('login_blocked_non_member', sessionUser, sessionUser, {
                reason: ref ? 'referral_not_granted' : 'not_a_member',
            });
            const message = ref
                ? 'This referral link could not be used. Please contact the admin for access.'
                : 'Your account is not registered for this portal.';
            return plexLoginFail(req, res, message, { redirectOnSuccess });
        }
    }

    const token = jwt.sign(sessionUser, JWT_SECRET, { expiresIn: '7d' });
    setSessionCookie(req, res, token);
    if (isAdmin) {
        persistPlexHomeOwner(req, res, { ownerId: userData.id, authToken });
        await ensurePortalUserForNotifications(sessionUser, { config });
    }
    await updateUsers((users) => {
        if (!touchUserLastLogin(users, sessionUser, new Date().toISOString(), {
            plexAuthToken: authToken,
        })) {
            return { data: users, result: users };
        }
        return users;
    });
    await appendAuditLog('user_login', sessionUser, sessionUser);

    log(`Plex login success for ${sessionUser.username} (admin=${isAdmin}, homeUser=${!!autoProvisionHomeUser}, secureCookie=${FORCE_SECURE_COOKIES})`);

    if (redirectOnSuccess) {
        return res.redirect(withBasePath('/portal'));
    }
    return res.json({ message: 'Logged in successfully', sessionToken: token, user: sessionUser });
};

const resolvePlexHomeSwitchIdentity = async ({
    ownerToken,
    ownerUserData,
    userId,
    uuid,
    pin,
}) => {
    const pickedSelf = isSamePlexHomeUser({
        id: ownerUserData?.id,
        uuid: ownerUserData?.uuid,
        plexId: ownerUserData?.id,
    }, userId);
    if (pickedSelf) {
        return { ok: true, pickedSelf: true, needsPin: false, authToken: ownerToken, userData: ownerUserData };
    }

    const switched = await switchPlexHomeUser({
        token: ownerToken,
        userId,
        uuid,
        pin,
        headers: plexClientHeaders(ownerToken),
    });
    if (switched.needsPin) return { ok: false, pickedSelf: false, needsPin: true, authToken: '', userData: null };
    if (!switched.ok || !switched.authToken) {
        return { ok: false, pickedSelf: false, needsPin: false, authToken: '', userData: null };
    }

    const userRes = await apiFetch('https://plex.tv/api/v2/user', switched.authToken);
    if (userRes.ok) {
        return {
            ok: true,
            pickedSelf: false,
            needsPin: false,
            authToken: switched.authToken,
            userData: await userRes.json(),
        };
    }

    const homeUsers = await fetchPlexHomeUsers(ownerToken, {
        headers: plexClientHeaders(ownerToken),
    }).catch(() => []);
    const selected = findRememberedPlexHomeUser(homeUsers, userId);
    if (!selected) return { ok: false, pickedSelf: false, needsPin: false, authToken: '', userData: null };
    return {
        ok: true,
        pickedSelf: false,
        needsPin: false,
        authToken: switched.authToken,
        userData: {
            id: selected.id,
            uuid: selected.uuid || selected.id,
            username: selected.username || selected.title,
            title: selected.title,
            email: selected.email || '',
            thumb: selected.thumb,
        },
    };
};

const maybePauseForPlexHomeSelect = async (req, res, {
    authToken,
    userData,
    ref,
    isAdmin,
    redirectOnSuccess = false,
}) => {
    if (!isAdmin) return false;
    const homeUsers = await fetchPlexHomeUsers(authToken, { headers: plexClientHeaders(authToken) }).catch(() => []);
    if (!shouldOfferPlexHomeSelect(homeUsers)) return false;
    persistPlexHomeOwner(req, res, { ownerId: userData.id, authToken });

    const skipRemember = consumePlexHomeSkipRemember(req, res);
    const remembered = readPlexHomeRemember(req);
    const rememberedForThisOwner = remembered && String(remembered.ownerId) === String(userData.id);
    const rememberedForOwner = rememberedForThisOwner
        ? findRememberedPlexHomeUser(homeUsers, remembered.userId)
        : null;
    if (!skipRemember && rememberedForOwner) {
        const resolved = await resolvePlexHomeSwitchIdentity({
            ownerToken: authToken,
            ownerUserData: userData,
            userId: rememberedForOwner.id,
            pin: remembered.pin,
        });
        if (resolved.ok) {
            log(`Plex Home auto-signin as ${rememberedForOwner.title || rememberedForOwner.id}`);
            setPlexHomeRemember(req, res, {
                ownerId: userData.id,
                userId: rememberedForOwner.id,
                pin: remembered.pin,
            });
            await completePlexPortalLogin(req, res, {
                userData: resolved.userData,
                authToken: resolved.authToken,
                ref,
                redirectOnSuccess,
                autoProvisionHomeUser: !resolved.pickedSelf,
            });
            return true;
        }
        clearPlexHomeRemember(req, res);
    } else if (!skipRemember && rememberedForThisOwner) {
        clearPlexHomeRemember(req, res);
    }

    const pending = issuePlexHomeSelectPending(req, res, { authToken, userData, ref });
    const users = homeUsers.map(toPublicPlexHomeUser).filter(Boolean);
    const rememberUserId = rememberedForOwner?.id || null;
    if (redirectOnSuccess) {
        res.redirect(withBasePath('/?homeSelect=1'));
        return true;
    }
    // homeSelectToken lets Capacitor / Bearer clients continue without cookies.
    res.json({
        needsHomeSelect: true,
        users,
        rememberUserId,
        homeSelectToken: pending?.token || null,
    });
    return true;
};

const handlePlexPinLogin = async (req, res, pinId, ref, { redirectOnSuccess = false } = {}) => {
    const pinData = await fetchPlexPinAuthToken(pinId);

    if (!pinData.authToken) {
        const message = 'Plex sign-in did not complete in time — please try again';
        log(`Plex login failed for pin ${pinId}: authToken not ready`);
        if (redirectOnSuccess) {
            return res.redirect(withBasePath('/?loginError=' + encodeURIComponent(message)));
        }
        return res.status(400).json({ error: message });
    }

    const userRes = await apiFetch('https://plex.tv/api/v2/user', pinData.authToken);
    if (!userRes.ok) throw new Error('Failed to fetch user info');
    const userData = await userRes.json();

    const config = await loadFile(CONFIG_PATH, {});
    await syncAdminPlexIdFromConfigToken(config);
    const adminId = await getAdminId(config);
    const isAdmin = !!(adminId && String(userData.id) === String(adminId));

    if (await maybePauseForPlexHomeSelect(req, res, {
        authToken: pinData.authToken,
        userData,
        ref,
        isAdmin,
        redirectOnSuccess,
    })) {
        return;
    }

    return completePlexPortalLogin(req, res, {
        userData,
        authToken: pinData.authToken,
        ref,
        redirectOnSuccess,
    });
};

