app.get('/api/auth/session', publicReadRateLimit, async (req, res) => {
    const token = readSessionToken(req);
    if (!token) return res.json({ authenticated: false });
    try {
        const user = jwt.verify(token, JWT_SECRET);
        const config = await loadFile(CONFIG_PATH, {});
        const isAdmin = await resolveCurrentAdmin(user, config);
        return res.json({
            authenticated: true,
            user: {
                username: user.username,
                plexId: user.plexId,
                jellyfinId: user.jellyfinId,
                authProvider: user.authProvider || 'plex',
                isAdmin,
            },
        });
    } catch {
        return res.json({ authenticated: false, reason: 'invalid_token' });
    }
});

app.post('/api/auth/session/token', requireAuth, (req, res) => {
    const token = readSessionToken(req);
    if (!token) return res.status(401).json({ error: 'Unauthorized' });
    return res.json({ sessionToken: token });
});

app.post('/api/auth/plex/callback', authCallbackRateLimit, async (req, res) => {
    const { pinId, ref } = req.body;
    if (!pinId) return res.status(400).json({ error: 'pinId is required' });
    // Peek first so TV/native PIN polling can retry until the pin is claimed.
    if (!verifyPlexOauthState(req, pinId)) {
        return rejectPlexOauthState(req, res, { redirectOnSuccess: false });
    }

    try {
        const pinData = await fetchPlexPinAuthToken(pinId);
        if (!pinData.authToken) {
            return res.status(202).json({ pending: true, error: 'Waiting for Plex sign-in' });
        }
        clearPlexOauthState(req, res, pinId);
        await handlePlexPinLogin(req, res, pinId, ref);
    } catch (err) {
        log('Error in plex callback: ' + err.message);
        res.status(500).json({ error: 'Failed to verify login' });
    }
});

app.get('/api/auth/plex/callback', authCallbackRateLimit, async (req, res) => {
    const { pinId, ref } = req.query;
    if (!pinId) return res.redirect(withBasePath('/?loginError=' + encodeURIComponent('Missing pin ID')));
    if (!consumePlexOauthState(req, res, pinId)) {
        return rejectPlexOauthState(req, res, { redirectOnSuccess: true });
    }

    try {
        await handlePlexPinLogin(req, res, String(pinId), ref, { redirectOnSuccess: true });
    } catch (err) {
        log('Error in plex GET callback: ' + err.message);
        clearSessionCookie(req, res);
        res.redirect(withBasePath('/?loginError=' + encodeURIComponent('Login failed. Please try again.')));
    }
});

app.get('/api/auth/plex/home-users', authCallbackRateLimit, async (req, res) => {
    try {
        const pending = readPlexHomeSelectPending(req);
        if (!pending?.authToken) {
            return res.status(404).json({ error: 'Plex Home selection expired. Please sign in again.' });
        }
        const homeUsers = await fetchPlexHomeUsers(pending.authToken, {
            headers: plexClientHeaders(pending.authToken),
        }).catch(() => []);
        return res.json({
            needsHomeSelect: true,
            users: homeUsers.map(toPublicPlexHomeUser).filter(Boolean),
            rememberUserId: (() => {
                const remembered = readPlexHomeRemember(req);
                if (!remembered || String(remembered.ownerId) !== String(pending.userData?.id || '')) return null;
                return findRememberedPlexHomeUser(homeUsers, remembered.userId)?.id || null;
            })(),
        });
    } catch (err) {
        log(`Plex Home users list failed: ${err.message}`);
        return res.status(500).json({ error: 'Failed to load Plex Home profiles.' });
    }
});

app.post('/api/auth/plex/home-select/cancel', authRateLimit, async (req, res) => {
    clearPlexHomeSelectPending(req, res);
    clearSessionCookie(req, res);
    return res.json({ ok: true });
});

app.post('/api/auth/plex/home-switch', authRateLimit, async (req, res) => {
    try {
        const pending = readPlexHomeSelectPending(req);
        if (!pending?.authToken || !pending?.userData) {
            return res.status(401).json({ error: 'Plex Home selection expired. Please sign in again.' });
        }
        const userId = String(req.body?.userId || '').trim();
        const pin = String(req.body?.pin || '').trim();
        const remember = req.body?.remember === true;
        if (!userId) return res.status(400).json({ error: 'Select a Plex Home profile.' });

        const resolved = await resolvePlexHomeSwitchIdentity({
            ownerToken: pending.authToken,
            ownerUserData: pending.userData,
            userId,
            pin,
        });
        if (resolved.needsPin) {
            return res.status(401).json({ error: 'Enter the PIN for this profile.' });
        }
        if (!resolved.ok || !resolved.authToken || !resolved.userData) {
            return res.status(401).json({ error: 'Could not switch to that Plex Home profile.' });
        }

        if (remember) {
            setPlexHomeRemember(req, res, {
                ownerId: pending.userData.id,
                userId,
                pin,
            });
        } else {
            clearPlexHomeRemember(req, res);
        }

        persistPlexHomeOwner(req, res, {
            ownerId: pending.userData.id,
            authToken: pending.authToken,
        });
        clearPlexHomeSelectPending(req, res);
        return completePlexPortalLogin(req, res, {
            userData: resolved.userData,
            authToken: resolved.authToken,
            ref: pending.ref,
            autoProvisionHomeUser: !resolved.pickedSelf,
        });
    } catch (err) {
        log(`Plex Home switch failed: ${err.message}`);
        return res.status(500).json({ error: 'Failed to switch Plex Home profile.' });
    }
});

const resolvePlexHomeOwnerContext = async (req) => {
    if (isImpersonatingSession(req.user)) return null;
    const config = await loadFile(CONFIG_PATH, {});
    if (String(config?.mediaServerType || 'plex').toLowerCase() !== 'plex') return null;
    const adminId = await getAdminId(config);
    const users = await loadFile(USERS_PATH, []);
    const localUser = findLocalUserForSession(users, req.user);
    const isAdmin = !!(adminId && (
        String(req.user?.plexId || '') === String(adminId)
        || String(req.user?.id || '') === String(adminId)
    ));
    const cookie = readPlexHomeOwner(req);
    const isHomeUser = !!localUser?.plexHomeUser || !!req.user?.plexHomeUser;
    if (!sessionCanUsePlexHomeSwitch({ isAdmin, plexHomeUser: isHomeUser, hasOwnerToken: !!cookie?.authToken })) {
        return null;
    }
    const ownerId = String(cookie?.ownerId || adminId || '').trim();
    let authToken = String(cookie?.authToken || '').trim();
    if (!authToken) {
        const adminUser = (Array.isArray(users) ? users : []).find((user) => (
            String(user?.plexId || '') === String(adminId)
            || (user?.isAdmin && String(user?.id || '') === String(adminId))
        ));
        const fromAdmin = decryptPlexAuthToken(adminUser?.plexAuthToken);
        const fromLocal = isAdmin ? decryptPlexAuthToken(localUser?.plexAuthToken) : '';
        authToken = String(fromLocal || fromAdmin || '').trim();
    }
    if (!ownerId || !authToken) return null;
    return { ownerId, authToken };
};

app.get('/api/auth/plex/home-profiles', requireAuth, requireMember, async (req, res) => {
    try {
        if (blockIfImpersonating(req, res)) return;
        const owner = await resolvePlexHomeOwnerContext(req);
        if (!owner) return res.json({ available: false, users: [], currentUserId: null });
        const homeUsers = await fetchPlexHomeUsers(owner.authToken, {
            headers: plexClientHeaders(owner.authToken),
        }).catch(() => []);
        const users = homeUsers.map(toPublicPlexHomeUser).filter(Boolean);
        const inHome = sessionIsPlexHomeProfile(users, req.user);
        const adminId = String(owner.ownerId || '');
        const isOwnerSession = !!(adminId && (
            String(req.user?.plexId || '') === adminId
            || String(req.user?.id || '') === adminId
        ));
        const hasOwnerCookie = !!readPlexHomeOwner(req)?.authToken;
        if (!shouldOfferPlexHomeSelect(users) || (!inHome && !isOwnerSession && !hasOwnerCookie)) {
            return res.json({
                available: false,
                users: inHome || isOwnerSession || hasOwnerCookie ? users : [],
                currentUserId: String(req.user?.plexId || req.user?.id || ''),
            });
        }
        setPlexHomeOwner(req, res, owner);
        const remembered = readPlexHomeRemember(req);
        return res.json({
            available: true,
            users,
            currentUserId: String(req.user?.plexId || req.user?.id || ''),
            rememberUserId: remembered?.userId || null,
        });
    } catch (err) {
        log(`Plex Home profiles failed: ${err.message}`);
        return res.status(500).json({ error: 'Failed to load Plex Home profiles.' });
    }
});

app.post('/api/auth/plex/home-profiles/switch', authRateLimit, requireAuth, requireMember, async (req, res) => {
    try {
        if (blockIfImpersonating(req, res)) return;
        const owner = await resolvePlexHomeOwnerContext(req);
        if (!owner) return res.status(403).json({ error: 'Plex Home switching is not available.' });
        const userId = String(req.body?.userId || '').trim();
        const pin = String(req.body?.pin || '').trim();
        if (!userId) return res.status(400).json({ error: 'Select a Plex Home profile.' });

        const homeUsers = await fetchPlexHomeUsers(owner.authToken, {
            headers: plexClientHeaders(owner.authToken),
        }).catch(() => []);
        const ownerProfile = homeUsers.find((user) => user.admin)
            || findRememberedPlexHomeUser(homeUsers, owner.ownerId);
        const ownerUserData = {
            id: ownerProfile?.id || owner.ownerId,
            uuid: ownerProfile?.uuid || owner.ownerId,
            username: ownerProfile?.username || ownerProfile?.title || '',
            title: ownerProfile?.title || '',
            email: ownerProfile?.email || '',
            thumb: ownerProfile?.thumb || null,
        };

        const resolved = await resolvePlexHomeSwitchIdentity({
            ownerToken: owner.authToken,
            ownerUserData,
            userId,
            pin,
        });
        if (resolved.needsPin) {
            return res.status(401).json({ error: 'Enter the PIN for this profile.' });
        }
        if (!resolved.ok || !resolved.authToken || !resolved.userData) {
            return res.status(401).json({ error: 'Could not switch to that Plex Home profile.' });
        }

        persistPlexHomeOwner(req, res, owner);
        if (req.body?.remember === true) {
            setPlexHomeRemember(req, res, {
                ownerId: owner.ownerId,
                userId,
                pin,
            });
        } else if (req.body?.remember === false) {
            clearPlexHomeRemember(req, res);
        } else if (readPlexHomeRemember(req)) {
            setPlexHomeRemember(req, res, {
                ownerId: owner.ownerId,
                userId,
                pin,
            });
        }
        return completePlexPortalLogin(req, res, {
            userData: resolved.userData,
            authToken: resolved.authToken,
            autoProvisionHomeUser: !resolved.pickedSelf,
        });
    } catch (err) {
        log(`Plex Home in-session switch failed: ${err.message}`);
        return res.status(500).json({ error: 'Failed to switch Plex Home profile.' });
    }
});

const assertInitialSetupAccess = async (req, res, options = {}) => {
    const existingConfig = await loadFile(CONFIG_PATH, {});
    const isConfigured = isPortalConfigured(existingConfig);
    if (isConfigured) {
        res.status(403).json({ error: 'Portal is already configured.' });
        return false;
    }
    // Only localhost / SETUP_TOKEN — do not accept an arbitrary valid JWT while unconfigured.
    if (canRunInitialSetup(req)) return true;
    res.status(403).json({ error: 'Initial setup denied: localhost or valid setup token required.' });
    return false;
};

app.post('/api/setup/plex/callback', setupRateLimit, authRateLimit, async (req, res) => {
    // Require localhost or SETUP_TOKEN — never return a Plex owner token on an open unconfigured portal.
    if (!(await assertInitialSetupAccess(req, res))) return;
    const { pinId } = req.body;
    if (!pinId) return res.status(400).json({ error: 'pinId is required' });
    if (!consumePlexOauthState(req, res, pinId)) {
        return rejectPlexOauthState(req, res, { redirectOnSuccess: false });
    }

    try {
        const pinData = await fetchPlexPinAuthToken(pinId);
        if (!pinData.authToken) {
            return res.status(400).json({ error: 'Plex sign-in not completed yet. Please try again.' });
        }

        const userRes = await apiFetch('https://plex.tv/api/v2/user', pinData.authToken);
        if (!userRes.ok) throw new Error('Failed to fetch Plex user info');
        const userData = await userRes.json();

        const servers = await fetchOwnedPlexServers(pinData.authToken);
        if (!servers.length) {
            return res.status(400).json({ error: 'No owned Plex servers found for this account. You must sign in as the server owner.' });
        }

        res.json({
            token: pinData.authToken,
            servers,
            username: userData.username || userData.title || userData.email || 'Plex User',
            email: userData.email || '',
        });
    } catch (err) {
        log(`Setup Plex callback error: ${err.message}`);
        res.status(500).json({ error: err.message || 'Failed to complete Plex sign-in' });
    }
});

app.post('/api/auth/logout', requireAuth, (req, res) => {
    clearSessionCookie(req, res);
    res.json({ message: 'Logged out' });
});

app.post('/api/users/preferences', requireAuth, requireMember, async (req, res) => {
    if (blockIfImpersonating(req, res)) return;
    try {
        const {
            optOutNewsletter,
            notifyRequestAvailableEmail,
            notifyRequestAvailableInApp,
            notifyRequestAvailableWebPush,
            notifyRequestAvailableDiscord,
            notifyRequestApprovedEmail,
            notifyRequestApprovedInApp,
            notifyRequestApprovedWebPush,
            notifyRequestDeclinedEmail,
            notifyRequestDeclinedInApp,
            notifyRequestDeclinedWebPush,
            notifySeasonAvailableEmail,
            notifySeasonAvailableInApp,
            notifySeasonAvailableWebPush,
            notifyNewEpisodeEmail,
            notifyNewEpisodeInApp,
            notifyNewEpisodeWebPush,
            notifyCollexionsFailed,
            notifyScannerFailed,
            notifyScannerDeleted,
            notifyScannerUpgrade,
            notifyScannerImport,
            notifyScannerGrab,
            notifyScannerUpdate,
            notifyScannerInteraction,
            notifySpotifySyncFailed,
            notifyStatusDown,
            notifyStatusUp,
            notifyMediaJobFailed,
            notifyMediaJobCompleted,
            notifyTautulliApiFailed,
            notifySupportTicket,
            notifySupportReply,
            notifySupportMediaIssue,
            notifyChatMentionInApp,
            notifyWebPush,
            notifySummaryDigest,
            showDiscoverNowPlaying,
            showHomeBecauseYouWatched,
            uiLocale,
            privacyShowName,
            privacyShowPlayer,
            privacyShowAchievements,
            privacyShowProfile,
            privacyShowEmail,
            privacyShowLibraries,
            profileBio,
        } = req.body || {};
        let newsletterAuditEvent = null;
        const updatedUser = await updateUsers(async (users) => {
            const localUser = findLocalUserForSession(users, req.user);
            const userIndex = localUser ? users.findIndex(u => normalized(u.id) === normalized(localUser.id)) : -1;

            if (userIndex === -1) {
                const err = new Error('User not found');
                err.status = 404;
                throw err;
            }

            if (optOutNewsletter !== undefined) {
                const oldPref = !!users[userIndex].optOutNewsletter;
                users[userIndex].optOutNewsletter = !!optOutNewsletter;
                if (oldPref !== !!optOutNewsletter) {
                    newsletterAuditEvent = optOutNewsletter ? 'newsletter_opt_out' : 'newsletter_opt_in';
                }
            }
            if (uiLocale !== undefined) {
                const normalizedLocale = String(uiLocale || '').trim().toLowerCase().replace(/_/g, '-');
                const persistedLocale = normalizedLocale === 'pt-br' ? 'pt-BR' : normalizedLocale;
                if (!['en', 'fr', 'de', 'es', 'pt-BR', 'it', 'ja', 'pl', 'nl', 'ru'].includes(persistedLocale)) {
                    const err = new Error('Unsupported locale');
                    err.status = 400;
                    throw err;
                }
                users[userIndex].uiLocale = persistedLocale;
            }
            const boolPrefs = {
                notifyRequestAvailableEmail,
                notifyRequestAvailableInApp,
                notifyRequestAvailableWebPush,
                notifyRequestAvailableDiscord,
                notifyRequestApprovedEmail,
                notifyRequestApprovedInApp,
                notifyRequestApprovedWebPush,
                notifyRequestDeclinedEmail,
                notifyRequestDeclinedInApp,
                notifyRequestDeclinedWebPush,
                notifySeasonAvailableEmail,
                notifySeasonAvailableInApp,
                notifySeasonAvailableWebPush,
                notifyNewEpisodeEmail,
                notifyNewEpisodeInApp,
                notifyNewEpisodeWebPush,
                notifyCollexionsFailed,
                notifyScannerFailed,
                notifyScannerDeleted,
                notifyScannerUpgrade,
                notifyScannerImport,
                notifyScannerGrab,
                notifyScannerUpdate,
                notifyScannerInteraction,
                notifySpotifySyncFailed,
                notifyStatusDown,
                notifyStatusUp,
                notifyMediaJobFailed,
                notifyMediaJobCompleted,
                notifyTautulliApiFailed,
                notifySupportTicket,
                notifySupportReply,
                notifySupportMediaIssue,
                notifyChatMentionInApp,
                notifyWebPush,
                notifySummaryDigest,
                showDiscoverNowPlaying,
                showHomeBecauseYouWatched,
                privacyShowName,
                privacyShowPlayer,
                privacyShowAchievements,
                privacyShowProfile,
                privacyShowEmail,
                privacyShowLibraries,
            };
            for (const [key, value] of Object.entries(boolPrefs)) {
                if (value !== undefined) users[userIndex][key] = !!value;
            }
            if (profileBio !== undefined) {
                users[userIndex].profileBio = sanitizeProfileBio(profileBio);
            }
            return { data: users, result: users[userIndex] };
        });

        if (newsletterAuditEvent) {
            await appendAuditLog(newsletterAuditEvent, req.user, req.user);
        }
        if (privacyShowAchievements !== undefined) {
            try {
                const config = await loadFile(CONFIG_PATH, {});
                const state = await loadAchievementsState();
                const subjectId = resolveAchievementsAccountId(updatedUser, updatedUser.plexAccountId, state, {
                    username: updatedUser.username,
                    adminPlexId: config.adminPlexId,
                });
                if (subjectId) await setLeaderboardOptOut(subjectId, !updatedUser.privacyShowAchievements);
            } catch (syncError) {
                log(`[privacy] achievements opt-out sync failed: ${syncError?.message || syncError}`);
            }
        }

        res.json({ success: true, user: sanitizeUserForApi(updatedUser) });
    } catch (e) {
        if (e?.status) return res.status(e.status).json({ error: e.message });
        log(`Error updating preferences: ${e.message}`);
        res.status(500).json({ error: 'Failed to update preferences' });
    }
});

app.get('/api/notifications', requireAuth, requireMember, async (req, res) => {
    try {
        const { localUser } = await ensurePortalUserForNotifications(req.user);
        if (!localUser?.id) {
            return res.status(404).json({ error: 'User not found' });
        }
        const userIds = notificationUserIdsFor(localUser, req.user);
        const limit = Math.max(1, Math.min(100, Number(req.query?.limit) || 30));
        const unreadOnly = ['1', 'true', 'yes'].includes(String(req.query?.unreadOnly || req.query?.unread || '').toLowerCase());
        const type = String(req.query?.type || '').trim();
        const includeAdminTypes = !!req.user?.isAdmin;
        const items = await listInAppNotificationsForUser(userIds, { limit, unreadOnly, type, includeAdminTypes });
        const { unread, total } = await summarizeInAppNotificationsForUser(userIds, { includeAdminTypes });
        let enriched = items;
        try {
            const store = createRequestStore({ dataDir: REQUESTS_DIR });
            const config = await loadFile(CONFIG_PATH, {});
            const users = await loadFile(USERS_PATH, []);
            const seerrReady = requestAppService.isRequestAppConfigured(config);
            enriched = await enrichInAppNotificationItems(items, {
                getRequest: async (id) => {
                    const key = String(id || '');
                    if (key.startsWith('seerr:')) {
                        if (!seerrReady) return null;
                        const seerrId = key.slice('seerr:'.length);
                        if (!seerrId) return null;
                        const dto = await requestAppService.getRequest(config, seerrId);
                        return mapSeerrRequestToLifecycleRecord(dto, users);
                    }
                    return store.get(id);
                },
                loadUsers: async () => users,
            });
        } catch (enrichError) {
            log(`[notifications] enrich failed: ${enrichError?.message || enrichError}`);
        }
        res.set('Cache-Control', 'no-store');
        res.json({ items: enriched, unread, total });
    } catch (e) {
        log(`Error listing notifications: ${e.message}`);
        res.status(500).json({ error: 'Failed to load notifications' });
    }
});

