app.post('/api/admin/notifications/test', requireAdmin, async (req, res) => {
    if (blockIfImpersonating(req, res)) return;
    try {
        const config = await loadFile(CONFIG_PATH, {});
        const { localUser } = await ensurePortalUserForNotifications(req.user, { config });
        if (!localUser?.id) {
            return res.status(404).json({
                error: 'Admin user not found in local users store',
                hint: 'Your admin Plex/Jellyfin account is missing from users.json. Sync users or re-login, then try again.',
            });
        }
        const channels = Array.isArray(req.body?.channels) && req.body.channels.length
            ? req.body.channels.map(String)
            : ['inApp'];
        const title = String(req.body?.title || 'Test notification').slice(0, 120);
        const body = String(req.body?.body || 'This is a test from Settings → Notifications.').slice(0, 400);
        const href = '/portal';
        const results = { inApp: false, webPush: false, email: false, discord: false, errors: [] };

        if (channels.includes('inApp')) {
            try {
                const item = await createInAppNotification({
                    userId: localUser.id,
                    type: 'admin_test',
                    title,
                    body,
                    href,
                    meta: { skipWebPush: true, test: true },
                });
                results.inApp = !!item;
            } catch (error) {
                results.errors.push(`inApp: ${error?.message || error}`);
            }
        }

        if (channels.includes('webPush')) {
            try {
                const push = await sendWebPushToUser(localUser.id, {
                    title,
                    body,
                    href,
                    type: 'admin_test',
                    tag: `admin-test-${Date.now()}`,
                }, { config, user: localUser, log });
                results.webPush = (push?.sent || 0) > 0;
                if (!results.webPush) {
                    const hints = {
                        'no-subscriptions': 'no device subscribed for this admin — on this phone, install the PWA in Chrome, open it, then Send test again (or Preferences → Enable on this device)',
                        disabled: 'Web Push is turned off in Settings',
                        'user-opt-out': 'Browser push is off in Preferences for this account',
                        'expired-subscription': 'this device’s push subscription expired — Enable on this device again',
                        'send-failed': push?.error || 'FCM rejected the push',
                    };
                    results.errors.push(`webPush: ${hints[push?.skipped] || push?.error || push?.skipped || 'send failed'}`);
                }
            } catch (error) {
                results.errors.push(`webPush: ${error?.message || error}`);
            }
        }

        if (channels.includes('email')) {
            try {
                if (!localUser.email) {
                    results.errors.push('email: admin account has no email');
                } else {
                    const html = `<p>${body}</p><p style="color:#888;font-size:12px;">Sent from Settings → Notifications test.</p>`;
                    results.email = !!(await sendEmail(config, localUser.email, `[${config.serverName || 'Portal'}] ${title}`, html));
                }
            } catch (error) {
                results.errors.push(`email: ${error?.message || error}`);
            }
        }

        if (channels.includes('discord')) {
            try {
                results.discord = !!(await notifyRequestAvailableDiscord({
                    config: {
                        ...config,
                        requestAvailableNotifyEnabled: true,
                        requestAvailableNotifyDiscord: true,
                    },
                    user: localUser,
                    username: localUser.username || 'Admin',
                    title,
                    year: null,
                    mediaType: 'movie',
                    ctaUrl: resolvePublicBaseUrlFromConfig(config) || href,
                    log,
                }));
                if (!results.discord) {
                    results.errors.push('discord: webhook not configured or disabled');
                }
            } catch (error) {
                results.errors.push(`discord: ${error?.message || error}`);
            }
        }

        if (channels.includes('ntfy')) {
            try {
                results.ntfy = !!(await notifyNtfyEvent({
                    config: {
                        ...config,
                        ntfyEnabled: true,
                        ntfyEvents: { ...normalizeNtfyEvents(config.ntfyEvents), available: true },
                    },
                    event: 'available',
                    title,
                    body,
                    clickUrl: resolvePublicBaseUrlFromConfig(config) || href,
                    log,
                }));
                if (!results.ntfy) {
                    results.errors.push('ntfy: not configured or disabled');
                }
            } catch (error) {
                results.errors.push(`ntfy: ${error?.message || error}`);
            }
        }

        if (channels.includes('webhook')) {
            try {
                results.webhook = !!(await sendGenericWebhook({
                    config: {
                        ...config,
                        webhookEnabled: true,
                        webhookEvents: { ...normalizeWebhookEvents(config.webhookEvents), available: true },
                    },
                    event: 'available',
                    vars: {
                        title,
                        user: localUser.username || 'Admin',
                        media_type: 'movie',
                        status: 'Test',
                        portal_url: resolvePublicBaseUrlFromConfig(config) || href,
                        server_name: config.serverName || 'StreamPilot',
                    },
                    log,
                }));
                if (!results.webhook) {
                    results.errors.push('webhook: not configured or disabled');
                }
            } catch (error) {
                results.errors.push(`webhook: ${error?.message || error}`);
            }
        }

        res.json({
            success: results.inApp || results.webPush || results.email || results.discord || results.ntfy || results.webhook,
            userId: localUser.id,
            username: localUser.username || null,
            results,
        });
    } catch (e) {
        log(`Error sending notification test: ${e.message}`);
        res.status(500).json({ error: e.message || 'Failed to send test notification' });
    }
});

app.get('/api/users/me', requireAuth, async (req, res) => {
    const users = await loadFile(USERS_PATH, []);
    const localUser = findLocalUserForSession(users, req.user);
    const deletedUsers = await loadFile(DELETED_USERS_PATH, []);
    const config = await loadFile(CONFIG_PATH, {});
    const impersonating = isImpersonatingSession(req.user);
    const actor = getSessionActor(req.user);
    const realIsAdmin = await resolveCurrentAdmin(actor, config);
    const isAdmin = impersonating ? false : realIsAdmin;
    req.user.isAdmin = isAdmin;

    if (!localUser && !realIsAdmin && isDeletedUser(deletedUsers, req.user)) {
        await appendAuditLog('session_blocked_deleted_user', req.user, req.user);
        clearSessionCookie(req, res);
        return res.status(403).json({ error: 'Your portal session has expired. Please contact the admin for access.' });
    }

    const mediaServerType = String(config?.mediaServerType || 'plex').toLowerCase();
    const mediaServerLabel = mediaServerType === 'emby' ? 'Emby' : mediaServerType === 'jellyfin' ? 'Jellyfin' : 'Plex';
    const isJellyfinPortal = ['jellyfin', 'emby'].includes(mediaServerType);
    let serverName = isJellyfinPortal ? `${mediaServerLabel} Server` : 'Plex Server';
    let adminThumb = null;
    let sessionThumb = req.user.thumb || localUser?.thumb || null;
    let requestUrl = config.requestUrl || 'https://yourdomain.com';
    if ((requestUrl === 'https://yourdomain.com' || !requestUrl) && config.requestAppUrl) {
        requestUrl = config.requestAppUrl;
    }
    let navOrder = Array.isArray(config.navOrder) && config.navOrder.length
        ? [...config.navOrder]
        : ['home', 'discover', 'request', 'analytics', 'users', 'downloads', 'upgrader', 'collexions', 'mediastack', 'requests', 'status', 'maintenance', 'about', 'settings', 'logout'];
    // Migrate known legacy stock defaults to the current default without clobbering custom orders
    const legacyNavOrders = [
        ['home', 'discover', 'users', 'status', 'analytics', 'downloads', 'mediastack', 'maintenance', 'request', 'about', 'settings', 'logout'],
        ['home', 'discover', 'users', 'analytics', 'downloads', 'mediastack', 'upgrader', 'requests', 'status', 'maintenance', 'request', 'about', 'logs', 'settings', 'logout'],
        ['home', 'discover', 'status', 'analytics', 'request', 'users', 'downloads', 'mediastack', 'maintenance', 'about', 'settings', 'logout'],
        ['home', 'discover', 'request', 'analytics', 'users', 'downloads', 'upgrader', 'mediastack', 'requests', 'status', 'maintenance', 'about', 'settings', 'logout'],
    ];
    if (legacyNavOrders.some((legacy) => legacy.length === navOrder.length && legacy.every((key, i) => key === navOrder[i]))) {
        navOrder = ['home', 'discover', 'request', 'analytics', 'users', 'downloads', 'upgrader', 'collexions', 'mediastack', 'requests', 'status', 'maintenance', 'about', 'settings', 'logout'];
    }
    // Ensure newly added stock items appear for custom orders too.
    if (!navOrder.includes('collexions')) {
        const upgraderIdx = navOrder.indexOf('upgrader');
        if (upgraderIdx >= 0) navOrder.splice(upgraderIdx + 1, 0, 'collexions');
        else {
            const downloadsIdx = navOrder.indexOf('downloads');
            if (downloadsIdx >= 0) navOrder.splice(downloadsIdx + 1, 0, 'collexions');
            else navOrder.splice(Math.max(0, navOrder.length - 2), 0, 'collexions');
        }
    }
    if (!navOrder.includes('spotify-sync')) {
        const collexionsIdx = navOrder.indexOf('collexions');
        if (collexionsIdx >= 0) navOrder.splice(collexionsIdx + 1, 0, 'spotify-sync');
        else {
            const upgraderIdx = navOrder.indexOf('upgrader');
            if (upgraderIdx >= 0) navOrder.splice(upgraderIdx + 1, 0, 'spotify-sync');
            else navOrder.splice(Math.max(0, navOrder.length - 2), 0, 'spotify-sync');
        }
    }
    if (!navOrder.includes('watch-sync')) {
        const editionsIdx = navOrder.indexOf('editions');
        const anchor = editionsIdx >= 0 ? editionsIdx : navOrder.indexOf('overlays');
        if (anchor >= 0) navOrder.splice(anchor + 1, 0, 'watch-sync');
        else navOrder.splice(Math.max(0, navOrder.length - 2), 0, 'watch-sync');
    }
    try {
        if (isJellyfinPortal && config?.jellyfinUrl && config?.jellyfinApiKey) {
            if (String(config.serverName || '').trim()) {
                serverName = String(config.serverName).trim();
            } else {
                const profile = await getAdminProfile(config);
                serverName = profile.serverName || `${mediaServerLabel} Server`;
            }
        } else if (config && config.plexToken && config.serverIdentifier) {
            const profile = await getAdminProfile(config);
            serverName = String(config.serverName || '').trim() || profile.serverName || 'Plex Server';
            adminThumb = profile.thumb;

            // Skip Plex /accounts fan-out when session or portal user already has a thumb.
            // Home managed profiles must not inherit the owner's PMS account avatar.
            const isPlexHomeProfile = !!(req.user?.plexHomeUser || localUser?.plexHomeUser);
            if (!sessionThumb && !isPlexHomeProfile) {
                const uri = await getPlexConnectionUri(config);
                if (uri) {
                    const accountId = await resolveLocalPlexAccountId(config, uri, req.user);
                    const { map } = await fetchPlexServerAccounts(uri, config);
                    if (accountId && map[accountId]?.thumb) {
                        sessionThumb = map[accountId].thumb;
                    }
                }
            }
        }
    } catch (e) { }

    if (impersonating && localUser?.thumb) {
        sessionThumb = localUser.thumb;
    }

    if (localUser && reconcileTrialAccessFlag(localUser)) {
        await patchUserById(localUser.id, (entry) => {
            reconcileTrialAccessFlag(entry);
        });
    }

    const { actor: _actor, impersonatingUserId, ...sessionPublic } = req.user;

    const requestAppType = config.requestAppType === 'overseerr' ? 'seerr' : (config.requestAppType || 'none');
    const resolvedRequestUrl = requestUrl;
    const isPlexMediaServer = String(config.mediaServerType || 'plex').toLowerCase() === 'plex';
    const portalRequestNav = isPortalRequestNavReady(config);
    const seerrRequestNav = !!(
        requestAppType
        && requestAppType !== 'none'
        && resolvedRequestUrl
        && resolvedRequestUrl !== 'https://yourdomain.com'
    );
    const navFeatures = {
        maintenance: !!config.maintenanceExperimentalEnabled,
        upgrader: !!config.upgraderEnabled,
        // Collexions is Plex-only — hide for Jellyfin/Emby even if the flag is on.
        collexions: !!config.collexionsEnabled && isPlexMediaServer,
        spotifySync: !!config.spotifyToPlexEnabled && isPlexMediaServer,
        spotifySyncHomeWidget: !!config.spotifyToPlexEnabled && isPlexMediaServer && !!config.spotifyToPlexHomeWidgetEnabled,
        scanner: !!config.scannerEnabled,
        scannerHomeWidget: !!config.scannerEnabled && !!config.scannerHomeWidgetEnabled,
        mediaAutomation: !!config.mediaAutomationEnabled,
        mediaAutomationHomeWidget: !!config.mediaAutomationEnabled && !!config.mediaAutomationHomeWidgetEnabled,
        posterSets: !!config.posterSetsEnabled,
        overlays: !!config.overlaysEnabled,
        editions: !!config.editionsEnabled && isPlexMediaServer,
        watchSync: !!config.watchSyncEnabled && isPlexMediaServer,
        achievements: !!config.achievementsEnabled,
        achievementsLeaderboard: !!config.achievementsEnabled && config.achievementsLeaderboardEnabled !== false,
        support: config.supportTicketsEnabled !== false,
        chat: !!config.chatEnabled,
        // Portal engine unlocks Discover; Seerr URL still works when using Seerr as engine.
        request: portalRequestNav || seerrRequestNav,
        requestsQueue: portalRequestNav || requestAppService.isRequestAppConfigured(config),
        downloads: config.downloadsVisibleToMembers !== false,
        mediaPlayer: isPlexMediaServer && config.mediaPlayerEnabled !== false,
    };

    // Non-admin expired members: restrict to support / chat / profile / preferences (#187).
    const accessExpired = !isAdmin && !!localUser && isAccessExpired(localUser);
    if (accessExpired) {
        Object.keys(navFeatures).forEach((key) => {
            if (key === 'support' || key === 'chat') return;
            navFeatures[key] = false;
        });
        navFeatures.support = config.supportTicketsEnabled !== false;
        navFeatures.chat = !!config.chatEnabled;
    }

    const expiredPortalTitle = String(config.expiredPortalTitle || '').trim();
    const expiredPortalMessage = String(config.expiredPortalMessage || '').trim();
    const onboardingDoc = normalizeOnboardingDocument(
        await loadFile(ONBOARDING_PATH, emptyOnboardingDocument())
    );
    const needsOnboarding = isOnboardingPending(localUser, onboardingDoc, { isAdmin });

    res.json({
        session: { ...sessionPublic, thumb: sessionThumb, isAdmin },
        account: localUser ? sanitizeUserForApi(localUser) : null,
        accessExpired,
        needsOnboarding,
        onboardingVersion: onboardingDoc.version,
        expiredPortal: accessExpired ? {
            title: expiredPortalTitle || null,
            message: expiredPortalMessage || null,
            expiryDate: localUser?.expiryDate || null,
            plexAccessStatus: localUser?.plexAccessStatus || null,
        } : null,
        serverName,
        adminThumb,
        mediaServerType: config.mediaServerType || 'plex',
        requestUrl,
        navOrder,
        navHiddenKeys: Array.isArray(config.navHiddenKeys)
            ? config.navHiddenKeys.filter((key) => typeof key === 'string' && key && key !== 'home' && key !== 'settings' && key !== 'logout')
            : [],
        memberNavOrder: Array.isArray(config.memberNavOrder) ? config.memberNavOrder : [],
        memberNavHiddenKeys: Array.isArray(config.memberNavHiddenKeys)
            ? config.memberNavHiddenKeys.filter((key) => typeof key === 'string' && key && key !== 'home' && key !== 'logout')
            : [],
        customNavTabs: accessExpired ? [] : sanitizeCustomNavTabsForSession(config.customNavTabs),
        navItemIcons: sanitizeNavItemIcons(config.navItemIcons),
        customNavDisplay: normalizeCustomNavDisplay(config.customNavDisplay),
        arrOpenInPortalEmbed: !!config.arrOpenInPortalEmbed,
        homeCustomModules: accessExpired ? [] : sanitizeHomeCustomModulesForSession(config.homeCustomModules, isAdmin),
        navFeatures,
        impersonation: impersonating ? {
            active: true,
            targetUserId: impersonatingUserId,
            targetUsername: localUser?.username || req.user.username,
            adminUsername: actor?.username || null,
        } : { active: false },
    });
});

app.post('/api/admin/impersonate/:userId', requireAdmin, async (req, res) => {
    try {
        const config = await loadFile(CONFIG_PATH, {});
        const actor = getSessionActor(req.user);
        const users = await loadFile(USERS_PATH, []);
        const deletedUsers = await loadFile(DELETED_USERS_PATH, []);
        const targetUser = users.find((user) => normalized(user.id) === normalized(req.params.userId));

        if (!targetUser) {
            return res.status(404).json({ error: 'User not found.' });
        }
        if (isDeletedUser(deletedUsers, targetUser)) {
            return res.status(400).json({ error: 'Cannot view portal as a removed user.' });
        }

        const targetIsAdmin = await resolveCurrentAdmin({
            plexId: targetUser.plexId || targetUser.id,
            jellyfinId: targetUser.jellyfinId,
            authProvider: ['jellyfin', 'emby'].includes(String(config?.mediaServerType || '').toLowerCase()) ? 'jellyfin' : undefined,
            username: targetUser.username,
        }, config);
        if (targetIsAdmin) {
            return res.status(403).json({ error: 'Cannot impersonate an administrator account.' });
        }

        const sessionUser = buildImpersonationSessionUser(actor, targetUser, config);
        const token = jwt.sign(sessionUser, JWT_SECRET, { expiresIn: '7d' });
        setSessionCookie(req, res, token);
        await appendAuditLog('impersonation_start', actor, targetUser);
        res.json({
            success: true,
            impersonation: {
                active: true,
                targetUserId: targetUser.id,
                targetUsername: targetUser.username,
                adminUsername: actor.username,
            },
        });
    } catch (e) {
        log(`Impersonation start failed: ${e.message}`);
        res.status(500).json({ error: 'Failed to start impersonation.' });
    }
});

app.post('/api/admin/stop-impersonation', requireAuth, async (req, res) => {
    try {
        if (!isImpersonatingSession(req.user)) {
            return res.json({ success: true, alreadyStopped: true });
        }

        const actor = req.user.actor;
        const target = { id: req.user.impersonatingUserId, username: req.user.username };
        const adminSession = buildAdminSessionFromActor(actor);
        const token = jwt.sign(adminSession, JWT_SECRET, { expiresIn: '7d' });
        setSessionCookie(req, res, token);
        await appendAuditLog('impersonation_stop', actor, target);
        res.json({ success: true });
    } catch (e) {
        log(`Impersonation stop failed: ${e.message}`);
        res.status(500).json({ error: 'Failed to stop impersonation.' });
    }
});

const DEFAULT_DASHBOARD_LAYOUT = {
    version: 1,
    sections: ['wrapUp', 'mainGrid', 'pendingRequests', 'watchRow', 'scanner', 'mediaAutomation', 'recentlyAdded', 'bazarrTools'],
    mainGridOrder: [
        'adminBadge', 'quickActions', 'expiringMembers', 'achievements', 'homeNotifications',
        'accessStatus', 'announcement', 'referral',
        'support', 'libraryStats', 'collexions', 'analytics'
    ],
    recentlyAddedOrder: ['recentMovies', 'recentShows', 'recentMusic'],
    hiddenSections: [],
    hiddenWidgets: [],
    widgetSizes: {},
    widgetColumns: {},
    recentHistoryRows: 4,
    topWatchedRows: 1
};

const DASHBOARD_SECTIONS = ['wrapUp', 'mainGrid', 'pendingRequests', 'watchRow', 'scanner', 'mediaAutomation', 'recentlyAdded', 'bazarrTools'];
const DASHBOARD_MAIN_GRID_WIDGETS = [
    'adminBadge', 'accessStatus', 'tempAccessSetup', 'quickActions', 'expiringMembers', 'achievements',
    'homeNotifications', 'announcement',
    'referral', 'support', 'libraryStats', 'collexions', 'analytics'
];
const DASHBOARD_RECENTLY_ADDED_WIDGETS = ['recentMovies', 'recentShows', 'recentMusic'];
const DASHBOARD_WIDGETS = [...DASHBOARD_MAIN_GRID_WIDGETS, ...DASHBOARD_RECENTLY_ADDED_WIDGETS];
const DASHBOARD_WIDGET_SIZES = ['compact', 'normal', 'wide', 'full'];

const DOWNLOAD_CLIENT_TYPES = ['qbittorrent', 'rdtclient', 'transmission', 'bittorrent', 'deluge', 'sabnzbd', 'nzbget'];
const DOWNLOAD_CLIENT_TYPE_ALIASES = {
    'rdt-client': 'rdtclient',
    rdt_client: 'rdtclient',
    'real-debrid': 'rdtclient',
    realdebrid: 'rdtclient',
    'real-debrid-client': 'rdtclient',
};
const downloadClientLabel = (type) => ({
    qbittorrent: 'qBittorrent',
    rdtclient: 'Real-Debrid Client',
    transmission: 'Transmission',
    bittorrent: 'BitTorrent',
    deluge: 'Deluge',
    sabnzbd: 'SABnzbd',
    nzbget: 'NZBGet',
}[type] || 'Download Client');
const normalizeDownloadClientType = (raw) => {
    const value = String(raw || '').toLowerCase();
    const aliased = DOWNLOAD_CLIENT_TYPE_ALIASES[value] || value;
    return DOWNLOAD_CLIENT_TYPES.includes(aliased) ? aliased : 'qbittorrent';
};

const normalizeDownloadClients = (incoming, existing = [], { resolveSecret = (v) => v, resolveConfigIntegrationUrl = (v) => String(v || '').trim(), secretMask = SECRET_MASK } = {}) => {
    if (!Array.isArray(incoming)) return Array.isArray(existing) ? existing : [];
    const existingById = new Map((Array.isArray(existing) ? existing : []).map((entry) => [String(entry.id), entry]));
    return incoming.slice(0, 20).map((raw, index) => {
        const type = normalizeDownloadClientType(raw?.type);
        const id = String(raw?.id || `${type}-${Date.now()}-${index}`);
        const previous = existingById.get(id) || {};
        const safeUrl = resolveConfigIntegrationUrl(raw?.url, previous.url || '');
        const password = resolveSecret(raw?.password, previous.password || '');
        return {
            id,
            type,
            name: String(raw?.name || previous.name || downloadClientLabel(type)).trim() || downloadClientLabel(type),
            url: safeUrl,
            username: String(raw?.username ?? previous.username ?? ''),
            password: password === secretMask ? (previous.password || '') : String(password || ''),
            enabled: raw?.enabled !== false,
        };
    }).filter((entry) => entry.url || entry.username || entry.password || entry.name);
};

const maskDownloadClientsForApi = (clients = [], secretMask = SECRET_MASK) => (
    (Array.isArray(clients) ? clients : []).map((entry) => ({
        id: entry.id,
        type: entry.type,
        name: entry.name || downloadClientLabel(entry.type),
        url: entry.url || '',
        username: entry.username || '',
        password: entry.password ? secretMask : '',
        enabled: entry.enabled !== false,
    }))
);

const migrateDashboardSections = (sections) => {
    const next = sections.filter((id, index) => id !== 'pendingRequests' || sections.indexOf('pendingRequests') === index);
    const mainGridIndex = next.indexOf('mainGrid');
    if (!next.includes('pendingRequests') && mainGridIndex >= 0) {
        next.splice(mainGridIndex + 1, 0, 'pendingRequests');
    } else if (!next.includes('pendingRequests')) {
        next.push('pendingRequests');
    }
    // Only seed missing sections — do not force-reorder (that fought Home Layout drag/save).
    if (!next.includes('scanner')) {
        const ra = next.indexOf('recentlyAdded');
        if (ra >= 0) next.splice(ra, 0, 'scanner');
        else next.push('scanner');
    }
    if (!next.includes('mediaAutomation')) {
        const scannerIndex = next.indexOf('scanner');
        const recentlyAddedIndex = next.indexOf('recentlyAdded');
        const insertAt = scannerIndex >= 0 ? scannerIndex + 1 : recentlyAddedIndex;
        if (insertAt >= 0) next.splice(insertAt, 0, 'mediaAutomation');
        else next.push('mediaAutomation');
    }
    if (!next.includes('bazarrTools')) next.push('bazarrTools');
    return next;
};

const migrateMainGridOrder = (order) => {
    const list = Array.isArray(order) ? [...order] : [];
    const achIdx = list.indexOf('achievements');
    const qaIdx = list.indexOf('quickActions');
    if (achIdx < 0 || qaIdx < 0) return list;
    if (achIdx === qaIdx + 1) return list;
    const analyticsIdx = list.indexOf('analytics');
    const looksLikeOldDefault =
        achIdx === list.length - 1
        || (analyticsIdx >= 0 && achIdx === analyticsIdx + 1);
    if (!looksLikeOldDefault) return list;
    const next = list.filter((id) => id !== 'achievements');
    next.splice(next.indexOf('quickActions') + 1, 0, 'achievements');
    return next;
};

const normalizeDashboardLayout = (raw, options = {}) => {
    const moduleIds = new Set(
        normalizeHomeCustomModules(options.homeCustomModules || [])
            .filter((module) => module.enabled)
            .map((module) => module.id),
    );
    const uniqueValid = (values, allowed, fallback, fillMissing = true) => {
        if (!Array.isArray(values)) return [...fallback];
        const seen = new Set();
        const result = [];
        values.forEach((value) => {
            if (typeof value !== 'string' || !allowed.includes(value) || seen.has(value)) return;
            seen.add(value);
            result.push(value);
        });
        if (fillMissing) {
            // Insert missing ids beside their default neighbors (not always at the end),
            // so new sections like mediaAutomation don't get stuck under Bazarr.
            allowed.forEach((id, defaultIndex) => {
                if (seen.has(id)) return;
                let insertAt = result.length;
                for (let i = defaultIndex - 1; i >= 0; i -= 1) {
                    const prevIdx = result.indexOf(allowed[i]);
                    if (prevIdx >= 0) {
                        insertAt = prevIdx + 1;
                        break;
                    }
                }
                if (insertAt === result.length) {
                    for (let i = defaultIndex + 1; i < allowed.length; i += 1) {
                        const nextIdx = result.indexOf(allowed[i]);
                        if (nextIdx >= 0) {
                            insertAt = nextIdx;
                            break;
                        }
                    }
                }
                result.splice(insertAt, 0, id);
                seen.add(id);
            });
        }
        return result;
    };
    const normalizeWidgetSizes = (values) => {
        if (!values || typeof values !== 'object') return {};
        return Object.entries(values).reduce((result, [key, value]) => {
            if (DASHBOARD_WIDGETS.includes(key) && DASHBOARD_WIDGET_SIZES.includes(value) && value !== 'normal') {
                result[key] = value;
            }
            return result;
        }, {});
    };
    const normalizeWidgetColumns = (values) => {
        if (!values || typeof values !== 'object') return {};
        return Object.entries(values).reduce((result, [key, value]) => {
            if (!DASHBOARD_WIDGETS.includes(key)) return result;
            const column = Math.max(1, Math.min(12, Math.floor(Number(value))));
            if (Number.isFinite(column)) result[key] = column;
            return result;
        }, {});
    };
    const input = raw && typeof raw === 'object' ? raw : {};
    return {
        version: 1,
        sections: migrateDashboardSections(normalizeDashboardSectionIds(input.sections, DASHBOARD_SECTIONS, DEFAULT_DASHBOARD_LAYOUT.sections, moduleIds)),
        mainGridOrder: migrateMainGridOrder(uniqueValid(input.mainGridOrder, DASHBOARD_MAIN_GRID_WIDGETS, DEFAULT_DASHBOARD_LAYOUT.mainGridOrder)),
        recentlyAddedOrder: uniqueValid(input.recentlyAddedOrder, DASHBOARD_RECENTLY_ADDED_WIDGETS, DEFAULT_DASHBOARD_LAYOUT.recentlyAddedOrder),
        hiddenSections: normalizeDashboardSectionIds(input.hiddenSections, DASHBOARD_SECTIONS, [], moduleIds, { fillMissingBuiltIn: false }),
        hiddenWidgets: uniqueValid(input.hiddenWidgets, DASHBOARD_WIDGETS, [], false),
        widgetSizes: normalizeWidgetSizes(input.widgetSizes),
        widgetColumns: normalizeWidgetColumns(input.widgetColumns),
        recentHistoryRows: typeof input.recentHistoryRows === 'number' ? input.recentHistoryRows : DEFAULT_DASHBOARD_LAYOUT.recentHistoryRows,
        topWatchedRows: typeof input.topWatchedRows === 'number' ? input.topWatchedRows : DEFAULT_DASHBOARD_LAYOUT.topWatchedRows
    };
};

const normalizeSectionLayout = (raw, options = {}) => {
    const normalized = normalizeDashboardLayout(raw, options);
    const input = raw && typeof raw === 'object' ? raw : null;
    if (!input || !Array.isArray(input.hiddenSections)) {
        return { ...normalized, hiddenSections: [] };
    }
    if (normalized.hiddenSections.length >= normalized.sections.length) {
        return { ...normalized, hiddenSections: [] };
    }
    if (normalized.hiddenWidgets.length >= DASHBOARD_WIDGETS.length) {
        return { ...normalized, hiddenWidgets: [] };
    }
    return normalized;
};

