let discoveryAvailabilityCacheMemo = null;
let discoveryAvailabilityCacheMemoAt = 0;
const DISCOVERY_AVAILABILITY_MEMO_TTL_MS = 90 * 1000;

const loadDiscoveryAvailabilityCacheFile = async ({ force = false } = {}) => {
    if (
        !force
        && discoveryAvailabilityCacheMemo
        && (Date.now() - discoveryAvailabilityCacheMemoAt) < DISCOVERY_AVAILABILITY_MEMO_TTL_MS
    ) {
        return discoveryAvailabilityCacheMemo;
    }
    discoveryAvailabilityCacheMemo = normalizeDiscoveryAvailabilityCache(
        await loadFile(DISCOVERY_AVAILABILITY_CACHE_PATH, emptyDiscoveryAvailabilityCache()),
    );
    discoveryAvailabilityCacheMemoAt = Date.now();
    return discoveryAvailabilityCacheMemo;
};

const invalidateDiscoveryAvailabilityCacheMemo = () => {
    discoveryAvailabilityCacheMemo = null;
    discoveryAvailabilityCacheMemoAt = 0;
};

/** Fingerprint Plex/*arr* settings that affect Discover availability badges. */
const discoveryLibraryStackFingerprint = (cfg) => JSON.stringify({
    plexToken: cfg?.plexToken || '',
    plexServerUrl: cfg?.plexServerUrl || '',
    serverIdentifier: cfg?.serverIdentifier || '',
    sonarrUrl: cfg?.sonarrUrl || '',
    sonarrApiKey: cfg?.sonarrApiKey || '',
    radarrUrl: cfg?.radarrUrl || '',
    radarrApiKey: cfg?.radarrApiKey || '',
    arrInstances: cfg?.arrInstances ?? null,
    discoverySource: cfg?.discoverySource || '',
    requestEngine: cfg?.requestEngine || '',
    mediaServerType: cfg?.mediaServerType || '',
});

/** Overlay the current member's active portal requests onto discover items (Requested badges). */
const memberActiveRequestsOverlayCache = new Map(); // userKey → { at, byKey: Map }
const MEMBER_ACTIVE_REQUESTS_OVERLAY_TTL_MS = 20 * 1000;
const MEMBER_ACTIVE_REQUESTS_OVERLAY_MAX_ENTRIES = 200;

const pruneMemberActiveRequestsOverlayCache = () => {
    const now = Date.now();
    for (const [key, entry] of memberActiveRequestsOverlayCache.entries()) {
        if (!entry || now - entry.at >= MEMBER_ACTIVE_REQUESTS_OVERLAY_TTL_MS) {
            memberActiveRequestsOverlayCache.delete(key);
        }
    }
    while (memberActiveRequestsOverlayCache.size > MEMBER_ACTIVE_REQUESTS_OVERLAY_MAX_ENTRIES) {
        const oldest = memberActiveRequestsOverlayCache.keys().next().value;
        if (oldest === undefined) break;
        memberActiveRequestsOverlayCache.delete(oldest);
    }
};

/** Prefer on-disk library state over stale request PROCESSING stamps on browse cards. */
const resolveDiscoveryItemLibraryMediaStatus = (item = {}, mediaInfo = {}) => {
    const current = Number(mediaInfo?.status);
    if (current === 5) return 5;
    if (current === 4) return 4;
    const radarr = item?.radarrLibraryStatus;
    if (radarr?.matched && radarr?.hasFile) {
        return radarr.downloading ? 3 : 5;
    }
    const sonarr = item?.sonarrLibraryStatus;
    if (sonarr?.matched && !sonarr?.hasActiveDownloads) {
        if (sonarr.showComplete) return 5;
        const fileCount = Number(sonarr.fileCount ?? sonarr.episodeFileCount) || 0;
        const hasFiles = fileCount > 0
            || (Array.isArray(sonarr.seasons) && sonarr.seasons.some((season) => (
                Number(season?.withFile) > 0 || Number(season?.airedWithFile) > 0
            )));
        // Continuing / still-airing shows are Partial in Seerr, not Requested.
        if (hasFiles) return 4;
    }
    const lidarr = item?.lidarrLibraryStatus;
    if (lidarr?.matched && !lidarr?.hasActiveDownloads) {
        return lidarr?.hasFile ? 5 : 4;
    }
    return null;
};

const overlayPortalPendingRequestsOntoItems = async (config, sessionUser, items = []) => {
    if (getRequestEngine(config) !== 'portal' || !sessionUser || !Array.isArray(items) || !items.length) {
        return items;
    }
    try {
        const userKey = String(sessionUser?.id || sessionUser?.plexId || '');
        let activeByKey = null;
        const cached = userKey ? memberActiveRequestsOverlayCache.get(userKey) : null;
        if (cached && (Date.now() - cached.at) < MEMBER_ACTIVE_REQUESTS_OVERLAY_TTL_MS) {
            activeByKey = cached.byKey;
        } else {
            if (cached && userKey) memberActiveRequestsOverlayCache.delete(userKey);
            const portalRequests = getPortalRequestService(config);
            // Include pending + approved — auto-approve clears "pending" immediately and was
            // leaving detail pages stuck on "Request Movie".
            const listed = await portalRequests.listMemberRequests(sessionUser, {
                filter: 'all',
                take: 200,
                skip: 0,
            });
            activeByKey = new Map();
            for (const row of listed.results || []) {
                const status = Number(row?.status);
                // Skip terminal states; library cache still owns Available/Partial.
                if (status === 3 || status === 4) continue; // declined / failed
                const mediaType = row?.type === 'tv'
                    ? 'tv'
                    : (row?.type === 'music' ? 'music' : 'movie');
                let key = null;
                if (mediaType === 'music') {
                    const mbid = String(row?.mbid || '').trim();
                    if (!mbid) continue;
                    key = `music:${mbid}`;
                } else {
                    const tmdbId = Number(row?.tmdbId);
                    if (!Number.isFinite(tmdbId) || tmdbId <= 0) continue;
                    key = `${mediaType}:${tmdbId}`;
                }
                const existing = activeByKey.get(key);
                // Prefer pending over approved when both exist (HD + later update).
                if (!existing || (status === 1 && Number(existing.status) !== 1)) {
                    activeByKey.set(key, row);
                }
            }
            if (userKey) {
                pruneMemberActiveRequestsOverlayCache();
                memberActiveRequestsOverlayCache.set(userKey, { at: Date.now(), byKey: activeByKey });
            }
        }
        if (!activeByKey.size) return items;
        return items.map((item) => {
            const isMusic = item?.mediaType === 'music' || item?.type === 'music';
            const mediaType = item?.mediaType === 'tv' || item?.mediaType === 2 || item?.mediaType === '2'
                ? 'tv'
                : (isMusic ? 'music' : 'movie');
            let key = null;
            if (mediaType === 'music') {
                const mbid = String(item?.mbid ?? item?.id ?? '').trim();
                if (mbid) key = `music:${mbid}`;
            } else {
                const tmdbId = Number(item?.tmdbId ?? item?.id);
                if (Number.isFinite(tmdbId) && tmdbId > 0) key = `${mediaType}:${tmdbId}`;
            }
            const active = key ? activeByKey.get(key) : null;
            if (!active) return item;
            const mediaInfo = { ...(item?.mediaInfo || {}) };
            const requestStatus = Number(active.status) || 1;
            mediaInfo.requests = [
                {
                    id: active.id,
                    status: requestStatus,
                    is4k: !!active.is4k,
                    createdAt: active.createdAt,
                },
                ...(Array.isArray(mediaInfo.requests) ? mediaInfo.requests : []),
            ];
            const libraryStatus = resolveDiscoveryItemLibraryMediaStatus(item, mediaInfo);
            if (libraryStatus === 5) {
                mediaInfo.status = 5;
                return { ...item, mediaInfo };
            }
            if (libraryStatus === 4) {
                mediaInfo.status = 4;
                return { ...item, mediaInfo };
            }
            if (libraryStatus === 3) {
                mediaInfo.status = 3;
                return { ...item, mediaInfo };
            }
            const syncedMediaStatus = Number(active.mediaStatus);
            if (syncedMediaStatus === 5 || syncedMediaStatus === 4) {
                mediaInfo.status = syncedMediaStatus;
                return { ...item, mediaInfo };
            }
            const currentStatus = Number(mediaInfo.status);
            // Don't clobber library available/partial — only fill unknown/empty.
            if (!Number.isFinite(currentStatus) || currentStatus === 1) {
                // MEDIA_STATUS: pending=2, processing=3 (approved / sent to *arr).
                mediaInfo.status = requestStatus === 1 ? 2 : 3;
            }
            return { ...item, mediaInfo };
        });
    } catch (error) {
        log(`Discovery request overlay skipped: ${error.message}`);
        return items;
    }
};

/**
 * Same role as portal overlay, for requestEngine=seerr: stamp Seerr mediaInfo so
 * detail CTAs show Requested/Pending instead of "Request Movie" when Seerr already
 * has the title (modal already knew via /request-options).
 */
const overlaySeerrPendingRequestsOntoItems = async (config, sessionUser, items = []) => {
    if (getRequestEngine(config) !== 'seerr' || !sessionUser || !Array.isArray(items) || !items.length) {
        return items;
    }
    try {
        // Detail fast path: same Seerr media endpoint the request modal uses.
        if (items.length === 1) {
            const item = items[0];
            const isMusic = item?.mediaType === 'music' || item?.type === 'music';
            if (!isMusic) {
                const mediaType = item?.mediaType === 'tv' || item?.mediaType === 2 || item?.mediaType === '2'
                    ? 'tv'
                    : 'movie';
                const tmdbId = Number(item?.tmdbId ?? item?.id);
                if (Number.isFinite(tmdbId) && tmdbId > 0) {
                    const opts = await requestAppService.getMemberRequestOptions(config, sessionUser, {
                        mediaType,
                        mediaId: tmdbId,
                    });
                    const seerrInfo = opts?.mediaInfo && typeof opts.mediaInfo === 'object'
                        ? opts.mediaInfo
                        : null;
                    const mediaStatus = Number(opts?.mediaStatus ?? seerrInfo?.status);
                    if (seerrInfo || (Number.isFinite(mediaStatus) && mediaStatus > 1) || opts?.canRequest) {
                        const mediaInfo = {
                            ...(item?.mediaInfo || {}),
                            ...(seerrInfo || {}),
                        };
                        if (Number.isFinite(mediaStatus) && mediaStatus > 0) {
                            mediaInfo.status = mediaStatus;
                        }
                        if (opts?.libraryQualities) mediaInfo.libraryQualities = opts.libraryQualities;
                        if (opts?.requestedQualities) mediaInfo.requestedQualities = opts.requestedQualities;
                        if (typeof opts?.canRequest === 'boolean') mediaInfo.canRequest = opts.canRequest;
                        return [{ ...item, mediaInfo }];
                    }
                }
            }
        }

        const userKey = `seerr:${String(sessionUser?.id || sessionUser?.plexId || '')}`;
        let activeByKey = null;
        const cached = userKey !== 'seerr:' ? memberActiveRequestsOverlayCache.get(userKey) : null;
        if (cached && (Date.now() - cached.at) < MEMBER_ACTIVE_REQUESTS_OVERLAY_TTL_MS) {
            activeByKey = cached.byKey;
        } else {
            if (cached && userKey) memberActiveRequestsOverlayCache.delete(userKey);
            const listed = await requestAppService.listMemberRequests(config, sessionUser, {
                filter: 'all',
                take: 50,
                skip: 0,
            });
            activeByKey = new Map();
            for (const row of listed.results || []) {
                const status = Number(row?.status);
                if (status === 3 || status === 4) continue; // declined / failed
                const mediaType = row?.type === 'tv' ? 'tv' : 'movie';
                const tmdbId = Number(row?.tmdbId);
                if (!Number.isFinite(tmdbId) || tmdbId <= 0) continue;
                const key = `${mediaType}:${tmdbId}`;
                const existing = activeByKey.get(key);
                if (!existing || (status === 1 && Number(existing.status) !== 1)) {
                    activeByKey.set(key, row);
                }
            }
            if (userKey !== 'seerr:') {
                memberActiveRequestsOverlayCache.set(userKey, { at: Date.now(), byKey: activeByKey });
            }
        }
        if (!activeByKey.size) return items;
        return items.map((item) => {
            const mediaType = item?.mediaType === 'tv' || item?.mediaType === 2 || item?.mediaType === '2'
                ? 'tv'
                : 'movie';
            const tmdbId = Number(item?.tmdbId ?? item?.id);
            if (!Number.isFinite(tmdbId) || tmdbId <= 0) return item;
            const active = activeByKey.get(`${mediaType}:${tmdbId}`);
            if (!active) return item;
            const mediaInfo = { ...(item?.mediaInfo || {}) };
            const requestStatus = Number(active.status) || 1;
            mediaInfo.requests = [
                {
                    id: active.id,
                    status: requestStatus,
                    is4k: !!active.is4k,
                    createdAt: active.createdAt,
                },
                ...(Array.isArray(mediaInfo.requests) ? mediaInfo.requests : []),
            ];
            const libraryStatus = resolveDiscoveryItemLibraryMediaStatus(item, mediaInfo);
            if (libraryStatus === 5) {
                mediaInfo.status = 5;
                return { ...item, mediaInfo };
            }
            if (libraryStatus === 4) {
                mediaInfo.status = 4;
                return { ...item, mediaInfo };
            }
            if (libraryStatus === 3) {
                mediaInfo.status = 3;
                return { ...item, mediaInfo };
            }
            const syncedMediaStatus = Number(active.mediaStatus);
            if (syncedMediaStatus === 5 || syncedMediaStatus === 4) {
                mediaInfo.status = syncedMediaStatus;
                return { ...item, mediaInfo };
            }
            const currentStatus = Number(mediaInfo.status);
            const seerrMediaStatus = Number(active.mediaStatus);
            if (!Number.isFinite(currentStatus) || currentStatus === 1) {
                if (Number.isFinite(seerrMediaStatus) && seerrMediaStatus > 1) {
                    mediaInfo.status = seerrMediaStatus;
                } else {
                    mediaInfo.status = requestStatus === 1 ? 2 : 3;
                }
            }
            return { ...item, mediaInfo };
        });
    } catch (error) {
        log(`Discovery Seerr request overlay skipped: ${error.message}`);
        return items;
    }
};

const overlayPendingRequestsOntoItems = async (config, sessionUser, items = []) => {
    const engine = getRequestEngine(config);
    if (engine === 'portal') return overlayPortalPendingRequestsOntoItems(config, sessionUser, items);
    if (engine === 'seerr') return overlaySeerrPendingRequestsOntoItems(config, sessionUser, items);
    return items;
};

const attachDiscoveryAvailabilityCacheToPayload = async (config, sessionUser, data) => {
    if (!data || typeof data !== 'object') return data;
    const cache = await loadDiscoveryAvailabilityCacheFile();
    // Deployed hosts may keep a v1 snapshot until reboot — kick a v2 rebuild on first browse.
    const cacheVersion = Number(cache?.version) || 0;
    if (
        cacheVersion < getDiscoveryAvailabilityCacheVersion()
        && !systemJobs.discoveryAvailabilityCache.running
    ) {
        setImmediate(() => {
            runDiscoveryAvailabilityCacheRebuild('upgrade').catch(() => {});
        });
    }
    let next = applyDiscoveryAvailabilityCacheToPayload(data, cache);

    // Disk cache is the Seerr-style Media DB join for list paths.
    // Do NOT warm-stamp / kick *arr catalog downloads on the request path — that
    // saturated Node (JSON-parsing huge Sonarr/Radarr catalogs) and froze Settings,
    // session, and every other route including /api/config.

    if (Array.isArray(next?.results)) {
        const overlaid = await Promise.race([
            overlayPendingRequestsOntoItems(config, sessionUser, next.results),
            new Promise((resolve) => setTimeout(() => resolve(next.results), 400)),
        ]);
        next = {
            ...next,
            results: overlaid,
        };
        return next;
    }
    // Detail pages: disk cache + pending overlay only.
    if (!Array.isArray(next) && (next?.mediaType === 'movie' || next?.mediaType === 'tv' || next?.mediaType === 'music' || next?.id)) {
        // Seerr media lookup needs more headroom than the portal request-list overlay.
        const overlayMs = getRequestEngine(config) === 'seerr' ? 2500 : 400;
        const overlaid = await Promise.race([
            overlayPendingRequestsOntoItems(config, sessionUser, [next]),
            new Promise((resolve) => setTimeout(() => resolve([next]), overlayMs)),
        ]);
        const [detailed] = Array.isArray(overlaid) ? overlaid : [next];
        return detailed || next;
    }
    return next;
};

const isMusicDiscoveryEnabled = (config) => {
    const defaults = getPortalRequestDefaults(config);
    if (!defaults.allowRequestMusic) return false;
    return getArrInstances(config, { type: 'lidarr', enabledOnly: true }).some(isArrInstanceReady);
};

/** Live Lidarr catalog + cache overlay for music discover lists. */
const enrichMusicDiscoveryPayload = async (config, sessionUser, payload, { blockForCatalog = false } = {}) => {
    const library = createDiscoveryLibraryAvailability(config);
    let results = Array.isArray(payload?.results) ? payload.results : [];
    try {
        if (blockForCatalog) {
            const blocked = library.enrichItems(results, { blockForCatalog: true });
            const timedOut = await Promise.race([
                blocked.then(() => false),
                new Promise((resolve) => setTimeout(() => resolve(true), 2500)),
            ]);
            results = timedOut
                ? await library.enrichItems(results, { blockForCatalog: false })
                : await blocked;
        } else {
            results = await library.enrichItems(results, { blockForCatalog: false });
        }
    } catch (enrichError) {
        log(`Music discovery library enrich skipped: ${enrichError.message}`);
    }
    return attachDiscoveryAvailabilityCacheToPayload(config, sessionUser, {
        ...(payload && typeof payload === 'object' ? payload : {}),
        results,
    });
};

/**
 * Optionally append Lidarr artist hits to global Discover search.
 * Never blocks movie/TV results — hard-capped and Lidarr-only (no MusicBrainz/CAA).
 */
const mergeMusicDiscoverySearchResults = async (config, sessionUser, query, results) => {
    const base = Array.isArray(results) ? results : [];
    if (!isMusicDiscoveryEnabled(config)) return base;

    const merge = async () => {
        const musicPayload = await searchMusicArtists(config, query, {
            limit: 6,
            fetchImpl: (url, options = {}) => fetchWithTimeout(url, { ...options, timeoutMs: 4000 }, 4000),
        });
        const musicResults = Array.isArray(musicPayload?.results) ? musicPayload.results : [];
        if (!musicResults.length) return base;
        // Cache overlay only — do not wait on catalog warm.
        const overlaid = await attachDiscoveryAvailabilityCacheToPayload(config, sessionUser, {
            results: musicResults,
        });
        const artists = Array.isArray(overlaid?.results) ? overlaid.results : musicResults;
        return [...base, ...artists].slice(0, 24);
    };

    try {
        return await Promise.race([
            merge(),
            // MusicBrainz throttles to ~1 req/s, so give the hybrid search a little headroom.
            new Promise((resolve) => setTimeout(() => resolve(base), 4500)),
        ]);
    } catch (e) {
        log(`Discovery music search merge skipped: ${e.message}`);
        return base;
    }
};

