const notifyPortalRequestDecision = async (config, record, { approved = false, declined = false, silent = false, declineReason = null } = {}) => {
    if (silent || !record) return;
    try {
        if (approved) {
            await notifyRequestApproved(buildRequestLifecycleNotifyDeps(config, record));
        } else if (declined) {
            await notifyRequestDeclined({
                ...buildRequestLifecycleNotifyDeps(config, record),
                declineReason,
            });
        }
    } catch (error) {
        log(`[RequestLifecycle] decision notify failed: ${error?.message || error}`);
    }
};

const notifyAdminNewRequest = async (config, record) => {
    if (!record) return;
    try {
        await notifyAdminPendingRequest({
            config,
            record,
            loadUsers: async () => loadFile(USERS_PATH, []),
            sendGotifyAlert,
            alertRuleEnabled,
            log,
        });
        const seerrId = String(record.id || '').startsWith('seerr:')
            ? record.id
            : record?.meta?.seerrRequestId;
        if (seerrId) {
            await stampSeerrPendingNotified(seerrId, { source: 'portal' });
        }
    } catch (error) {
        log(`[RequestLifecycle] admin pending notify failed: ${error?.message || error}`);
    }
};

const maybeNotifyRequestNotReleased = async (config, record) => {
    if (!record?.id || record.mediaType === 'music') return;
    if (!record?.meta?.releaseDateIsFuture && !isFutureReleaseDate(record?.meta?.releaseDate)) return;
    try {
        const result = await notifyRequestNotReleasedYet({
            config,
            record,
            releaseMeta: record?.meta?.releaseDate
                ? {
                    selectedDate: record.meta.releaseDate,
                    selectedType: record.meta.releaseDateType || 'tmdb',
                    selectedLabel: record.meta.releaseDateLabel || 'Release date',
                    formatted: record.meta.releaseDateFormatted || record.meta.releaseDate,
                    isFuture: true,
                }
                : null,
            loadUsers: async () => loadFile(USERS_PATH, []),
            sendEmail,
            hasEmailBeenSent,
            logEmailSent,
            resolvePublicBaseUrl: resolvePublicBaseUrlFromConfig,
            log,
        });
        if (result?.notified) {
            try {
                const portalRequests = getPortalRequestService(config);
                await portalRequests.store.update(record.id, {
                    meta: {
                        ...(record.meta || {}),
                        notReleasedNotifiedAt: new Date().toISOString(),
                    },
                });
            } catch (error) {
                log(`[RequestNotReleased] stamp failed for ${record.id}: ${error?.message || error}`);
            }
        }
    } catch (error) {
        log(`[RequestNotReleased] notify failed: ${error?.message || error}`);
    }
};

const getPortalWatchlistService = (config) => createPortalWatchlistService({
    dataDir: WATCHLIST_DIR,
    config,
    resolveUrl: resolveIntegrationUrlForFetch,
    fetchImpl: fetchWithTimeout,
    plexHeaders: plexClientHeaders,
    resolvePlexToken: async (sessionUser) => {
        if (sessionUser?.isAdmin && config?.plexToken && config.plexToken !== SECRET_MASK) {
            return String(config.plexToken);
        }
        const users = await loadFile(USERS_PATH, []);
        const key = String(sessionUser?.id || '');
        const plexId = String(sessionUser?.plexId || '');
        const local = users.find((user) => (
            String(user?.id) === key || String(user?.plexId) === plexId
        ));
        if (local?.plexAuthToken) {
            const token = decryptPlexAuthToken(local.plexAuthToken);
            if (token) {
                // Lazily upgrade legacy plaintext tokens on next watchlist use.
                if (!String(local.plexAuthToken).startsWith(PLEX_TOKEN_ENC_PREFIX)) {
                    local.plexAuthToken = encryptPlexAuthToken(token);
                    await saveFile(USERS_PATH, users);
                }
                return token;
            }
        }
        // Admin token as last resort only for admin sessions.
        if (sessionUser?.isAdmin && config?.plexToken && config.plexToken !== SECRET_MASK) {
            return String(config.plexToken);
        }
        return null;
    },
    requestService: getPortalRequestService(config),
});

