/** Trending charts + genres for Discover music (Deezer — no API key required). */
const musicBrowseCache = new Map(); // key: genreId → { at, payload }
const mapDeezerArtist = (entry) => {
    const name = String(entry?.name || '').trim();
    if (!name) return null;
    return {
        deezerId: entry.id,
        mediaType: 'music',
        type: 'music',
        name,
        title: name,
        posterUrl: entry.picture_big || entry.picture_medium || null,
        posterPath: entry.picture_big || entry.picture_medium || null,
    };
};
const mapDeezerAlbum = (entry) => {
    const title = String(entry?.title || '').trim();
    const artistName = String(entry?.artist?.name || '').trim();
    if (!title || !artistName) return null;
    return {
        deezerId: entry.id,
        mediaType: 'music',
        type: 'music',
        name: artistName,
        title,
        artistName,
        posterUrl: entry.cover_big || entry.cover_medium || null,
        posterPath: entry.cover_big || entry.cover_medium || null,
    };
};
/** Deezer charts repeat entries (clean/explicit variants) — collapse them. */
const dedupeChartItems = (items, keyFn) => {
    const seen = new Set();
    const out = [];
    for (const item of items) {
        if (!item) continue;
        const key = keyFn(item);
        if (!key || seen.has(key)) continue;
        seen.add(key);
        out.push(item);
    }
    return out;
};
const artistChartKey = (item) => String(item?.name || '').trim().toLowerCase();
const albumChartKey = (item) => `${String(item?.artistName || '').trim().toLowerCase()}|${String(item?.title || '').trim().toLowerCase()}`;
app.get('/api/discovery/music/browse', requireAuth, requireMember, async (req, res) => {
    try {
        const config = await loadFile(CONFIG_PATH, {});
        if (!isMusicDiscoveryEnabled(config)) {
            return res.json({ topArtists: [], topAlbums: [], newReleases: [], genres: [] });
        }

        const genreId = Number(req.query.genreId) > 0 ? Number(req.query.genreId) : 0;
        const cached = musicBrowseCache.get(genreId);
        if (cached && Date.now() - cached.at < 30 * 60 * 1000) {
            return res.json(cached.payload);
        }

        const fetchJson = async (url) => {
            const response = await fetchWithTimeout(url, { headers: { Accept: 'application/json' }, timeoutMs: 8000 }, 8000);
            if (!response.ok) return null;
            return response.json().catch(() => null);
        };
        // Deezer's editorial "new releases" feed returns empty payloads, so only charts are used.
        const [artistsRes, albumsRes, genresRes] = await Promise.all([
            fetchJson(`https://api.deezer.com/chart/${genreId}/artists?limit=24`).catch(() => null),
            fetchJson(`https://api.deezer.com/chart/${genreId}/albums?limit=24`).catch(() => null),
            genreId === 0 ? fetchJson('https://api.deezer.com/genre').catch(() => null) : Promise.resolve(null),
        ]);

        const genres = (genresRes?.data || [])
            .filter((entry) => Number(entry?.id) > 0 && String(entry?.name || '').trim())
            .map((entry) => ({
                id: Number(entry.id),
                name: String(entry.name).trim(),
                image: entry.picture_big || entry.picture_medium || entry.picture || null,
            }));

        // One album rail per genre on the browse view (default charts only).
        let genreRows = [];
        if (genreId === 0 && genres.length) {
            genreRows = (await Promise.all(genres.slice(0, 12).map(async (g) => {
                const rowRes = await fetchJson(`https://api.deezer.com/chart/${g.id}/albums?limit=18`).catch(() => null);
                const albums = dedupeChartItems(
                    (rowRes?.data || []).map(mapDeezerAlbum),
                    albumChartKey,
                );
                return albums.length >= 4 ? { id: g.id, name: g.name, albums } : null;
            }))).filter(Boolean);
        }

        const payload = {
            genreId: genreId || null,
            topArtists: dedupeChartItems((artistsRes?.data || []).map(mapDeezerArtist), artistChartKey),
            topAlbums: dedupeChartItems((albumsRes?.data || []).map(mapDeezerAlbum), albumChartKey),
            newReleases: [],
            genres,
            genreRows,
        };
        if (payload.topArtists.length || payload.topAlbums.length) {
            musicBrowseCache.set(genreId, { at: Date.now(), payload });
            if (musicBrowseCache.size > 40) {
                musicBrowseCache.delete(musicBrowseCache.keys().next().value);
            }
        }
        res.json(payload);
    } catch (e) {
        log(`Discovery music browse error: ${e.message}`);
        res.status(502).json({ error: e.message || 'Failed to load music charts' });
    }
});

/** Resolve an artist name (from chart rails) to a MusicBrainz id for the artist page. */
const musicResolveCache = new Map();
app.get('/api/discovery/music/resolve', requireAuth, requireMember, async (req, res) => {
    try {
        const name = String(req.query.name || '').trim();
        if (name.length < 2) return res.status(400).json({ error: 'Artist name is required' });
        const key = name.toLowerCase();
        if (musicResolveCache.has(key)) return res.json(musicResolveCache.get(key));

        const config = await loadFile(CONFIG_PATH, {});
        const hybrid = await searchMusicArtists(config, name, { limit: 5, fetchImpl: fetchWithTimeout });
        const results = Array.isArray(hybrid?.results) ? hybrid.results : [];
        const exact = results.find((hit) => String(hit?.name || '').toLowerCase() === key) || results[0] || null;
        if (!exact?.mbid) return res.status(404).json({ error: 'Artist not found' });

        const payload = { mbid: exact.mbid, name: exact.name || name };
        musicResolveCache.set(key, payload);
        if (musicResolveCache.size > 500) {
            musicResolveCache.delete(musicResolveCache.keys().next().value);
        }
        res.json(payload);
    } catch (e) {
        log(`Discovery music resolve error: ${e.message}`);
        res.status(502).json({ error: e.message || 'Failed to resolve artist' });
    }
});

// Assembled artist payloads (pre user-overlay) — repeat visits render instantly.
const musicArtistPayloadCache = new Map(); // mbid → { at, artist }
const MUSIC_ARTIST_PAYLOAD_CACHE_MS = 3 * 60 * 1000;

app.get('/api/discovery/music/artist/:mbid', requireAuth, requireMember, async (req, res) => {
    try {
        const config = await loadFile(CONFIG_PATH, {});
        const mbid = String(req.params.mbid || '').trim();
        if (!mbid) return res.status(400).json({ error: 'Artist id is required' });

        const cachedPayload = musicArtistPayloadCache.get(mbid);
        if (cachedPayload && Date.now() - cachedPayload.at < MUSIC_ARTIST_PAYLOAD_CACHE_MS) {
            const artist = await attachDiscoveryAvailabilityCacheToPayload(
                config, req.user, structuredClone(cachedPayload.artist),
            );
            return res.json(artist);
        }

        // Lidarr (art + library id), MusicBrainz (discography), and per-album
        // availability all in parallel — nothing serial on this path. The Lidarr
        // metadata-server lookup routinely takes seconds, so it gets a hard 4s
        // budget; a late result still lands in its cache for the next view.
        const lidarrArtistPromise = fetchLidarrArtistByMbid(config, mbid, { fetchImpl: fetchWithTimeout }).catch(() => null);
        const [lidarrArtist, mbArtist, lidarrAlbums] = await Promise.all([
            Promise.race([
                lidarrArtistPromise,
                new Promise((resolve) => setTimeout(() => resolve(null), 4000)),
            ]),
            fetchMusicBrainzArtist(mbid, { fetchImpl: fetchWithTimeout }).catch((err) => {
                log(`MusicBrainz artist lookup failed: ${err.message}`);
                return null;
            }),
            fetchLidarrAlbumAvailabilityByMbid(config, mbid, { fetchImpl: fetchWithTimeout }).catch(() => null),
        ]);
        // Metadata lookup timed out but the artist is in the library — use the
        // library entity for the header (name + Lidarr artwork).
        const libraryItem = (!lidarrArtist && lidarrAlbums?.artist?.id)
            ? mapLidarrArtistToDiscoverItem(lidarrAlbums.artist, lidarrAlbums.instance)
            : null;
        const lidarrHeader = lidarrArtist || libraryItem;
        let artist = lidarrHeader || mbArtist;
        if (lidarrHeader && mbArtist) {
            artist = {
                ...mbArtist,
                ...lidarrHeader,
                overview: lidarrHeader.overview || mbArtist.overview,
                posterUrl: lidarrHeader.posterUrl || lidarrHeader.posterPath || mbArtist.posterUrl || mbArtist.posterPath || null,
                posterPath: lidarrHeader.posterPath || lidarrHeader.posterUrl || mbArtist.posterPath || mbArtist.posterUrl || null,
                tags: Array.isArray(lidarrHeader.tags) && lidarrHeader.tags.length ? lidarrHeader.tags : mbArtist.tags,
                disambiguation: lidarrHeader.disambiguation || mbArtist.disambiguation,
            };
        }

        if (!artist) return res.status(404).json({ error: 'Artist not found' });

        // Discography with per-album Lidarr availability for the request UI.
        const albums = Array.isArray(mbArtist?.albums) ? mbArtist.albums : [];
        if (albums.length) {
            artist.albums = albums.map((album) => {
                const status = lidarrAlbums?.albumsByMbid?.get(album.mbid) || null;
                return {
                    ...album,
                    inLidarr: !!status,
                    monitored: !!status?.monitored,
                    available: !!status?.available,
                    partial: !!status?.partial,
                };
            });
        } else if (lidarrAlbums?.albumsByMbid?.size) {
            // MusicBrainz was down — fall back to whatever Lidarr tracks for the artist.
            const fallback = [];
            const lidarrList = await fetchLidarrAlbumsForArtist(
                lidarrAlbums.instance,
                lidarrAlbums.artist?.id,
                { fetchImpl: fetchWithTimeout },
            ).catch(() => []);
            for (const album of lidarrList) {
                const albumMbid = String(album?.foreignAlbumId || '').trim();
                if (!albumMbid) continue;
                const status = lidarrAlbums.albumsByMbid.get(albumMbid) || null;
                fallback.push({
                    mbid: albumMbid,
                    id: albumMbid,
                    title: String(album?.title || 'Unknown album'),
                    type: String(album?.albumType || 'Album'),
                    releaseDate: album?.releaseDate || null,
                    year: album?.releaseDate ? String(album.releaseDate).slice(0, 4) : null,
                    coverUrl: caaReleaseGroupCoverUrl(albumMbid),
                    inLidarr: true,
                    monitored: !!status?.monitored,
                    available: !!status?.available,
                    partial: !!status?.partial,
                });
            }
            fallback.sort((a, b) => String(b.releaseDate || '').localeCompare(String(a.releaseDate || '')));
            artist.albums = fallback;
        } else {
            artist.albums = [];
        }

        // Header art fallback: newest album cover when no artist image resolved.
        if (!artist.posterUrl && artist.albums.length) {
            artist.posterUrl = artist.albums[0].coverUrl || null;
            artist.posterPath = artist.posterPath || artist.posterUrl;
        }

        try {
            const library = createDiscoveryLibraryAvailability(config);
            artist = await library.enrichDetails(artist);
        } catch (enrichError) {
            log(`Music artist library enrich skipped: ${enrichError.message}`);
        }
        if (musicArtistPayloadCache.size > 200) musicArtistPayloadCache.clear();
        musicArtistPayloadCache.set(mbid, { at: Date.now(), artist: structuredClone(artist) });
        artist = await attachDiscoveryAvailabilityCacheToPayload(config, req.user, artist);
        res.json(artist);
    } catch (e) {
        log(`Discovery music artist error: ${e.message}`);
        res.status(502).json({ error: e.message || 'Failed to load artist' });
    }
});

/** Proxy Lidarr MediaCover / remote artist art for Discover cards (member-accessible). */
app.get('/api/discovery/music/cover', requireAuth, requireMember, async (req, res) => {
    try {
        const config = await loadFile(CONFIG_PATH, {});
        const instanceId = String(req.query.instanceId || '').trim();
        const artistId = Number(req.query.artistId || 0);
        if (!instanceId || !Number.isFinite(artistId) || artistId <= 0) {
            return res.status(400).send('Missing instanceId or artistId');
        }
        const instance = getArrInstance(config, instanceId);
        if (!instance || instance.type !== 'lidarr' || !isArrInstanceReady(instance)) {
            return res.status(404).send('Lidarr instance not ready');
        }
        const resolveUrl = resolveIntegrationUrlForFetch;
        const base = String(resolveUrl(instance.url) || '').replace(/\/+$/, '');
        const headers = { 'X-Api-Key': instance.apiKey };
        const coverPaths = [
            `/MediaCover/${artistId}/poster.jpg`,
            `/MediaCover/${artistId}/cover.jpg`,
            `/MediaCover/${artistId}/poster-500.jpg`,
        ];
        let imageRes = null;
        for (const coverPath of coverPaths) {
            discardFetchBody(imageRes);
            imageRes = await fetch(`${base}${coverPath}`, { headers }).catch(() => null);
            if (imageRes?.ok) break;
        }
        if (!imageRes?.ok) {
            discardFetchBody(imageRes);
            const artist = await fetchArrInstanceJson(instance, `/api/v1/artist/${artistId}`, {
                resolveUrl,
                fetchImpl: fetch,
            }).catch(() => null);
            const posterImage = (artist?.images || []).find((img) => String(img?.coverType || '').toLowerCase() === 'poster')
                || (artist?.images || []).find((img) => String(img?.coverType || '').toLowerCase() === 'cover')
                || (artist?.images || [])[0]
                || null;
            const remoteUrl = posterImage?.remoteUrl || posterImage?.url || null;
            if (remoteUrl) {
                const safeRemote = await resolveSafeArrRemoteImageUrl(remoteUrl, base).catch(() => null);
                if (safeRemote) imageRes = await fetch(safeRemote).catch(() => null);
            }
        }
        await sendFetchImage(res, imageRes);
    } catch (e) {
        log(`Discovery music cover error: ${e.message}`);
        res.status(500).send('Failed to load cover art');
    }
});

