const requestMediaTypeFromArrSegment = (raw) => {
    const value = String(raw || '').toLowerCase();
    if (value === 'radarr' || value === 'movie') return 'movie';
    if (value === 'lidarr' || value === 'music') return 'music';
    return 'tv';
};

