app.get('/api/health', (req, res) => res.json({ status: 'ok', uptime: process.uptime() }));
app.get('/api/status', publicReadRateLimit, async (req, res) => {
    const config = await loadFile(CONFIG_PATH, {});
    let sessionUser = null;
    let viewerIsAdmin = false;
    const token = req.cookies?.session;
    if (token) {
        try {
            sessionUser = jwt.verify(token, JWT_SECRET);
            const isRealAdmin = await resolveCurrentAdmin(getSessionActor(sessionUser), config);
            // Impersonation must see the member/public view — not the full admin service list.
            viewerIsAdmin = effectiveViewerIsAdmin(sessionUser, isRealAdmin);
        } catch (e) {
            sessionUser = null;
            viewerIsAdmin = false;
        }
    }
    if (!isPublicStatusVisible(config) && !sessionUser) {
        return res.status(401).json({ error: 'Status monitor requires login.' });
    }

    const allServices = Array.isArray(statusConfig.services) ? statusConfig.services : [];
    const allowedServices = viewerIsAdmin
        ? allServices
        : allServices.filter(isStatusServiceVisibleToUsers);
    const allowedIds = new Set(allowedServices.map((service) => String(service.id)));
    const publicServices = allowedServices.map((service) => ({
        id: service.id,
        name: service.name,
        groupId: service.groupId,
        type: service.type || 'web',
        clientType: service.clientType || null,
        description: service.description || '',
        ...(viewerIsAdmin ? {
            visibleToUsers: isStatusServiceVisibleToUsers(service),
            isCritical: service.isCritical !== false,
        } : {}),
    }));
    const usedGroupIds = new Set(publicServices.map((service) => String(service.groupId || '')));
    const groups = (statusConfig.groups || [])
        .filter((group) => usedGroupIds.has(String(group.id)))
        .map((group) => ({ id: group.id, name: group.name, order: group.order }));

    // Downsample recentChecks for the public payload (keep full resolution on disk).
    const slimHealth = {};
    for (const [key, record] of Object.entries(healthData || {})) {
        if (key === '_meta') {
            slimHealth[key] = record;
            continue;
        }
        if (!allowedIds.has(String(key))) continue;
        if (!record || typeof record !== 'object') continue;
        const recent = Array.isArray(record.recentChecks) ? record.recentChecks : [];
        const bucketMs = 5 * 60 * 1000;
        const buckets = new Map();
        for (const sample of recent) {
            if (!sample || !sample.t) continue;
            const slot = Math.floor(sample.t / bucketMs) * bucketMs;
            if (!buckets.has(slot)) buckets.set(slot, []);
            buckets.get(slot).push(sample);
        }
        const downsampled = [];
        for (const [slot, samples] of [...buckets.entries()].sort((a, b) => a[0] - b[0])) {
            const online = samples.filter((s) => s.status === 'online');
            const latencies = online.map((s) => Number(s.latency)).filter((n) => Number.isFinite(n) && n > 0);
            downsampled.push({
                t: slot,
                status: online.length >= samples.length / 2 ? 'online' : (samples[samples.length - 1]?.status || 'offline'),
                latency: latencies.length ? Math.round(latencies.reduce((a, b) => a + b, 0) / latencies.length) : 0,
                _n: samples.length,
                _up: online.length,
            });
        }
        slimHealth[key] = {
            ...record,
            recentChecks: downsampled,
        };
    }

    res.json({
        config: {
            services: publicServices,
            groups,
            announcement: statusConfig.announcement || null
        },
        healthData: slimHealth
    });
});
app.get('/api/status/config', requireAuth, requireAdmin, (req, res) => res.json(statusConfig));
app.post('/api/status/config', requireAuth, requireAdmin, async (req, res) => {
    try {
        // Security: validate body schema before writing to disk
        const { services, groups, announcement } = req.body;
        if (!Array.isArray(services) || !Array.isArray(groups)) {
            return res.status(400).json({ error: 'Invalid config structure: services and groups must be arrays.' });
        }
        const previousServices = Array.isArray(statusConfig.services) ? statusConfig.services : [];
        const previousManagedIds = previousServices
            .map((service) => String(service?.id || ''))
            .filter((id) => id.startsWith('arr-') || id.startsWith('download-'));
        const previousSuppressed = new Set(
            (Array.isArray(statusConfig.suppressedManagedIds) ? statusConfig.suppressedManagedIds : []).map(String),
        );

        const sanitizedServices = [];
        for (const service of services) {
            if (!service || typeof service !== 'object') continue;
            let normalizedUrl = '';
            if (service.url) {
                try {
                    normalizedUrl = normalizeExternalBaseUrl(service.url, {
                        allowPrivate: ALLOW_PRIVATE_INTEGRATION_URLS,
                        allowHttp: true,
                    });
                    await assertResolvedAddressesAllowed(new URL(normalizedUrl).hostname, {
                        allowPrivate: ALLOW_PRIVATE_INTEGRATION_URLS,
                    });
                } catch (e) {
                    return res.status(400).json({ error: `Invalid service URL for "${service.name || service.id || 'unknown'}": ${e.message}` });
                }
            }
            const rawGroupId = service.groupId;
            const groupId = (rawGroupId == null || rawGroupId === '')
                ? null
                : String(rawGroupId);
            sanitizedServices.push({
                id: String(service.id || randomUUID()),
                name: String(service.name || 'Service'),
                url: normalizedUrl,
                port: Number.isFinite(Number(service.port)) ? Number(service.port) : undefined,
                type: String(service.type || 'web'),
                clientType: service.clientType ? String(service.clientType) : undefined,
                clientId: service.clientId ? String(service.clientId) : undefined,
                groupId,
                description: String(service.description || ''),
                isCritical: service.isCritical !== false,
                // Default visible when unset so older configs keep showing on the public page.
                visibleToUsers: service.visibleToUsers !== false,
            });
        }

        // Track managed monitors the admin removed so /api/config sync does not resurrect them.
        const nextManagedIds = new Set(
            sanitizedServices
                .map((service) => String(service.id || ''))
                .filter((id) => id.startsWith('arr-') || id.startsWith('download-')),
        );
        for (const id of previousManagedIds) {
            if (!nextManagedIds.has(id)) previousSuppressed.add(id);
        }
        for (const id of nextManagedIds) {
            previousSuppressed.delete(id);
        }

        statusConfig = {
            services: sanitizedServices,
            groups,
            announcement: announcement !== undefined ? (announcement || null) : (statusConfig.announcement || null),
            suppressedManagedIds: [...previousSuppressed],
            notifyDownAfterMinutes: normalizeStatusNotifyDownAfterMinutes(
                req.body?.notifyDownAfterMinutes ?? statusConfig.notifyDownAfterMinutes,
            ),
        };
        await saveFile(STATUS_CONFIG_PATH, statusConfig);
        res.json({ success: true, message: 'Status configuration updated successfully.' });
    } catch (error) {
        res.status(500).json({ error: 'Failed to update status configuration' });
    }
});

