app.get('/api/plex/discover-search', requireAuth, requireAdmin, async (req, res) => {
    try {
        const config = await loadFile(CONFIG_PATH, null);
        if (!config || !config.plexToken || !config.serverIdentifier) {
            return res.status(503).json({ error: 'Plex not configured' });
        }

        const uri = await getPlexConnectionUri(config);
        if (!uri) return res.status(503).json({ error: 'Cannot connect to Plex' });

        const query = String(req.query.query || '').trim();
        if (!query) return res.json({ results: [] });

        // Search Plex Hubs
        const searchRes = await fetch(`${uri}/hubs/search?query=${encodeURIComponent(query)}&limit=20&X-Plex-Token=${config.plexToken}`, { headers: plexClientHeaders(config.plexToken) }).then(r => r.json());
        
        let searchResults = [];
        if (searchRes && searchRes.MediaContainer && searchRes.MediaContainer.Hub) {
            searchRes.MediaContainer.Hub.forEach(hub => {
                if (hub.type === 'movie' || hub.type === 'show') {
                    if (hub.Metadata) {
                        hub.Metadata.forEach(m => {
                            searchResults.push({
                                ratingKey: m.ratingKey,
                                title: m.title,
                                type: m.type,
                                year: m.year,
                                thumb: m.thumb,
                                plexUrl: `https://app.plex.tv/desktop/#!/server/${config.serverIdentifier}/details?key=${encodeURIComponent(m.key)}`
                            });
                        });
                    }
                }
            });
        }

        // Titles only — watch history loads on the title page so search stays fast.
        searchResults = searchResults.slice(0, 12);

        res.json({ results: searchResults });
    } catch (e) {
        log(`Error fetching discover search: ${e.message}`);
        res.status(500).json({ error: 'Failed to fetch search results' });
    }
});

const asInt = (value) => {
    if (value == null || value === '') return null;
    const n = Number(value);
    return Number.isFinite(n) ? n : null;
};

const mapTitleHistoryRow = (row, source) => {
    const playDuration = asInt(row.playDuration ?? row.play_duration);
    const mediaDuration = asInt(row.mediaDuration)
        ?? (source === 'tautulli' ? asInt(row.duration) : null);
    const plexDuration = source === 'plex' ? asInt(row.duration) : null;
    return {
        id: row.id != null ? String(row.id) : (row.row_id != null ? String(row.row_id) : null),
        user: row.user || 'Unknown',
        userThumb: row.userThumb || row.user_thumb || null,
        date: asInt(row.date) || asInt(row.startedAt) || asInt(row.started) || 0,
        duration: Math.max(0, playDuration ?? plexDuration ?? 0),
        playDuration,
        mediaDuration,
        player: row.player || null,
        platform: row.platform || null,
        product: row.product || null,
        title: row.full_title || row.title || null,
        episodeTitle: row.episodeTitle || (String(row.media_type || row.mediaType || '') === 'episode' ? row.title : null),
        seasonNumber: asInt(row.seasonNumber ?? row.parent_media_index),
        episodeNumber: asInt(row.episodeNumber ?? row.media_index),
        startedAt: asInt(row.startedAt ?? row.started),
        stoppedAt: asInt(row.stoppedAt ?? row.stopped),
        pausedSeconds: asInt(row.pausedSeconds ?? row.paused_counter) || 0,
        percentComplete: asInt(row.percentComplete ?? row.percent_complete),
        watchedStatus: asInt(row.watchedStatus ?? row.watched_status),
        transcodeDecision: row.transcodeDecision || row.transcode_decision || null,
        videoDecision: row.videoDecision || row.video_decision || null,
        audioDecision: row.audioDecision || row.audio_decision || null,
        ipAddress: row.ipAddress || row.ip_address || null,
        location: row.location || null,
        year: asInt(row.year),
        mediaType: row.mediaType || row.media_type || null,
        ratingKey: row.ratingKey != null ? String(row.ratingKey) : (row.rating_key != null ? String(row.rating_key) : null),
        parentRatingKey: row.parentRatingKey != null ? String(row.parentRatingKey) : (row.parent_rating_key != null ? String(row.parent_rating_key) : null),
        parentTitle: row.parentTitle || row.parent_title || null,
        grandparentRatingKey: row.grandparentRatingKey != null ? String(row.grandparentRatingKey) : (row.grandparent_rating_key != null ? String(row.grandparent_rating_key) : null),
        grandparentTitle: row.grandparentTitle || row.grandparent_title || null,
        source,
    };
};

const mapTitleAnalyticsItem = (meta, ratingKey, config) => ({
    ratingKey: String(meta?.ratingKey || ratingKey),
    title: meta?.title || '',
    type: meta?.type || '',
    year: meta?.year || null,
    thumb: meta?.thumb || meta?.parentThumb || meta?.grandparentThumb || null,
    summary: meta?.summary || null,
    index: asInt(meta?.index),
    parentIndex: asInt(meta?.parentIndex),
    leafCount: asInt(meta?.leafCount),
    parentRatingKey: meta?.parentRatingKey ? String(meta.parentRatingKey) : null,
    parentTitle: meta?.parentTitle || null,
    grandparentRatingKey: meta?.grandparentRatingKey ? String(meta.grandparentRatingKey) : null,
    grandparentTitle: meta?.grandparentTitle || null,
    plexUrl: `https://app.plex.tv/desktop/#!/server/${config.serverIdentifier}/details?key=${encodeURIComponent(meta?.key || `/library/metadata/${ratingKey}`)}`,
});

const titleHistoryScope = (type) => {
    const t = String(type || '').toLowerCase();
    if (t === 'show') return 'show';
    if (t === 'season') return 'season';
    return 'item';
};

const tautulliExtraForTitleScope = (scope, ratingKey, start, pageSize) => {
    if (scope === 'show') return { grandparent_rating_key: ratingKey, start, length: pageSize };
    if (scope === 'season') return { parent_rating_key: ratingKey, start, length: pageSize };
    return { rating_key: ratingKey, start, length: pageSize };
};

const plexHistoryFilterForTitleScope = (scope) => {
    if (scope === 'show') return 'grandparentID';
    if (scope === 'season') return 'parentID';
    return 'metadataItemID';
};

const tautulliRowMatchesTitleScope = (row, scope, ratingKey) => {
    const hasKeys = row.grandparent_rating_key != null || row.parent_rating_key != null || row.rating_key != null;
    if (!hasKeys) return true;
    if (scope === 'show') return String(row.grandparent_rating_key || '') === ratingKey;
    if (scope === 'season') return String(row.parent_rating_key || '') === ratingKey;
    return String(row.rating_key || '') === ratingKey || String(row.grandparent_rating_key || '') === ratingKey;
};

const fetchPlexTitleChildren = async (uri, config, ratingKey, { excludeAllLeaves = false } = {}) => {
    const extra = excludeAllLeaves ? '&excludeAllLeaves=1' : '';
    const url = `${uri}/library/metadata/${encodeURIComponent(ratingKey)}/children?X-Plex-Container-Start=0&X-Plex-Container-Size=500${extra}&X-Plex-Token=${config.plexToken}`;
    const data = await fetch(url, { headers: plexClientHeaders(config.plexToken) }).then((r) => r.json()).catch(() => null);
    return data?.MediaContainer?.Metadata || [];
};

const mapTitleChildMeta = (meta) => ({
    ratingKey: String(meta?.ratingKey || ''),
    title: meta?.title || '',
    type: meta?.type || '',
    index: asInt(meta?.index),
    parentIndex: asInt(meta?.parentIndex),
    thumb: meta?.thumb || meta?.parentThumb || meta?.grandparentThumb || null,
    leafCount: asInt(meta?.leafCount),
});

app.get('/api/plex/analytics/title/:ratingKey', requireAuth, requireAdmin, async (req, res) => {
    try {
        const config = await loadFile(CONFIG_PATH, null);
        if (!config || !config.plexToken || !config.serverIdentifier) {
            return res.status(503).json({ error: 'Plex not configured' });
        }
        const uri = await getPlexConnectionUri(config);
        if (!uri) return res.status(503).json({ error: 'Cannot connect to Plex' });

        const ratingKey = String(req.params.ratingKey || '').trim();
        if (!ratingKey || !/^\d+$/.test(ratingKey)) {
            return res.status(400).json({ error: 'Invalid title id' });
        }

        let item = mapTitleAnalyticsItem(null, ratingKey, config);
        try {
            const metaRes = await fetch(
                `${uri}/library/metadata/${encodeURIComponent(ratingKey)}?X-Plex-Token=${config.plexToken}`,
                { headers: plexClientHeaders(config.plexToken) },
            ).then((r) => r.json()).catch(() => null);
            const meta = metaRes?.MediaContainer?.Metadata?.[0];
            if (meta) item = mapTitleAnalyticsItem(meta, ratingKey, config);
        } catch (e) {
            log(`Title analytics metadata failed for ${ratingKey}: ${e.message}`);
        }

        const history = [];
        let source = 'plex';
        const scope = titleHistoryScope(item.type);
        const childKind = scope === 'show' ? 'season' : scope === 'season' ? 'episode' : null;

        if (config.tautulliUrl && config.tautulliApiKey) {
            const tUrl = resolveIntegrationUrlForFetch(config.tautulliUrl);
            if (tUrl) {
                const pageSize = 100;
                const maxRows = 500;
                for (let start = 0; start < maxRows; start += pageSize) {
                    const extra = tautulliExtraForTitleScope(scope, ratingKey, start, pageSize);
                    const rows = await fetchTautulliHistoryPage(tUrl, config, extra, { throwOnError: false });
                    if (!rows || !rows.length) break;
                    let pageMatches = 0;
                    for (const row of rows) {
                        if (!tautulliRowMatchesTitleScope(row, scope, ratingKey)) continue;
                        pageMatches += 1;
                        history.push(mapTitleHistoryRow(row, 'tautulli'));
                    }
                    if (start === 0 && pageMatches === 0) break;
                    if (rows.length < pageSize) break;
                }
                if (history.length) source = 'tautulli';
            }
        }

        if (!history.length) {
            const filterKey = plexHistoryFilterForTitleScope(scope);
            const fetchUrl = `${uri}/status/sessions/history/all?sort=viewedAt%3Adesc&${filterKey}=${encodeURIComponent(ratingKey)}&X-Plex-Container-Start=0&X-Plex-Container-Size=200&X-Plex-Token=${config.plexToken}`;
            const resData = await fetch(fetchUrl, { headers: plexClientHeaders(config.plexToken) }).then((r) => r.json()).catch(() => null);
            const rows = resData?.MediaContainer?.Metadata || [];
            for (const row of rows) {
                history.push(mapTitleHistoryRow({
                    user: row.User?.title || 'Unknown User',
                    userThumb: row.User?.thumb || null,
                    date: row.viewedAt,
                    duration: row.duration ? Math.round(row.duration / 1000) : 0,
                    player: row.Player?.title || null,
                    platform: row.Player?.platform || null,
                    product: row.Player?.product || null,
                    title: row.grandparentTitle ? `${row.grandparentTitle} - ${row.title}` : row.title,
                    episodeTitle: row.grandparentTitle ? row.title : null,
                    seasonNumber: row.parentIndex,
                    episodeNumber: row.index,
                    ratingKey: row.ratingKey,
                    parentRatingKey: row.parentRatingKey,
                    parentTitle: row.parentTitle || null,
                    grandparentRatingKey: row.grandparentRatingKey,
                    grandparentTitle: row.grandparentTitle || null,
                }, 'plex'));
            }
            source = 'plex';
        }

        let children = [];
        if (childKind) {
            let childMeta = [];
            try {
                childMeta = await fetchPlexTitleChildren(uri, config, ratingKey, { excludeAllLeaves: childKind === 'season' });
            } catch (e) {
                log(`Title analytics children failed for ${ratingKey}: ${e.message}`);
            }
            const mapped = (childMeta || []).map(mapTitleChildMeta).filter((row) => row.ratingKey);
            const list = mapped.length ? mapped : synthesizeTitleChildren(history, { kind: childKind });
            children = rollupTitleChildren(list, history, { kind: childKind });
        }

        const aggregated = aggregateTitleHistory(history);
        res.json({
            item,
            source,
            children,
            childKind,
            ...aggregated,
            history,
        });
    } catch (e) {
        log(`Error fetching title analytics: ${e.message}`);
        res.status(500).json({ error: 'Failed to load title analytics' });
    }
});

app.get('/api/plex/analytics/history/:rowId/stream', requireAuth, requireAdmin, async (req, res) => {
    try {
        const rowId = String(req.params.rowId || '').trim();
        if (!rowId || !/^\d+$/.test(rowId)) {
            return res.status(400).json({ error: 'Invalid history id' });
        }

        const config = await loadFile(CONFIG_PATH, null);
        if (!config?.tautulliUrl || !config?.tautulliApiKey) {
            return res.status(503).json({ error: 'Tautulli is not configured' });
        }
        const tUrl = resolveIntegrationUrlForFetch(config.tautulliUrl);
        if (!tUrl) return res.status(503).json({ error: 'Tautulli is not configured' });

        const payload = await fetchTautulliApi(tUrl, {
            apikey: config.tautulliApiKey,
            cmd: 'get_stream_data',
            row_id: rowId,
        });
        const raw = payload?.response?.data;
        if (!raw || typeof raw !== 'object' || Array.isArray(raw) || !Object.keys(raw).length) {
            return res.status(404).json({ error: 'Stream details not found for this play' });
        }
        res.json(mapTautulliStreamData(raw));
    } catch (e) {
        log(`Error fetching history stream details: ${e.message}`);
        res.status(502).json({ error: e.message || 'Failed to load stream details' });
    }
});

const jellyfinItemUrl = (config, itemId) => {
    const baseUrl = String(config?.jellyfinUrl || '').replace(/\/+$/, '');
    return baseUrl && itemId ? `${baseUrl}/web/#/details?id=${encodeURIComponent(itemId)}` : baseUrl;
};

const hasJellyfinPrimaryImage = (item = {}) => !!(
    item?.ImageTags?.Primary
    || item?.PrimaryImageTag
    || item?.PrimaryImageItemId
);

const jellyfinImageUrlForItem = (itemId, width = 300, height = 450) => (
    itemId ? withBasePath(`/api/jellyfin/image?itemId=${encodeURIComponent(itemId)}&width=${width}&height=${height}`) : ''
);

const mapJellyfinItemForDiscover = (config, item = {}, type = '') => {
    const id = item.Id || '';
    const isEpisode = String(type || item.Type || '').toLowerCase() === 'episode';
    const canUsePrimaryImage = hasJellyfinPrimaryImage(item);
    const posterId = canUsePrimaryImage ? (isEpisode ? (item.PrimaryImageItemId || item.SeriesId || item.ParentId || id) : (item.PrimaryImageItemId || id)) : '';
    const title = type === 'episode'
        ? (item.SeriesName ? `${item.SeriesName} - ${item.Name}` : item.Name)
        : (item.Name || 'Untitled');
    const tags = [];
    const width = Number(item.Width || item.MediaStreams?.find?.((s) => s.Type === 'Video')?.Width || 0);
    const height = Number(item.Height || item.MediaStreams?.find?.((s) => s.Type === 'Video')?.Height || 0);
    if (width >= 3800 || height >= 2000) tags.push('4K');
    else if (height >= 1000) tags.push('1080p');
    else if (height >= 700) tags.push('720p');
    const videoCodec = item.MediaStreams?.find?.((s) => s.Type === 'Video')?.Codec || item.MediaSources?.[0]?.VideoCodec;
    if (videoCodec) tags.push(String(videoCodec).toUpperCase());

    return {
        ratingKey: id,
        sourceRatingKey: id,
        title,
        parentTitle: item.Album || item.SeriesName || null,
        type: item.Type,
        year: item.ProductionYear,
        thumb: posterId,
        thumbUrl: posterId ? jellyfinImageUrlForItem(posterId, 300, type === 'music' ? 300 : 450) : '',
        posterFallbackUrl: isEpisode && canUsePrimaryImage && id && id !== posterId ? jellyfinImageUrlForItem(id, 300, 450) : '',
        addedAt: item.DateCreated ? Date.parse(item.DateCreated) / 1000 : 0,
        tags: [...new Set(tags)].slice(0, 4),
        plexUrl: jellyfinItemUrl(config, id),
    };
};

const fetchJellyfinItems = async (config, includeItemTypes, limit) => {
    const baseUrl = resolveIntegrationUrlForFetch(config.jellyfinUrl);
    const params = new URLSearchParams({
        Recursive: 'true',
        IncludeItemTypes: includeItemTypes,
        SortBy: 'DateCreated',
        SortOrder: 'Descending',
        Limit: String(limit),
        Fields: 'DateCreated,PrimaryImageAspectRatio,ProductionYear,SeriesName,Album,ParentId,SeriesId,AlbumId,ImageTags,BackdropImageTags,ParentThumbItemId,PrimaryImageItemId,MediaSources,MediaStreams,ProviderIds',
        ImageTypeLimit: '1',
        EnableImageTypes: 'Primary,Thumb,Backdrop',
    });
    const response = await fetchWithTimeout(`${baseUrl}/Items?${params.toString()}`, {
        headers: jellyfinHeaders(config.jellyfinApiKey),
    }, 15000);
    if (!response.ok) {
        discardFetchBody(response);
        throw new Error(`Jellyfin Items returned HTTP ${response.status}`);
    }
    const data = await response.json();
    return Array.isArray(data.Items) ? data.Items : [];
};

app.get('/api/jellyfin/image', requireAuth, requireMember, async (req, res) => {
    const itemId = String(req.query.itemId || '').trim();
    const width = Math.min(Math.max(parseInt(req.query.width, 10) || 300, 64), 1200);
    const height = Math.min(Math.max(parseInt(req.query.height, 10) || 450, 64), 1600);
    if (!itemId || !/^[A-Za-z0-9_-]+$/.test(itemId)) return res.status(400).send('Invalid itemId');
    const failImage = (status = 500) => {
        if (res.headersSent) {
            if (!res.writableEnded) res.destroy();
            return;
        }
        res.setHeader('Cache-Control', 'no-store');
        res.status(status).send('');
    };
    try {
        const config = await loadFile(CONFIG_PATH, {});
        if (!isJellyfinConfigured(config)) return failImage(503);
        const key = mediaImageCacheKey({
            source: 'jellyfin',
            id: itemId,
            width,
            height,
        });
        await serveMediaImage(
            res,
            key,
            () => fetchJellyfinPosterBuffer(config, itemId, width, height),
            failImage,
        );
    } catch (e) {
        failImage(500);
    }
});

app.get('/api/jellyfin/user-image', requireAuth, requireMember, async (req, res) => {
    const userId = String(req.query.userId || '').trim();
    if (!userId || !/^[A-Za-z0-9_-]+$/.test(userId)) return res.status(400).send('Invalid userId');
    try {
        const config = await loadFile(CONFIG_PATH, {});
        if (!isJellyfinConfigured(config)) return res.status(503).send('');
        const baseUrl = resolveIntegrationUrlForFetch(config.jellyfinUrl);
        const imageUrl = `${baseUrl}/Users/${encodeURIComponent(userId)}/Images/Primary?fillWidth=128&fillHeight=128&quality=90`;
        const response = await fetchWithTimeout(imageUrl, {
            headers: jellyfinHeaders(config.jellyfinApiKey),
        }, 15000);
        await sendFetchImage(res, response);
    } catch (e) {
        res.status(500).send('');
    }
});

const proxyJellyfinBrandingAsset = async (res, paths, fallbackContentType = 'image/png') => {
    const config = await loadFile(CONFIG_PATH, {});
    if (!isJellyfinConfigured(config)) return res.status(503).send('');
    const baseUrl = resolveIntegrationUrlForFetch(config.jellyfinUrl);
    for (const path of paths) {
        const response = await fetchWithTimeout(`${baseUrl}${path}`, {
            headers: jellyfinHeaders(config.jellyfinApiKey, { Accept: 'image/*,*/*;q=0.8' }),
        }, 15000).catch(() => null);
        if (!response || !response.ok) {
            discardFetchBody(response);
            continue;
        }
        return sendFetchImage(res, response, { cacheControl: 'public, max-age=3600' });
    }
    return res.status(404).send('');
};

