// Chromium Android uses this for WebAPK installability. Firefox deliberately does not
// register it (a bad SW makes Firefox Install silently no-op).
const serviceWorkerScript = `/* portal-sw v11 */
self.addEventListener('install', (event) => {
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(self.clients.claim());
});

// Presence-only fetch listener — required for Chrome Android Install.
// Do NOT event.respondWith(fetch(...)): proxying every request breaks
// cross-origin posters (TMDB), fonts (Google), and Plex/user thumbs.
self.addEventListener('fetch', () => {});

const PORTAL_START = ${JSON.stringify(BASE_PATH ? `${BASE_PATH}/` : '/portal')};
const PWA_ICON_PATH = ${JSON.stringify(withBasePath('/api/public/pwa-icon?size=192'))};
const PWA_BADGE_PATH = ${JSON.stringify(withBasePath('/api/public/pwa-badge?size=96&m=sz3'))};

const toAbsoluteHref = (href) => {
  try {
    return new URL(String(href || PORTAL_START), self.registration.scope).href;
  } catch (_) {
    return PORTAL_START;
  }
};

self.addEventListener('push', (event) => {
  let data = { title: 'Notification', body: '', href: PORTAL_START, tag: 'portal' };
  try {
    if (event.data) data = { ...data, ...event.data.json() };
  } catch (_) {}
  const href = toAbsoluteHref(data.href);
  let icon = '';
  let badge = '';
  try { icon = new URL(PWA_ICON_PATH, self.registration.scope).href; } catch (_) {}
  try { badge = new URL(PWA_BADGE_PATH, self.registration.scope).href; } catch (_) {}
  const iconUrl = typeof data.icon === 'string' && /^https?:\\/\\//i.test(data.icon) ? data.icon : '';
  const badgeUrl = typeof data.badge === 'string' && /^https?:\\/\\//i.test(data.badge) ? data.badge : '';
  const image = typeof data.image === 'string' && /^https?:\\/\\//i.test(data.image) ? data.image : '';
  const options = {
    body: String(data.body || ''),
    tag: String(data.tag || 'portal'),
    data: { href },
    icon: iconUrl || image || icon || undefined,
    badge: badgeUrl || badge || undefined,
    image: image || undefined,
    renotify: true,
    vibrate: [120, 80, 120],
  };
  event.waitUntil(self.registration.showNotification(String(data.title || 'Notification'), options));
});

self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  const href = (event.notification && event.notification.data && event.notification.data.href) || toAbsoluteHref(PORTAL_START);
  event.waitUntil((async () => {
    const allClients = await clients.matchAll({ type: 'window', includeUncontrolled: true });
    for (const client of allClients) {
      try {
        let sameOrigin = false;
        try { sameOrigin = new URL(client.url).origin === self.location.origin; } catch (_) {}
        if (!sameOrigin) continue;
        if ('focus' in client) await client.focus();
        if (href && typeof client.navigate === 'function') {
          try { await client.navigate(href); return; } catch (_) {}
        }
      } catch (_) {}
    }
    if (clients.openWindow) await clients.openWindow(href);
  })());
});
`;

const sendServiceWorker = (_req, res) => {
    res.setHeader('Content-Type', 'application/javascript; charset=utf-8');
    res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate');
    res.setHeader('Service-Worker-Allowed', BASE_PATH ? `${BASE_PATH}/` : '/');
    res.send(serviceWorkerScript);
};

app.get('/service-worker.js', sendServiceWorker);
