app.post('/api/spotify-to-plex/sync-playlist', requireAdmin, requireSpotifyToPlex, async (req, res) => {
    try {
        const config = req.spotifyToPlexConfig || await loadFile(CONFIG_PATH, {});
        const hasIds = Array.isArray(req.body?.ids);
        const idValue = req.body?.id != null ? String(req.body.id).trim() : '';
        const ids = hasIds ? req.body.ids : (idValue ? [idValue] : []);
        const all = req.body?.all === true || (!hasIds && !idValue);
        const job = startSpotifyPlaylistSyncJob({
            ids,
            all,
            fast: req.body?.fast !== false,
            run: async ({ ids: jobIds, all: jobAll, fast, onProgress }) => {
                try {
                    await applySpotifyToPlexPortalDefaults(config, spotifyToPlexPortalDefaultsDeps());
                } catch (error) {
                    log(`[spotify-sync] Plex defaults before playlist sync: ${error?.message || error}`);
                }
                let workerPlex = {};
                try {
                    workerPlex = await fetchSpotifyToPlexJson({
                        config,
                        path: '/api/settings',
                        fetchWithTimeout,
                        allowPrivate: ALLOW_PRIVATE_INTEGRATION_URLS,
                    }) || {};
                } catch {
                    workerPlex = {};
                }
                let filePlex = { uri: '', token: '' };
                try {
                    const parsed = JSON.parse(fsSync.readFileSync(getSpotifyToPlexPlexConfigPath(CONFIG_DIR), 'utf8'));
                    filePlex = {
                        uri: String(parsed?.uri || '').trim().replace(/\/+$/, ''),
                        token: String(parsed?.serverToken || parsed?.token || '').trim(),
                    };
                } catch {
                    filePlex = { uri: '', token: '' };
                }
                const plexBaseUrl = resolveConfiguredPlexServerUrl(config)
                    || filePlex.uri
                    || String(workerPlex.uri || '').trim().replace(/\/+$/, '');
                const plexToken = String(config.plexToken || filePlex.token || '').trim();
                const applyArtwork = createPlaylistArtworkApplier({
                    fetchImpl: (url, opts) => fetchWithTimeout(url, opts, 20000),
                    plexBaseUrl,
                    plexToken,
                    plexHeaders: plexClientHeaders,
                    allowPrivate: ALLOW_PRIVATE_INTEGRATION_URLS,
                    log,
                });
                if (!applyArtwork) {
                    log(`[spotify-sync] Playlist artwork skipped: missing Plex URL or token.`);
                }
                return syncSpotifyPlaylistsToPlex({
                    ids: jobIds,
                    all: jobAll,
                    fast,
                    onProgress,
                    workerBase: resolveSpotifyToPlexBase(config, { allowPrivate: ALLOW_PRIVATE_INTEGRATION_URLS }),
                    applyArtwork,
                    fetchJson: (opts) => fetchSpotifyToPlexJson({
                        config,
                        fetchWithTimeout,
                        allowPrivate: ALLOW_PRIVATE_INTEGRATION_URLS,
                        ...opts,
                    }),
                });
            },
        });
        return res.status(202).json({
            ok: true,
            started: true,
            message: 'Playlist sync started on the server.',
            playlistSync: job,
        });
    } catch (e) {
        if (Number(e?.status) === 409) {
            return res.status(409).json({ error: e.message, playlistSync: e.job || snapshotSpotifyPlaylistSyncJob() });
        }
        return res.status(e?.status || 502).json({ error: e.message || 'Failed to start playlist sync.' });
    }
});

