/** Persist Start/Pause so encode gating survives container restarts. */
const setMediaAutomationWorkerPaused = async (paused) => {
    const config = await loadFile(CONFIG_PATH, {});
    const existing = config.mediaAutomation && typeof config.mediaAutomation === 'object'
        ? config.mediaAutomation
        : {};
    const nextMediaAutomation = normalizeMediaAutomationConfig({
        ...existing,
        workerPaused: paused === true,
    }, existing);
    await saveFile(CONFIG_PATH, {
        ...config,
        mediaAutomation: {
            ...existing,
            ...nextMediaAutomation,
            workerPaused: paused === true,
        },
    });
    return paused === true;
};

// Pause-when-streaming: count active Plex/Jellyfin playback sessions (short cache
// so the scheduler poll cannot hammer the media servers).
let mediaStreamCountCache = { at: 0, count: 0 };
const countActiveMediaStreams = async () => {
    const now = Date.now();
    if (now - mediaStreamCountCache.at < 15_000) return mediaStreamCountCache.count;
    const config = await loadFile(CONFIG_PATH, {});
    let count = 0;
    if (config.plexToken) {
        try {
            const uri = await getPlexConnectionUri(config);
            if (uri) {
                const data = await fetch(`${uri}/status/sessions?X-Plex-Token=${config.plexToken}`, { headers: plexClientHeaders(config.plexToken) })
                    .then((r) => (r.ok ? r.json() : null))
                    .catch(() => null);
                count += Array.isArray(data?.MediaContainer?.Metadata) ? data.MediaContainer.Metadata.length : 0;
            }
        } catch { /* best effort — scheduler fails open */ }
    }
    if (config.jellyfinUrl && config.jellyfinApiKey) {
        try {
            const baseUrl = resolveIntegrationUrlForFetch(config.jellyfinUrl);
            const sessions = await fetchWithTimeout(`${baseUrl}/Sessions`, { headers: jellyfinHeaders(config.jellyfinApiKey) }, 10000)
                .then((r) => (r.ok ? r.json() : []))
                .catch(() => []);
            count += (Array.isArray(sessions) ? sessions : []).filter((session) => session?.NowPlayingItem).length;
        } catch { /* best effort */ }
    }
    mediaStreamCountCache = { at: now, count };
    return count;
};

// Arr rescan hooks: match the changed file to a Sonarr series / Radarr movie by
// path prefix (library lists cached briefly) and request a targeted rescan.
const ARR_RESCAN_CACHE_TTL_MS = 5 * 60_000;
const ARR_RESCAN_CACHE_MAX_ENTRIES = 32;
const arrRescanListCache = new Map();
const pruneArrRescanListCache = () => {
    const now = Date.now();
    for (const [key, entry] of arrRescanListCache.entries()) {
        if (!entry || now - entry.at >= ARR_RESCAN_CACHE_TTL_MS) arrRescanListCache.delete(key);
    }
    while (arrRescanListCache.size > ARR_RESCAN_CACHE_MAX_ENTRIES) {
        const oldest = arrRescanListCache.keys().next().value;
        if (oldest === undefined) break;
        arrRescanListCache.delete(oldest);
    }
};
const arrCachedList = async (instance, endpoint) => {
    const key = `${instance.id}:${endpoint}`;
    const cached = arrRescanListCache.get(key);
    if (cached && Date.now() - cached.at < ARR_RESCAN_CACHE_TTL_MS) return cached.items;
    if (cached) arrRescanListCache.delete(key);
    const items = await fetchArrInstanceJson(instance, endpoint, {
        resolveUrl: resolveIntegrationUrlForFetch,
        fetchImpl: fetch,
        timeoutMs: 60_000,
    });
    const list = Array.isArray(items) ? items : [];
    arrRescanListCache.set(key, { at: Date.now(), items: list });
    pruneArrRescanListCache();
    return list;
};

const normalizeMediaPathForMatch = (value) => String(value || '').replace(/\\/g, '/').replace(/\/+$/, '').toLowerCase();
const mediaPathIsWithin = (child, parent) => {
    const childPath = normalizeMediaPathForMatch(child);
    const parentPath = normalizeMediaPathForMatch(parent);
    return !!parentPath && (childPath === parentPath || childPath.startsWith(`${parentPath}/`));
};

const postArrCommand = (instance, body) => fetchArrInstance(instance, '/api/v3/command', {
    resolveUrl: resolveIntegrationUrlForFetch,
    fetchImpl: fetch,
    method: 'POST',
    body,
    timeoutMs: 30_000,
});

const triggerArrRescanForPath = async (config, filePath) => {
    const results = [];
    for (const instance of getArrInstances(config, { type: 'sonarr', enabledOnly: true }).filter(isArrInstanceReady)) {
        const series = await arrCachedList(instance, '/api/v3/series');
        const match = series
            .filter((entry) => entry?.path && mediaPathIsWithin(filePath, entry.path))
            .sort((a, b) => String(b.path).length - String(a.path).length)[0];
        if (!match) continue;
        const response = await postArrCommand(instance, { name: 'RescanSeries', seriesId: match.id });
        results.push({ type: 'sonarr', instance: instance.name || instance.id, title: match.title, ok: !!response?.ok });
    }
    for (const instance of getArrInstances(config, { type: 'radarr', enabledOnly: true }).filter(isArrInstanceReady)) {
        const movies = await arrCachedList(instance, '/api/v3/movie');
        const match = movies
            .filter((entry) => mediaPathIsWithin(filePath, entry?.path || entry?.folderName))
            .sort((a, b) => String(b.path || b.folderName || '').length - String(a.path || a.folderName || '').length)[0];
        if (!match) continue;
        const response = await postArrCommand(instance, { name: 'RescanMovie', movieId: match.id });
        results.push({ type: 'radarr', instance: instance.name || instance.id, title: match.title, ok: !!response?.ok });
    }
    return results;
};

const collectScannerPathRewrites = (scanner) => collectMountRewrites(
    scanner?.targets?.plex,
    scanner?.triggers?.sonarr,
    scanner?.triggers?.radarr,
    scanner?.triggers?.lidarr,
    scanner?.triggers?.mediaAutomation,
);

/**
 * Only queue Scanner when the finished file lives under a library root (Plex-visible),
 * never under a library Output/ staging folder.
 */
const resolveScannerRefreshFilePath = async (event = {}) => {
    const mode = String(event.outputMode || '').toLowerCase();
    if (mode !== 'copy' && mode !== 'replace') return null;

    let libraries = [];
    try {
        libraries = await mediaAutomationService?.libraries?.list?.() || [];
    } catch {
        libraries = [];
    }
    const roots = libraries
        .filter((library) => library?.enabled !== false)
        .map((library) => path.resolve(String(library.rootPath || '').trim()))
        .filter(Boolean);
    const outputDirs = libraries
        .map((library) => String(library.outputPath || '').trim())
        .filter(Boolean)
        .map((entry) => path.resolve(entry));

    const under = (candidate, root) => {
        const abs = path.resolve(String(candidate || ''));
        const base = path.resolve(String(root || ''));
        if (!abs || !base) return false;
        return abs === base || abs.startsWith(`${base}${path.sep}`);
    };

    // Prefer the library-side file: replace → original/final; copy → final only if it landed in-library.
    const candidates = mode === 'replace'
        ? [event.finalPath, event.sourcePath]
        : [event.finalPath, event.deliveredPath];

    for (const candidate of candidates) {
        const filePath = String(candidate || '').trim();
        if (!filePath) continue;
        if (outputDirs.some((dir) => under(filePath, dir))) continue;
        if (!roots.some((root) => under(filePath, root))) continue;
        return filePath;
    }
    return null;
};

/**
 * Queue a season/parent-folder Scanner refresh for a Media Automation library write.
 * Applies Settings → Scanner → Media Automation path rewrites (from = Automation path,
 * to = Scanner/Plex path), same pattern as Sonarr webhook triggers.
 */
const enqueueInstantLibraryRefresh = async (config, filePath, {
    reason = 'Media Automation completed',
    title = null,
} = {}) => {
    if (!config.scannerEnabled) return { skipped: true, reason: 'scanner-disabled' };
    const folder = path.dirname(String(filePath || '').trim());
    if (!folder || folder === '.' || folder === '/' || folder === '\\') {
        return { skipped: true, reason: 'missing-folder' };
    }
    const scanner = normalizeScannerConfig(config.scanner, getDefaultScannerConfig());
    const automationTriggers = scanner.triggers?.mediaAutomation || [];
    const automationRewrites = collectMountRewrites(automationTriggers);
    const priority = Number(automationTriggers[0]?.priority) || 20;
    const scans = buildScansFromPaths([folder], {
        priority,
        source: 'media-automation',
        rewrite: automationRewrites,
        eventType: 'Processed',
        action: 'refresh',
        reason,
        title: title || path.basename(String(filePath || '')),
    });
    if (!scans.length) return { skipped: true, reason: 'no-scans' };
    await enqueueScans(scans);
    void processOne(scannerPortalConfig(config), scanner);
    return { skipped: false, folders: scans.map((entry) => entry.folder) };
};

const triggerPlexRescanForPath = async (config, filePath) => {
    const targetPath = String(filePath || '').trim();
    if (!targetPath) return { skipped: true, reason: 'missing-path' };
    const url = String(config.plexServerUrl || config.plexUrl || '').trim();
    const token = String(config.plexToken || '').trim();
    if (!url || !token) return { skipped: true, reason: 'plex-not-configured' };
    const scanner = normalizeScannerConfig(config.scanner, getDefaultScannerConfig());
    const rewrites = collectScannerPathRewrites(scanner);
    const target = createPlexTarget({
        url,
        token,
        rewrite: rewrites,
    });
    // Season/show parent folder — Plex target expands rewrite candidates itself.
    const folder = path.dirname(targetPath);
    const refresh = await target.scan(folder);
    // Same-path Replace keeps the filename — folder refresh alone can still leave stale codec metadata.
    // Analyze the episode/movie leaf and wait until Plex Media Info matches ffprobe when possible.
    let expectedVideoCodec = null;
    try {
        const runtime = mediaAutomationRuntimeConfig(config);
        const probe = await probeMedia(targetPath, {
            ffprobePath: runtime.ffprobePath || 'ffprobe',
            timeoutMs: 30_000,
        });
        const video = (probe.streams || []).find((stream) => stream.codec_type === 'video');
        expectedVideoCodec = String(video?.codec_name || '').trim() || null;
    } catch {
        expectedVideoCodec = null;
    }
    let analyze = null;
    try {
        analyze = await target.analyzeFile(targetPath, {
            initialDelayMs: 3000,
            retries: 5,
            retryDelayMs: 2500,
            expectedVideoCodec,
            verifyTimeoutMs: 60_000,
        });
    } catch (error) {
        analyze = { skipped: true, reason: error.message || 'analyze-failed', analyzed: [] };
    }
    return {
        ...refresh,
        analyze,
        analyzed: analyze?.analyzed || [],
        expectedVideoCodec,
    };
};

mediaAutomationService = createMediaAutomation({
    dataDir: MEDIA_AUTOMATION_DIR,
    queuePath: MEDIA_AUTOMATION_QUEUE_PATH,
    getConfig: getMediaAutomationServiceConfig,
    logger: console,
    getActiveStreamCount: countActiveMediaStreams,
    setWorkerPaused: setMediaAutomationWorkerPaused,
    // Cheap path→watchCount lookup from maintenance-media-index.json (no live Plex calls).
    getWatchStats: createWatchStatsLookup({
        indexPath: MAINTENANCE_MEDIA_INDEX_PATH,
        logger: console,
    }).getWatchStats,
    onMediaCommitted: async (event) => {
        const config = await loadFile(CONFIG_PATH, {});
        const runtime = mediaAutomationRuntimeConfig(config);

        if (runtime.arrRescanEnabled) {
            try {
                // Delivered to a mapped Sonarr drop folder: ask Sonarr to import it properly.
                if (event.deliveredPath && event.deliveryTargetId) {
                    const target = (runtime.deliveryTargets || []).find((entry) => String(entry.id) === String(event.deliveryTargetId));
                    const instance = target?.sonarrInstanceId ? getArrInstance(config, target.sonarrInstanceId) : null;
                    if (instance && isArrInstanceReady(instance)) {
                        const response = await postArrCommand(instance, {
                            name: 'DownloadedEpisodesScan',
                            path: event.deliveredPath,
                            importMode: 'Move',
                        });
                        log(`[media-automation] Sonarr drop-folder import ${response?.ok ? 'requested' : 'failed'}: ${event.deliveredPath}`);
                    } else {
                        const targetPath = event.finalPath || event.sourcePath;
                        if (targetPath) {
                            const results = await triggerArrRescanForPath(config, targetPath);
                            if (results.length) {
                                log(`[media-automation] Arr rescan requested for ${path.basename(targetPath)}: ${results.map((entry) => `${entry.type}:${entry.title}${entry.ok ? '' : ' (failed)'}`).join(', ')}`);
                            }
                        }
                    }
                } else {
                    const targetPath = event.finalPath || event.sourcePath;
                    if (targetPath) {
                        const results = await triggerArrRescanForPath(config, targetPath);
                        if (results.length) {
                            log(`[media-automation] Arr rescan requested for ${path.basename(targetPath)}: ${results.map((entry) => `${entry.type}:${entry.title}${entry.ok ? '' : ' (failed)'}`).join(', ')}`);
                        }
                    }
                }
            } catch (error) {
                log(`[media-automation] Arr rescan hook failed: ${error.message}`);
            }
        }

        if (runtime.scannerRefreshEnabled) {
            try {
                const libraryFile = await resolveScannerRefreshFilePath(event);
                if (!libraryFile) {
                    log('[media-automation] Scanner refresh skipped: finished file is not under a library root (Output/completed paths are ignored)');
                } else {
                    const queued = await enqueueInstantLibraryRefresh(config, libraryFile, {
                        reason: 'Media Automation library write — Scanner refresh',
                        title: path.basename(String(libraryFile)),
                    });
                    if (!queued.skipped) {
                        log(`[media-automation] Scanner refresh queued: ${(queued.folders || []).join(', ')}`);
                    } else if (queued.reason && queued.reason !== 'scanner-disabled') {
                        log(`[media-automation] Scanner refresh skipped: ${queued.reason}`);
                    }
                }
            } catch (error) {
                log(`[media-automation] Scanner refresh failed: ${error.message}`);
            }
        }

        if (runtime.plexRescanEnabled) {
            try {
                const targetPath = event.deliveredPath || event.finalPath || event.sourcePath;
                if (!targetPath) return;
                const result = await triggerPlexRescanForPath(config, targetPath);
                if (result?.skipped && !(result?.analyzed || []).length) {
                    log(`[media-automation] Plex refresh skipped for ${path.basename(String(targetPath))}: ${result.reason || 'unknown'}`);
                } else {
                    const libraries = (result?.results || []).map((entry) => entry.library || entry.id).filter(Boolean);
                    const analyzedKeys = (result?.analyzed || []).map((entry) => entry.ratingKey).filter(Boolean);
                    log(`[media-automation] Plex refresh requested for ${path.dirname(String(targetPath))}${libraries.length ? ` (${libraries.join(', ')})` : ''}`);
                    if (analyzedKeys.length) {
                        const codecBits = (result?.analyzed || [])
                            .map((entry) => {
                                if (!entry?.ratingKey) return null;
                                if (entry.codecMatched === true) return `${entry.ratingKey}:${entry.videoCodec || 'ok'}`;
                                if (entry.codecMatched === false) {
                                    return `${entry.ratingKey}:still-${entry.videoCodec || 'unknown'}(want ${result.expectedVideoCodec || '?'})`;
                                }
                                return String(entry.ratingKey);
                            })
                            .filter(Boolean);
                        log(`[media-automation] Plex analyze requested for ${path.basename(String(targetPath))} (${codecBits.join(', ')})`);
                    } else if (result?.analyze?.skipped) {
                        const candidates = Array.isArray(result.analyze.candidates) && result.analyze.candidates.length
                            ? ` (tried ${result.analyze.candidates.join(' | ')})`
                            : '';
                        log(`[media-automation] Plex analyze skipped for ${path.basename(String(targetPath))}: ${result.analyze.reason || 'unknown'}${candidates}`);
                    }
                }
            } catch (error) {
                log(`[media-automation] Plex refresh hook failed: ${error.message}`);
            }
        }
    },
    resolveDeliveryNaming: async ({ target, sourcePath } = {}) => {
        try {
            const config = await loadFile(CONFIG_PATH, {});
            const instance = target?.sonarrInstanceId
                ? getArrInstance(config, target.sonarrInstanceId)
                : getArrInstances(config, { type: 'sonarr', enabledOnly: true }).find(isArrInstanceReady);
            if (!instance || !isArrInstanceReady(instance)) return null;
            const namingConfig = await fetchArrInstanceJson(instance, '/api/v3/config/naming', {
                resolveUrl: resolveIntegrationUrlForFetch,
                fetchImpl: fetch,
            });
            const basename = path.basename(String(sourcePath || ''));
            const stem = basename.replace(/\.[^.]+$/, '');
            const seriesMatch = /^(.*?)[\s._-]*[Ss](\d{1,2})[Ee](\d{1,3})/.exec(stem);
            const namingContext = seriesMatch
                ? {
                    seriesTitle: String(seriesMatch[1] || '').replace(/[._]+/g, ' ').trim(),
                    series: String(seriesMatch[1] || '').replace(/[._]+/g, ' ').trim(),
                    seasonNumber: Number(seriesMatch[2]),
                    episodeNumber: Number(seriesMatch[3]),
                    n: String(seriesMatch[1] || '').replace(/[._]+/g, ' ').trim(),
                    title: String(seriesMatch[1] || '').replace(/[._]+/g, ' ').trim(),
                }
                : {
                    movieTitle: stem.replace(/[._]+/g, ' ').trim(),
                    movie: stem.replace(/[._]+/g, ' ').trim(),
                    n: stem.replace(/[._]+/g, ' ').trim(),
                    title: stem.replace(/[._]+/g, ' ').trim(),
                };
            return { namingConfig, namingContext };
        } catch (error) {
            log(`[media-automation] Sonarr naming lookup failed: ${error.message}`);
            return null;
        }
    },
    onActivity: async (entry) => {
        log(`[media-automation] ${entry.message || entry.type}`);
        if (entry.type === 'job.failed') {
            try {
                const config = await loadFile(CONFIG_PATH, {});
                if (config.mediaAutomation?.notifyOnJobFailed) {
                    await sendGotifyAlert(
                        config,
                        'Media Automation job failed',
                        entry.message || 'Job failed',
                        8,
                    );
                }
                await notifyOps('media_job_failed', {
                    title: entry.message || 'Job failed',
                    dedupeKey: `media-job-failed:${entry.jobId || entry.message || Date.now()}`,
                    meta: await mediaJobNotifyMeta(entry, config),
                });
                if (config.mediaAutomation?.notifyOnFailBurst) {
                    const now = Date.now();
                    if (!globalThis.__maFailBurst) {
                        globalThis.__maFailBurst = { times: [], lastDigestAt: 0 };
                    }
                    const burst = globalThis.__maFailBurst;
                    burst.times = burst.times.filter((ts) => now - ts < 15 * 60_000);
                    burst.times.push(now);
                    if (burst.times.length >= 5 && now - burst.lastDigestAt > 15 * 60_000) {
                        burst.lastDigestAt = now;
                        await sendGotifyAlert(
                            config,
                            'Media Automation failure burst',
                            `${burst.times.length} jobs failed in the last 15 minutes.`,
                            8,
                        );
                    }
                }
            } catch (error) {
                log(`[media-automation] Gotify notify failed: ${error.message}`);
            }
        }
        if (entry.type === 'library.scan.completed' || entry.type === 'library.scan.cancelled') {
            try {
                const config = await loadFile(CONFIG_PATH, {});
                if (config.mediaAutomation?.notifyOnScanComplete) {
                    const data = entry.data || {};
                    await sendGotifyAlert(
                        config,
                        entry.type === 'library.scan.cancelled'
                            ? 'Media Automation scan cancelled'
                            : 'Media Automation scan complete',
                        entry.message
                            || `discovered ${data.discovered || 0}, queued ${data.enqueued || 0}, skipped ${data.skipped || 0}`,
                        5,
                    );
                }
            } catch (error) {
                log(`[media-automation] Gotify scan notify failed: ${error.message}`);
            }
        }
        if (entry.type === 'job.completed') {
            try {
                const config = await loadFile(CONFIG_PATH, {});
                await notifyOps('media_job_completed', {
                    title: entry.message || 'Job completed',
                    dedupeKey: `media-job-completed:${entry.jobId || Date.now()}`,
                    meta: await mediaJobNotifyMeta(entry, config),
                });
            } catch (error) {
                log(`[media-automation] job complete notify failed: ${error.message}`);
            }
        }
        // Scanner / Plex refresh is handled only by onMediaCommitted (gated by
        // scannerRefreshEnabled / plexRescanEnabled). Do not enqueue here — the old
        // fallback queued Scanner on every job.completed when both toggles were off.
    },
});

const requireMediaAutomation = async (req, res, next) => {
    try {
        const config = await loadFile(CONFIG_PATH, {});
        if (!config.mediaAutomationEnabled) {
            return res.status(403).json({ error: 'Media Automation is disabled. Enable it in Settings first.' });
        }
        return next();
    } catch {
        return res.status(500).json({ error: 'Failed to check Media Automation feature flag.' });
    }
};

