const loadMediaAutomationCapabilities = async ({ force = false } = {}) => {
    if (!force && mediaAutomationCapabilitiesCache && Date.now() - mediaAutomationCapabilitiesAt < 60_000) {
        return mediaAutomationCapabilitiesCache;
    }
    const config = mediaAutomationRuntimeConfig(await loadFile(CONFIG_PATH, {}));
    const [ffmpegVersion, ffprobeVersion, detected] = await Promise.all([
        spawnCommand(config.ffmpegPath, ['-version'], { timeoutMs: 15_000 }),
        spawnCommand(config.ffprobePath, ['-version'], { timeoutMs: 15_000 }),
        detectFfmpegCapabilities({
            ffmpegPath: config.ffmpegPath,
            vaapiDevice: config.vaapiDevice,
            runSyntheticTests: true,
            timeoutMs: 30_000,
        }),
    ]);
    const firstLine = (value) => String(value || '').split(/\r?\n/)[0] || '';
    const details = detected.details || {};
    const encoders = [...new Set(
        Object.values(details).flatMap((entry) => Array.isArray(entry?.encoders) ? entry.encoders : []),
    )].sort();
    mediaAutomationCapabilitiesCache = {
        available: true,
        ffmpeg: { available: true, version: firstLine(ffmpegVersion.stdout || ffmpegVersion.stderr) },
        ffprobe: { available: true, version: firstLine(ffprobeVersion.stdout || ffprobeVersion.stderr) },
        hardware: Object.entries(detected)
            .filter(([name, available]) => name !== 'details' && name !== 'devices' && available)
            .map(([name]) => name),
        encoders,
        details,
        devices: detected.devices || null,
        plugins: mediaAutomationService.plugins.list().map((plugin) => ({
            id: plugin.id,
            type: plugin.type,
            label: plugin.label,
        })),
    };
    mediaAutomationCapabilitiesAt = Date.now();
    return mediaAutomationCapabilitiesCache;
};

app.get('/api/media-automation/status', requireAdmin, requireMediaAutomation, async (req, res) => {
    try {
        const status = await mediaAutomationService.status();
        const jobs = status.jobs || [];
        const config = await loadFile(CONFIG_PATH, {});
        // Completed/failed + 24h/7d/30d metrics come from durable history (service.status),
        // not the live queue — clearing finished jobs must not reset Overview counters.
        res.json({
            ...status,
            enabled: true,
            paused: status.workerPaused !== false,
            workerPaused: status.workerPaused !== false,
            workerState: status.autoPausedForQueueDepth
                ? 'auto-paused'
                : (status.workerPaused !== false
                    ? 'paused'
                    : (status.running ? 'running' : 'stopped')),
            autoPausedForQueueDepth: !!status.autoPausedForQueueDepth,
            activeJobs: jobs.filter((job) => job.state === 'running').length,
            queuedJobs: jobs.filter((job) => job.state === 'queued').length,
            completedJobs: status.completedJobs ?? 0,
            failedJobs: status.failedJobs ?? 0,
            watchEnvEnabled: mediaAutomationWatchOptIn(),
            libraryWatchConfigured: config.mediaAutomation?.libraryWatchEnabled === true,
            notifyOnJobFailed: config.mediaAutomation?.notifyOnJobFailed === true,
            notifyOnScanComplete: config.mediaAutomation?.notifyOnScanComplete === true,
            notifyOnFailBurst: config.mediaAutomation?.notifyOnFailBurst === true,
            minFreeDiskGb: Number(config.mediaAutomation?.minFreeDiskGb ?? status.minFreeDiskGb ?? 20),
            autoPauseQueueDepth: Number(config.mediaAutomation?.autoPauseQueueDepth ?? status.autoPauseQueueDepth ?? 0),
            pathDenyList: Array.isArray(config.mediaAutomation?.pathDenyList)
                ? config.mediaAutomation.pathDenyList
                : (status.pathDenyList || []),
            quietHoursEnabled: config.mediaAutomation?.quietHoursEnabled === true
                || status.quietHoursEnabled === true,
            quietHoursStart: config.mediaAutomation?.quietHoursStart || status.quietHoursStart || '23:00',
            quietHoursEnd: config.mediaAutomation?.quietHoursEnd || status.quietHoursEnd || '07:00',
            quietHoursDays: Array.isArray(config.mediaAutomation?.quietHoursDays)
                ? config.mediaAutomation.quietHoursDays
                : (status.quietHoursDays || []),
            quietHoursActive: !!status.quietHoursActive,
            scanProgress: status.scanProgress || null,
            recentScans: status.recentScans || [],
            workerGroups: status.workerGroups || config.mediaAutomation?.workerGroups || [],
            deliveryTargets: status.deliveryTargets || config.mediaAutomation?.deliveryTargets || [],
            savings: status.savings || null,
            metrics: status.metrics || {
                processed24h: 0,
                failed24h: 0,
                cancelled24h: 0,
                successRate24h: null,
                bytesIn24h: 0,
                bytesOut24h: 0,
                bytesSaved24h: 0,
                encodeMs24h: 0,
                bytesSaved7d: status.savings?.['7d']?.bytesSaved || 0,
                encodeMs7d: status.savings?.['7d']?.encodeMs || 0,
                bytesSaved30d: status.savings?.['30d']?.bytesSaved || 0,
                encodeMs30d: status.savings?.['30d']?.encodeMs || 0,
            },
        });
    } catch (error) {
        res.status(500).json({ error: error.message || 'Failed to load Media Automation status' });
    }
});

