// Monitor Plex sessions to track high watermarks
async function monitorConcurrentSessions() {
    try {
        const config = await loadFile(CONFIG_PATH, null);
        if (!config || !config.plexToken || !config.serverIdentifier) return;

        const uri = await getPlexConnectionUri(config);
        if (!uri) return;

        const sessionsRes = await fetchPlexStatusSessions(uri, config);
        // Warm Now Playing / watching-count SWR so Home polls stay near-instant.
        if (sessionsRes) {
            mediaSessionsSwr.put(PLEX_SESSIONS_SWR_KEY, sessionsRes);
        }

        if (sessionsRes && sessionsRes.MediaContainer) {
            const currentStreams = sessionsRes.MediaContainer.size || 0;

            // Evaluate kill rules against live sessions
            if (sessionsRes.MediaContainer.Metadata) {
                const sessionObjs = sessionsRes.MediaContainer.Metadata.map(m => {
                    const isTranscode = !!(m.TranscodeSession || (m.Media && m.Media[0] && m.Media[0].Part && m.Media[0].Part[0] && m.Media[0].Part[0].Stream && m.Media[0].Part[0].Stream.some(s => s.decision === 'transcode')));
                    const player = m.Player || {};
                    const session = m.Session || {};
                    const transcodeResolutionRaw = m?.TranscodeSession?.videoResolution || '';
                    const sourceResolution = m.Media && m.Media[0] ? m.Media[0].videoResolution : null;
                    return {
                        sessionId: session.id || m.sessionKey,
                        user: m.User ? m.User.title : 'Unknown',
                        isTranscoding: isTranscode,
                        sourceResolution: sourceResolution ? String(sourceResolution).toLowerCase() : null,
                        resolution: normalizeRuleResolution(sourceResolution, isTranscode, transcodeResolutionRaw),
                        bandwidth: normalizePlexBandwidthKbps((session && session.bandwidth) || (m.Media && m.Media[0] && m.Media[0].bitrate) || 0),
                        playerProduct: player.product || '',
                        playerTitle: player.title || '',
                        state: player.state || 'playing',
                        type: m.type || '',
                        sessionLocation: session.location || 'lan',
                        videoCodec: m.Media && m.Media[0] ? m.Media[0].videoCodec : '',
                        audioCodec: m.Media && m.Media[0] ? m.Media[0].audioCodec : '',
                        transcodeVideoDecision: m.TranscodeSession ? m.TranscodeSession.videoDecision : 'directplay',
                    };
                });
                await evaluateKillRules(config, uri, sessionObjs);
            }
            let currentDirect = 0;
            let currentTranscodes = 0;

            if (sessionsRes.MediaContainer.Metadata) {
                sessionsRes.MediaContainer.Metadata.forEach(m => {
                    let isTranscode = false;
                    if (m.TranscodeSession) {
                        isTranscode = true;
                    } else if (m.Media && m.Media.length > 0) {
                        for (const media of m.Media) {
                            if (media.Part && media.Part.length > 0) {
                                for (const part of media.Part) {
                                    if (part.decision === 'transcode' || (part.Stream && part.Stream.some(s => s.decision === 'transcode'))) {
                                        isTranscode = true;
                                        break;
                                    }
                                }
                            }
                        }
                    }
                    if (isTranscode) {
                        currentTranscodes++;
                    } else {
                        currentDirect++;
                    }
                });
            }

            const stats = await loadFile(PLEX_STATS_CACHE_PATH, {});
            let updated = false;

            if (currentStreams > (stats.maxConcurrentStreams || 0)) {
                stats.maxConcurrentStreams = currentStreams;
                updated = true;
            }
            if (currentDirect > (stats.maxDirectPlays || 0)) {
                stats.maxDirectPlays = currentDirect;
                updated = true;
            }
            if (currentTranscodes > (stats.maxTranscodes || 0)) {
                stats.maxTranscodes = currentTranscodes;
                updated = true;
            }

            if (updated) {
                await saveFile(PLEX_STATS_CACHE_PATH, stats);
            }
        }
    } catch (e) {
        log(`[PlexStats] Session monitor failed: ${e.message}`);
    }
}

// Last middleware: API routes must never fall through to Express HTML error pages.
// The client treats non-JSON bodies as "An unknown API error occurred."
app.use((err, req, res, next) => {
    if (!err) return next();
    if (res.headersSent) return next(err);
    const url = String(req.originalUrl || req.url || req.path || '');
    if (!url.includes('/api/')) return next(err);
    const status = Number(err.status || err.statusCode) || 500;
    const parseErr = err.type === 'entity.parse.failed'
        || (err instanceof SyntaxError && status === 400);
    const safeStatus = status >= 400 && status < 600 ? status : 500;
    const message = parseErr
        ? 'Invalid JSON body.'
        : String(err.message || 'Request failed.');
    log(`API ${req.method} ${url} failed: ${err.stack || message}`);
    return res.status(safeStatus).json({ error: message });
});

app.listen(PORT, BIND_HOST, async () => {
    log(`--- StreamPilot Service starting on http://${BIND_HOST}:${PORT} ---`);
    log(`Runtime: CONFIG_DIR=${CONFIG_DIR}, FORCE_SECURE_COOKIES=${FORCE_SECURE_COOKIES}, BASE_PATH=${BASE_PATH || '/'}, appVersion=${appVersion}`);
    if (!arePortalFrontendAssetsReady()) {
        log('CRITICAL: Frontend build assets missing (static/tailwind.css and/or static/index.js). Pull the latest Docker image or run npm run build before serving the UI.');
    }
    if (FORCE_SECURE_COOKIES) {
        log('WARNING: FORCE_SECURE_COOKIES=true — plain HTTP logins (http://LAN-IP:2121) will fail until this is set to false.');
    }

    await migrateConfigFiles((message) => log(`[config] ${message}`));
    try {
        const spotifyEnvPath = getSpotifyToPlexEnvFilePath(CONFIG_DIR);
        await fs.access(spotifyEnvPath);
    } catch {
        await fs.writeFile(
            getSpotifyToPlexEnvFilePath(CONFIG_DIR),
            '# Configure in Settings → Spotify Sync, then Save Settings. Restart spotify-to-plex after credential changes.\n',
            { mode: 0o600 },
        );
    }
    try {
        const migratedBranding = await migrateLegacyBrandingAssets(BRANDING_DIR, staticDir, (message) => log(message));
        if (migratedBranding > 0) {
            log(`[Branding] migrated ${migratedBranding} legacy static asset(s) into ${BRANDING_DIR}`);
        }
    } catch (error) {
        log(`[Branding] legacy static migrate failed: ${error.message}`);
    }
    try {
        const migratedTokens = await migratePlexAuthTokensAtRest();
        if (migratedTokens > 0) {
            log(`[security] Encrypted ${migratedTokens} legacy member Plex token(s) at rest`);
        }
    } catch (error) {
        log(`[security] Plex token encryption migrate failed: ${error.message}`);
    }

    // Ensure unique, *stable* CLIENT_ID per installation (survives Docker recreates).
    // Without this, PMS may register the container hostname (e.g. 151a94f8…) as a new device each restart.
    let config = await loadFile(CONFIG_PATH, {});
    // Seed Portal UI Public Base URL from PUBLIC_BASE_URL when the UI field was never set.
    if (!normalizePublicBaseUrl(config.publicDomain) && getEnvPublicBaseUrl()) {
        config.publicDomain = getEnvPublicBaseUrl();
        await saveFile(CONFIG_PATH, config);
        log(`Seeded publicDomain from PUBLIC_BASE_URL=${config.publicDomain}`);
    }
    refreshRuntimePublicBaseUrl(config);
    if (!config.clientId || config.clientId.startsWith('smp-') || config.clientId === 'plex-expiry-manager-client-id') {
        config.clientId = randomUUID();
        await saveFile(CONFIG_PATH, config);
        log(`Generated stable Plex clientId ${config.clientId}`);
    }
    if (!process.env.CLIENT_ID) {
        CLIENT_ID = config.clientId;
    } else {
        CLIENT_ID = process.env.CLIENT_ID;
        if (config.clientId !== CLIENT_ID) {
            config.clientId = CLIENT_ID;
            await saveFile(CONFIG_PATH, config);
        }
    }
    // Publish identity to process.env so every Python/child worker (Collexions, Poster Sets)
    // inherits the same durable Plex client — never the Docker hostname/MAC.
    process.env.CLIENT_ID = CLIENT_ID;
    process.env.PLEX_CLIENT_IDENTIFIER = CLIENT_ID;
    process.env.PLEXAPI_HEADER_IDENTIFIER = CLIENT_ID;
    process.env.PLEXAPI_HEADER_PRODUCT = 'StreamPilot';
    process.env.PLEXAPI_HEADER_DEVICE = 'Server';
    process.env.PLEXAPI_HEADER_DEVICE_NAME = 'StreamPilot';
    process.env.PLEXAPI_HEADER_PLATFORM = 'StreamPilot';
    log(`Plex client identity: product=StreamPilot clientId=${String(CLIENT_ID).slice(0, 8)}…`);
    await syncAdminPlexIdFromConfigToken(config, { persist: true });
    const runStartupBrandingSync = async (label = 'startup') => {
        try {
            const profile = await getAdminProfile(config);
            const result = await refreshPortalBrandingAssets(config, profile);
            if (!result?.synced) {
                log(`[Branding] ${label} icon sync skipped or deferred`);
            }
        } catch (error) {
            log(`[Branding] ${label} icon sync failed: ${error.message}`);
        }
    };
    void runStartupBrandingSync('startup');
    setTimeout(() => { void runStartupBrandingSync('startup-retry'); }, 45000);

    await loadStatusState();
    runMonitorCycle();
    setInterval(runMonitorCycle, 15000);
    monitorConcurrentSessions();
    setInterval(monitorConcurrentSessions, 15000);
    startBackgroundService();
    loadFile(CONFIG_PATH, {}).then(async (bootConfig) => {
        const bootWithId = { ...(bootConfig || {}), clientId: CLIENT_ID || bootConfig?.clientId };
        try {
            const { config: withCollexions, changed } = applyCollexionsBundledDefaults(bootWithId, {
                configDir: CONFIG_DIR,
                log,
            });
            if (changed) {
                await saveFile(CONFIG_PATH, withCollexions);
            }
            let autostartRun = !!withCollexions.collexionsAutostart;
            let collexionsIntervalMs = 180 * 60 * 1000;
            let markPinningJobStart = autostartRun;
            try {
                const hints = await readCollexionsRunHints(CONFIG_DIR);
                collexionsIntervalMs = hints.intervalMs || collexionsIntervalMs;
                autostartRun = shouldStartCollexionsPinningLoop({
                    autostartEnabled: !!withCollexions.collexionsAutostart,
                    status: hints.status,
                    interrupted: hints.interrupted,
                });
                const stored = await getJob(JOB_IDS.collexionsPinning);
                const merged = mergeJobWithExternal(stored, hints);
                let decision = decideBootRun(merged, { intervalMs: collexionsIntervalMs });
                if (decision.action !== 'resume' && !hints.interrupted && hints.nextRunTs) {
                    const dueMs = hints.nextRunTs * 1000;
                    if (dueMs > Date.now()) {
                        decision = {
                            action: 'skip',
                            delayMs: dueMs - Date.now(),
                            reason: 'worker-next-run',
                            nextRunAt: new Date(dueMs).toISOString(),
                        };
                    }
                }
                // Never fold "not due yet" into autostart=false — that left pinning
                // Stopped after every StreamPilot/container update until someone clicked Start.
                if (!autostartRun) {
                    log('[collexions] boot: pinning loop stays stopped (not running before restart)');
                } else if (decision.action === 'skip') {
                    log(`[collexions] boot: restarting pinning loop, first cycle waits ${formatDelay(decision.delayMs)}`);
                    if (merged.lastCompletedAt) {
                        await updateJob(JOB_IDS.collexionsPinning, {
                            status: 'completed',
                            lastCompletedAt: merged.lastCompletedAt,
                            lastStartedAt: merged.lastStartedAt,
                            intervalMs: hints.intervalMs,
                            checkpoint: null,
                        }).catch(() => {});
                    }
                } else if (decision.action === 'resume') {
                    log('[collexions] boot: resuming interrupted pinning run');
                }
                markPinningJobStart = autostartRun && decision.action !== 'skip';
            } catch (hintError) {
                log(`[collexions] boot schedule check failed: ${hintError.message}`);
            }
            await syncCollexionsEmbeddedWorker(withCollexions, {
                configDir: CONFIG_DIR,
                log,
                autostartRun,
            });
            if (markPinningJobStart) {
                await markJobStart(JOB_IDS.collexionsPinning, { intervalMs: collexionsIntervalMs }).catch(() => {});
            }
        } catch (e) {
            log(`[collexions] Startup embedded worker sync failed: ${e.message}`);
        }
        try {
            const latest = await loadFile(CONFIG_PATH, bootWithId);
            const { config: withSpotifyBundled, changed: spotifyBundledChanged } = applySpotifyToPlexBundledDefaults(latest, {
                configDir: CONFIG_DIR,
                log,
            });
            let bootSpotifyConfig = withSpotifyBundled;
            if (spotifyBundledChanged) {
                await saveFile(CONFIG_PATH, withSpotifyBundled);
            }
            try {
                syncSpotifyToPlexPlexConfigFile(bootSpotifyConfig, spotifyToPlexPortalDefaultsDeps());
            } catch (e) {
                log(`[spotify-sync] Portal Plex config file sync on boot failed: ${e.message}`);
            }
            await syncSpotifyToPlexEmbeddedWorker(bootSpotifyConfig, { configDir: CONFIG_DIR, log });
            try {
                const portalDefaults = await applySpotifyToPlexPortalDefaults(bootSpotifyConfig, spotifyToPlexPortalDefaultsDeps());
                if (portalDefaults.applied?.length) {
                    log(`[spotify-sync] ${portalDefaults.message}`);
                }
            } catch (e) {
                log(`[spotify-sync] Portal Plex/Lidarr apply on boot failed: ${e.message}`);
            }
        } catch (e) {
            log(`[spotify-sync] Startup bundled worker sync failed: ${e.message}`);
        }
        // Phase 4: Discover prefs are portal-owned — skip Seerr settings sync on boot.
    });
    startPlexStatsBackgroundTask(); // start 24-hour library size cache task

    // Background cache builders: reuse on-disk cache and schedule next run by interval.
    startTrendingStatsBackgroundTask();
    startAnalyticsStatsBackgroundTask();
    startAchievementsBackfillBackgroundTask();
    startPersonalAnalyticsWarmBackgroundTask();
    startUpgraderIndexBackgroundTask();
    startPortalRequestStatusSyncBackgroundTask();
    startSeerrAvailableNotifyBackgroundTask();
    startSeerrPendingNotifyBackgroundTask();
    startSpotifySyncBackgroundTask();
    startDiscoveryAvailabilityCacheBackgroundTask();
    startScannerWorker(async () => scannerPortalConfig(await loadFile(CONFIG_PATH, {})));
    setScannerFailureNotify((payload) => {
        const folder = payload?.folder || 'unknown path';
        const error = payload?.error || 'Scanner failed';
        const label = payload?.title ? `${payload.title}: ${error}` : `${folder}: ${error}`;
        const noTargets = payload?.kind === 'no-targets';
        return notifyOps('scanner_failed', {
            title: label,
            body: error,
            dedupeKey: noTargets ? 'scanner:no-targets' : `scanner:${folder}`,
            cooldownMs: noTargets ? 6 * 60 * 60 * 1000 : undefined,
        });
    });
    setCollexionsFailureNotify((payload) => notifyOps('collexions_failed', {
        title: payload?.message || 'ColleXions failed',
        dedupeKey: `collexions:${payload?.signature || payload?.message || 'failed'}`,
    }));
    setCollexionsUnexpectedExitHandler(({ code, signal }) => notifyOps('collexions_failed', {
        title: `ColleXions could not recover (exit code ${code})`,
        body: 'The portal tried to restart ColleXions automatically. Open ColleXions or check portal logs if this keeps happening.',
        dedupeKey: `collexions:exit-unrecoverable:${code}:${signal || 'none'}`,
        cooldownMs: 2 * 60 * 60 * 1000,
    }));
    startCollexionsStatusWatcher({
        configDir: CONFIG_DIR,
        getEnabled: async () => {
            const cfg = await loadFile(CONFIG_PATH, {});
            return !!cfg.collexionsEnabled;
        },
    });
    setSpotifyToPlexFailureNotify((payload) => notifyOps('spotify_sync_failed', {
        title: payload?.failures?.map((f) => `${f.type}: ${f.message}`).join(' · ') || 'Spotify Sync failed',
        dedupeKey: `spotify-sync:${payload?.signature || 'failed'}`,
    }));
    setSpotifyToPlexUnexpectedExitHandler(({ code, signal }) => notifyOps('spotify_sync_failed', {
        title: signal === 'SIGKILL'
            ? 'Spotify Sync worker was killed (SIGKILL). This is usually the OS reclaiming memory.'
            : `Bundled spotify-to-plex exited (code=${code}, signal=${signal || 'none'})`,
        dedupeKey: `spotify-sync:exit:${code}:${signal || 'none'}`,
    }));
    void (async () => {
        try {
            const cfg = await loadFile(CONFIG_PATH, {});
            if (!cfg.spotifyToPlexEnabled) return;
            if (isSpotifyToPlexBundledAvailable() && isUsingBundledSpotifyToPlexUrl(cfg)) {
                return;
            }
            try {
                syncSpotifyToPlexPlexConfigFile(cfg, spotifyToPlexPortalDefaultsDeps());
            } catch (error) {
                log(`[spotify-sync] Portal Plex config file sync on external boot failed: ${error.message}`);
            }
            await syncSpotifyToPlexSupervisorConfig(cfg, { configDir: CONFIG_DIR, log });
            try {
                await applySpotifyToPlexPortalDefaults(cfg, spotifyToPlexPortalDefaultsDeps());
            } catch (error) {
                log(`[spotify-sync] Portal Plex/Lidarr apply on external boot failed: ${error.message}`);
            }
        } catch (error) {
            log(`[spotify-sync] external boot sync failed: ${error.message}`);
        }
    })();
    startSpotifyToPlexStatusWatcher({
        loadConfig: async () => loadFile(CONFIG_PATH, {}),
        fetchWithTimeout,
        allowPrivate: ALLOW_PRIVATE_INTEGRATION_URLS,
        getEnabled: async (cfg) => !!cfg?.spotifyToPlexEnabled,
    });
    void refreshScannerAuthCache();
    try {
        setPosterSetsNotifyDigest(async ({ title, message }) => {
            const config = await loadFile(CONFIG_PATH, {});
            await sendGotifyAlert(config, title || 'Poster Sets watcher', message || '');
        });
        startPosterSetsWatcher({
            resolveFirstPassDelayMs: async () => {
                const stored = await getJob(JOB_IDS.posterSetsWatcher);
                const intervalMs = stored.intervalMs || 6 * 60 * 60 * 1000;
                const decision = decideBootRun(stored, { intervalMs });
                if (decision.action === 'skip') {
                    log(`[poster-sets] boot: skipping watcher pass, next in ${formatDelay(decision.delayMs)}`);
                    return decision.delayMs;
                }
                if (decision.action === 'resume') {
                    log('[poster-sets] boot: resuming watcher pass');
                }
                return 20_000;
            },
        });
        startTpdbCacheDailyRefresh();
        log('[poster-sets] Watcher scheduled');
        log('[poster-sets] TPDB cache refresh scheduler started');
    } catch (error) {
        log(`[poster-sets] Watcher startup failed: ${error.message}`);
    }
    try {
        const overlaysSchedDeps = {
            loadPortalConfig: async () => loadFile(CONFIG_PATH, {}),
            resolvePlex: resolveOverlaysPlex,
            isFeatureEnabled: async () => {
                const cfg = await loadFile(CONFIG_PATH, {});
                return !!cfg.overlaysEnabled;
            },
            markTaskStart,
            markTaskEnd,
        };
        startOverlaysScheduler({
            ...overlaysSchedDeps,
            systemJob: systemJobs.overlaysNewSeason,
        });
        startOverlaysBundleScheduler('recently', {
            ...overlaysSchedDeps,
            systemJob: systemJobs.overlaysRecentlyAdded,
        });
        startOverlaysBundleScheduler('kometa', {
            ...overlaysSchedDeps,
            systemJob: systemJobs.overlaysKometaStyle,
        });
        log('[overlays] Core / Recently Added / Kometa schedulers started');
    } catch (error) {
        log(`[overlays] Scheduler startup failed: ${error.message}`);
    }
    try {
        startEditionsScheduler({
            loadPortalConfig: async () => loadFile(CONFIG_PATH, {}),
            resolvePlex: resolveOverlaysPlex,
            markTaskStart,
            markTaskEnd,
            systemJob: systemJobs.editionsProcess,
            log,
        });
        log('[editions] Full-run scheduler started');
    } catch (error) {
        log(`[editions] Scheduler startup failed: ${error.message}`);
    }
    try {
        startWatchSyncScheduler({
            loadPortalConfig: async () => loadFile(CONFIG_PATH, {}),
            resolvePlex: resolveWatchSyncPlex,
            markTaskStart,
            markTaskEnd,
            systemJob: systemJobs.watchSync,
            log,
        });
        log('[watch-sync] Scheduler started');
        startLiveWatch({
            loadPortalConfig: async () => loadFile(CONFIG_PATH, {}),
            resolvePlex: resolveWatchSyncPlex,
            log,
        });
        log('[watch-sync] Live scrobble watcher started');
    } catch (error) {
        log(`[watch-sync] Scheduler startup failed: ${error.message}`);
    }
    // Never block portal boot on Media Automation (watcher/scans can hang on big mounts).
    void mediaAutomationService.start()
        .then(() => refreshMediaAutomationAuthCache())
        .catch((error) => log(`[media-automation] Worker startup failed: ${error.message}`));
    if (!mediaAutomationWatchOptIn()) {
        log('[media-automation] Filesystem watcher disabled unless MEDIA_AUTOMATION_ENABLE_WATCH=1');
    }
    const MAINTENANCE_INDEX_INTERVAL_MS = 6 * 60 * 60 * 1000;
    const runMaintenanceIndexIfEnabled = async (reason) => {
        try {
            const cfg = await loadFile(CONFIG_PATH, {});
            if (!isMediaQualityIndexEnabled(cfg)) return;
            await buildMaintenanceMediaIndex({ actor: { username: 'System', email: 'system@local' }, force: false });
        } catch (e) {
            log(`${reason === 'startup' || reason === 'resume' ? 'Initial' : 'Scheduled'} media quality index build failed: ${e.message}`);
        }
    };
    void (async () => {
        let existingGeneratedAt = null;
        try {
            const existing = await loadFile(MAINTENANCE_MEDIA_INDEX_PATH, null);
            existingGeneratedAt = existing?.generatedAt || null;
        } catch { /* no index yet */ }
        const stored = mergeJobWithExternal(await getJob(JOB_IDS.maintenanceIndex), {
            lastCompletedAt: existingGeneratedAt,
        });
        const decision = decideBootRun(stored, { intervalMs: MAINTENANCE_INDEX_INTERVAL_MS });
        applyJobToTask(systemJobs.maintenanceIndex, stored, { intervalMs: MAINTENANCE_INDEX_INTERVAL_MS });
        const delay = decision.action === 'skip' ? decision.delayMs : 20_000;
        if (decision.action === 'skip') {
            log(`boot: skipping maintenanceIndex, next in ${formatDelay(decision.delayMs)}`);
        } else if (decision.action === 'resume') {
            log('boot: resuming maintenanceIndex');
        }
        systemJobs.maintenanceIndex.nextRun = new Date(Date.now() + delay).toISOString();
        setTimeout(() => { void runMaintenanceIndexIfEnabled(decision.action === 'skip' ? 'scheduled' : decision.action); }, delay);
        setInterval(() => {
            systemJobs.maintenanceIndex.nextRun = new Date(Date.now() + MAINTENANCE_INDEX_INTERVAL_MS).toISOString();
            void runMaintenanceIndexIfEnabled('scheduled');
        }, MAINTENANCE_INDEX_INTERVAL_MS);
    })();

    const backupConfig = await loadFile(CONFIG_PATH, {});
    systemJobs.autoBackup.nextRun = backupConfig.autoBackupEnabled ? computeNextBackupRun(backupConfig) : null;
    // Check every hour whether an auto backup is due.
    setInterval(async () => {
        const cfg = await loadFile(CONFIG_PATH, {});
        if (!cfg.autoBackupEnabled) {
            systemJobs.autoBackup.nextRun = null;
            return;
        }
        const nextRunTs = Date.parse(computeNextBackupRun(cfg));
        systemJobs.autoBackup.nextRun = new Date(nextRunTs).toISOString();
        if (Date.now() >= nextRunTs) {
            await runAutoBackupCycle('scheduled');
        }
    }, 60 * 60 * 1000);
});
